export default "(the admin \\\"add user\\\" flow) may always\\n    # create users. For every other caller this endpoint is effectively\\n    # unauthenticated, so refuse it unless public sign up is intended for this\\n    # deployment. get_current_user_optional returns None for credential-less\\n    # requests, so the anonymous path can never be promoted to superuser.\\n    is_superuser_caller = current_user is not None and current_user.is_active and current_user.is_superuser\\n    if not is_superuser_caller and (auth_settings.AUTO_LOGIN or not auth_settings.ENABLE_SIGNUP):\\n        await _audit_deny(\\n            user_id=current_user.id if current_user is not None else None,\\n            action=\\\"user:create\\\",\\n            obj=\\\"user:*\\\",\\n            status_code=403,\\n            reason=\\\"public_registration_disabled\\\",\\n        )\\n        raise HTTPException(status_code=403, detail=\\\"Public user registration is disabled.\\\")\\n\\n    new_user = User.model_validate(user, from_attributes=True)\\n    authorization_service = get_authorization_service()\\n    try:\\n        new_user.password = get_auth_service().get_password_hash(user.password)\\n        new_user.is_active = settings_service.auth_settings.NEW_USER_IS_ACTIVE\\n        await acquire_identity_mutation_lock(\\n            authorization_service,\\n            session,\\n            kind=AuthorizationMutationKind.USER_CREATED,\\n            entity_id=new_user.id,\\n            affected_user_ids=(new_user.id,),\\n        )\\n        session.add(new_user)\\n        await session.flush()\\n        await session.refresh(new_user)\\n        folder = await get_or_create_default_folder(session, new_user.id)\\n        if not folder:\\n            await session.rollback()\\n            await _audit_deny(\\n                user_id=current_user.id if current_user is not None else None,\\n                action=\\\"user:create\\\",\\n                obj=f\\\"user:{new_user.id}\\\",\\n                status_code=500,\\n                reason=\\\"default_project_creation_failed\\\",\\n            )\\n            raise HTTPException(status_code=500, detail=\\\"Error creating default project\\\")\\n    except IntegrityError as e:\\n        await session.rollback()\\n        await _audit_deny(\\n            user_id=current_user.id if current_user is not None else None,\\n            action=\\\"user:create\\\",\\n            obj=\\\"user:*\\\",\\n            status_code=400,\\n            reason=\\\"username_unavailable\\\",\\n        )\\n        raise HTTPException(status_code=400, detail=\\\"This username is unavailable.\\\") from e\\n\\n    lifecycle_mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.USER_CREATED,\\n        entity_id=new_user.id,\\n        actor_user_id=current_user.id if current_user is not None else None,\\n        affected_user_ids=(new_user.id,),\\n        policy_relevant_fields=(\\\"is_active\\\", \\\"is_superuser\\\"),\\n        user_before=None,\\n        user_after=UserAuthorizationSnapshot(\\n            is_active=new_user.is_active,\\n            is_superuser=new_user.is_superuser,\\n        ),\\n    )\\n    audit_details = {\\n        \\\"event\\\": AUDIT_EVENT_MUTATION,\\n        \\\"created_by\\\": \\\"admin\\\" if is_superuser_caller else \\\"signup\\\",\\n    }\\n    try:\\n        await stage_identity_mutation(authorization_service, session, lifecycle_mutation)\\n        audit_staged = stage_audit_decision(\\n            session=session,\\n            user_id=current_user.id if current_user is not None else new_user.id,\\n            action=\\\"user:create\\\",\\n            obj=f\\\"user:{new_user.id}\\\",\\n            result=\\\"allow\\\",\\n            details=audit_details,\\n        )\\n        await session.commit()\\n    except Exception:\\n        await session.rollback()\\n        raise\\n\\n    await safe_identity_mutation_committed(authorization_service, lifecycle_mutation)\\n    if not audit_staged:\\n        await audit_decision(\\n            user_id=current_user.id if current_user is not None else new_user.id,\\n            action=\\\"user:create\\\",\\n            obj=f\\\"user:{new_user.id}\\\",\\n            result=\\\"allow\\\",\\n            details=audit_details,\\n        )\\n    return new_user\\n\\n\\n@router.get(\\\"/whoami\\\", response_model=UserRead)\\nasync def read_current_user(\\n    current_user: CurrentActiveUser,\\n) -> User:\\n    \\\"\\\"\\\"Retrieve the current user's data.\\\"\\\"\\\"\\n    return current_user\\n\\n\\n@router.get(\\\"/\\\", dependencies=[Depends(get_current_active_superuser)])\\nasync def read_all_users(\\n    *,\\n    skip: int = 0,\\n    limit: int = 10,\\n    search: str | None = None,\\n    session: DbSession,\\n) -> UsersResponse:\\n    \\\"\\\"\\\"Retrieve a list of users from the database with pagination.\\\"\\\"\\\"\\n    query: SelectOfScalar = select(User)\\n    count_query = select(func.count()).select_from(User)\\n\\n    if search:\\n        search_filter = User.username.ilike(f\\\"%{escape_like_pattern(search)}%\\\", escape=\\\"\\\\\\\\\\\")  # type: ignore[attr-defined]\\n        query = query.where(search_filter)\\n        count_query = count_query.where(search_filter)\\n\\n    query = query.offset(skip).limit(limit)\\n    users = (await session.exec(query)).fetchall()\\n    total_count = (await session.exec(count_query)).first()\\n\\n    return UsersResponse(\\n        total_count=total_count,\\n        users=[UserRead(**user.model_dump()) for user in users],\\n    )\\n\\n\\n@router.patch(\\\"/{user_id}\\\", response_model=UserRead)\\nasync def patch_user(\\n    user_id: UUID,\\n    user_update: UserUpdate,\\n    user: CurrentActiveUser,\\n    session: DbSession,\\n) -> User:\\n    \\\"\\\"\\\"Update an existing user's data.\\\"\\\"\\\"\\n    update_password = bool(user_update.password)\\n\\n    # Prevent users from deactivating their own account to avoid lockout\\n    if user.id == user_id and user_update.is_active is False:\\n        await _audit_deny(\\n            user_id=user.id,\\n            action=\\\"user:update\\\",\\n            obj=f\\\"user:{user_id}\\\",\\n            status_code=403,\\n            reason=\\\"self_deactivation_forbidden\\\",\\n        )\\n        raise HTTPException(status_code=403, detail=\\\"You can't deactivate your own user account\\\")\\n\\n    if not user.is_superuser and user_update.is_superuser:\\n        await _audit_deny(\\n            user_id=user.id,\\n            action=\\\"user:update\\\",\\n            obj=f\\\"user:{user_id}\\\",\\n            status_code=403,\\n            reason=\\\"superuser_required\\\",\\n        )\\n        raise HTTPException(status_code=403, detail=\\\"Permission denied\\\")\\n\\n    if not user.is_superuser and user.id != user_id:\\n        await _audit_deny(\\n            user_id=user.id,\\n            action=\\\"user:update\\\",\\n            obj=f\\\"user:{user_id}\\\",\\n            status_code=403,\\n            reason=\\\"cross_user_update_forbidden\\\",\\n        )\\n        raise HTTPException(status_code=403, detail=\\\"Permission denied\\\")\\n    if update_password:\\n        if not user.is_superuser:\\n            await _audit_deny(\\n                user_id=user.id,\\n                action=\\\"user:update\\\",\\n                obj=f\\\"user:{user_id}\\\",\\n                status_code=400,\\n                reason=\\\"password_update_forbidden\\\",\\n            )\\n            raise HTTPException(status_code=400, detail=\\\"You can't change your password here\\\")\\n        user_update.password = get_auth_service().get_password_hash(user_update.password)\\n\\n    authorization_service = get_authorization_service()\\n    # Pre-read lock hint; canonical user state may produce a different staged kind.\\n    possible_lifecycle_kind: AuthorizationMutationKind | None = None\\n    if user_update.is_active is False:\\n        possible_lifecycle_kind = AuthorizationMutationKind.USER_DISABLED\\n    elif user_update.is_superuser is False:\\n        possible_lifecycle_kind = AuthorizationMutationKind.USER_SUPERUSER_DEMOTED\\n    if possible_lifecycle_kind is not None:\\n        await acquire_identity_mutation_lock(\\n            authorization_service,\\n            session,\\n            kind=possible_lifecycle_kind,\\n            entity_id=user_id,\\n            affected_user_ids=(user_id,),\\n        )\\n\\n    if user_db := await get_user_by_id(session, user_id):\\n        lifecycle_mutation: AuthorizationMutation | None = None\\n        fields_changed = sorted(\\n            field\\n            for field in user_update.model_fields_set\\n            if field != \\\"password\\\"\\n            and getattr(user_update, field) is not None\\n            and getattr(user_db, field, None) != getattr(user_update, field)\\n        )\\n        next_is_active = user_db.is_active if user_update.is_active is None else user_update.is_active\\n        next_is_superuser = user_db.is_superuser if user_update.is_superuser is None else user_update.is_superuser\\n        if user_db.is_active and not next_is_active:\\n            lifecycle_kind = AuthorizationMutationKind.USER_DISABLED\\n        elif user_db.is_superuser and not next_is_superuser:\\n            lifecycle_kind = AuthorizationMutationKind.USER_SUPERUSER_DEMOTED\\n        else:\\n            lifecycle_kind = None\\n\\n        if lifecycle_kind is not None:\\n            policy_relevant_fields = tuple(\\n                field\\n                for field, before, after in (\\n                    (\\\"is_active\\\", user_db.is_active, next_is_active),\\n                    (\\\"is_superuser\\\", user_db.is_superuser, next_is_superuser),\\n                )\\n                if before != after\\n            )\\n            lifecycle_mutation = AuthorizationMutation(\\n                kind=lifecycle_kind,\\n                entity_id=user_db.id,\\n                actor_user_id=user.id,\\n                affected_user_ids=(user_db.id,),\\n                policy_relevant_fields=policy_relevant_fields,\\n                user_before=UserAuthorizationSnapshot(\\n                    is_active=user_db.is_active,\\n                    is_superuser=user_db.is_superuser,\\n                ),\\n                user_after=UserAuthorizationSnapshot(\\n                    is_active=next_is_active,\\n                    is_superuser=next_is_superuser,\\n                ),\\n            )\\n            try:\\n                await validate_identity_mutation(authorization_service, session, lifecycle_mutation)\\n            except AuthorizationMutationRejected as exc:\\n                raise HTTPException(status_code=409, detail=exc.public_detail) from exc\\n\\n        if not update_password:\\n            user_update.password = user_db.password\\n        try:\\n            updated_user = await update_user(user_db, user_update, session)\\n        except HTTPException as exc:\\n            await _audit_deny(\\n                user_id=user.id,\\n                action=\\\"user:update\\\",\\n                obj=f\\\"user:{user_id}\\\",\\n                status_code=exc.status_code,\\n                reason=\\\"update_rejected\\\",\\n            )\\n            raise\\n        if lifecycle_mutation is not None:\\n            await stage_identity_mutation(authorization_service, session, lifecycle_mutation)\\n        audit_details = {\\n            \\\"event\\\": AUDIT_EVENT_MUTATION,\\n            \\\"fields_changed\\\": fields_changed,\\n            \\\"lifecycle_kind\\\": lifecycle_mutation.kind.value if lifecycle_mutation is not None else None,\\n        }\\n        try:\\n            audit_staged = stage_audit_decision(\\n                session=session,\\n                user_id=user.id,\\n                action=\\\"user:update\\\",\\n                obj=f\\\"user:{user_db.id}\\\",\\n                result=\\\"allow\\\",\\n                details=audit_details,\\n            )\\n            await session.commit()\\n        except Exception:\\n            await session.rollback()\\n            raise\\n        if lifecycle_mutation is not None:\\n            await safe_identity_mutation_committed(authorization_service, lifecycle_mutation)\\n        if not audit_staged:\\n            await audit_decision(\\n                user_id=user.id,\\n                action=\\\"user:update\\\",\\n                obj=f\\\"user:{user_db.id}\\\",\\n                result=\\\"allow\\\",\\n                details=audit_details,\\n            )\\n        return updated_user\\n    await _audit_deny(\\n        user_id=user.id,\\n        action=\\\"user:update\\\",\\n        obj=f\\\"user:{user_id}\\\",\\n        status_code=404,\\n        reason=\\\"user_not_found\\\",\\n    )\\n    raise HTTPException(status_code=404, detail=\\\"User not found\\\")\\n\\n\\n@router.patch(\\\"/{user_id}/reset-password\\\", response_model=UserRead)\\nasync def reset_password(\\n    user_id: UUID,\\n    password_reset: PasswordResetRequest,\\n    user: CurrentActiveUser,\\n    session: DbSession,\\n) -> User:\\n    \\\"\\\"\\\"Change the current user's password after verifying the existing password.\\\"\\\"\\\"\\n    if user_id != user.id:\\n        raise HTTPException(status_code=404, detail=\\\"You can't change another user's password\\\")\\n\\n    if not user:\\n        raise HTTPException(status_code=404, detail=\\\"User not found\\\")\\n\\n    auth = get_auth_service()\\n    if not auth.verify_password(password_reset.current_password, user.password):\\n        raise HTTPException(status_code=400, detail=\\\"Current password is incorrect\\\")\\n\\n    if auth.verify_password(password_reset.password, user.password):\\n        raise HTTPException(status_code=400, detail=\\\"You can't use your current password\\\")\\n\\n    new_password = auth.get_password_hash(password_reset.password)\\n    user.password = new_password\\n\\n    await session.flush()\\n    await session.refresh(user)\\n\\n    return user\\n\\n\\n@router.delete(\\\"/{user_id}\\\")\\nasync def delete_user(\\n    user_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> dict:\\n    \\\"\\\"\\\"Delete a user from the database.\\\"\\\"\\\"\\n    if current_user.id == user_id:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"user:delete\\\",\\n            obj=f\\\"user:{user_id}\\\",\\n            status_code=400,\\n            reason=\\\"self_deletion_forbidden\\\",\\n        )\\n        raise HTTPException(status_code=400, detail=\\\"You can't delete your own user account\\\")\\n    if not current_user.is_superuser:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"user:delete\\\",\\n            obj=f\\\"user:{user_id}\\\",\\n            status_code=403,\\n            reason=\\\"superuser_required\\\",\\n        )\\n        raise HTTPException(status_code=403, detail=\\\"Permission denied\\\")\\n\\n    authorization_service = get_authorization_service()\\n    await acquire_identity_mutation_lock(\\n        authorization_service,\\n        session,\\n        kind=AuthorizationMutationKind.USER_DELETED,\\n        entity_id=user_id,\\n        affected_user_ids=(user_id,),\\n    )\\n    stmt = select(User).where(User.id == user_id)\\n    user_db = (await session.exec(stmt)).first()\\n    if not user_db:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"user:delete\\\",\\n            obj=f\\\"user:{user_id}\\\",\\n            status_code=404,\\n            reason=\\\"user_not_found\\\",\\n        )\\n        raise HTTPException(status_code=404, detail=\\\"User not found\\\")\\n\\n    lifecycle_mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.USER_DELETED,\\n        entity_id=user_db.id,\\n        actor_user_id=current_user.id,\\n        affected_user_ids=(user_db.id,),\\n        policy_relevant_fields=(\\\"is_active\\\", \\\"is_superuser\\\"),\\n        user_before=UserAuthorizationSnapshot(\\n            is_active=user_db.is_active,\\n            is_superuser=user_db.is_superuser,\\n        ),\\n        user_after=None,\\n    )\\n    try:\\n        await validate_identity_mutation(authorization_service, session, lifecycle_mutation)\\n    except AuthorizationMutationRejected as exc:\\n        raise HTTPException(status_code=409, detail=exc.public_detail) from exc\\n\\n    # IMPORTANT:\\n    # This endpoint intentionally performs a DB-cascade delete only and does\\n    # not issue provider-side teardown across all user deployments.\\n    # The trade-off is to avoid destructive bulk deletion of external\\n    # deployment resources during user deletion.\\n    await session.delete(user_db)\\n    await session.flush()\\n    await stage_identity_mutation(authorization_service, session, lifecycle_mutation)\\n    audit_details = {\\n        \\\"event\\\": AUDIT_EVENT_MUTATION,\\n        \\\"target_was_active\\\": lifecycle_mutation.user_before.is_active,\\n        \\\"target_was_superuser\\\": lifecycle_mutation.user_before.is_superuser,\\n    }\\n    audit_staged = stage_audit_decision(\\n        session=session,\\n        user_id=current_user.id,\\n        action=\\\"user:delete\\\",\\n        obj=f\\\"user:{user_id}\\\",\\n        result=\\\"allow\\\",\\n        details=audit_details,\\n    )\\n    await session.commit()\\n    await safe_identity_mutation_committed(authorization_service, lifecycle_mutation)\\n    if not audit_staged:\\n        await audit_decision(\\n            user_id=current_user.id,\\n            action=\\\"user:delete\\\",\\n            obj=f\\\"user:{user_id}\\\",\\n            result=\\\"allow\\\",\\n            details=audit_details,\\n        )\\n    return {\\\"detail\\\": \\\"User deleted\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/validate.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"60f5887fb8c6824017d34679bd6eff5a247a9a51c1a719f94d6630074cab2fb9\",\"content\":\"from fastapi import APIRouter, Depends, HTTPException\\nfrom lfx.base.prompts.api_utils import process_prompt_template\\nfrom lfx.custom.validate import validate_code\\nfrom lfx.log.logger import logger\\n\\nfrom langflow.api.utils import CurrentActiveUser\\nfrom langflow.api.v1.base import Code, CodeValidationResponse, PromptValidationResponse, ValidatePromptRequest\\nfrom langflow.api.v1.custom_component_policy import resolve_component_code_for_action\\nfrom langflow.services.auth.utils import get_current_active_user\\nfrom langflow.services.deps import get_catalog_policy_service, get_settings_service\\n\\n# build router\\nrouter = APIRouter(prefix=\\\"/validate\\\", tags=[\\\"Validate\\\"])\\n\\n\\n@router.post(\\\"/code\\\", status_code=200, include_in_schema=False)\\nasync def post_validate_code(code: Code, user: CurrentActiveUser) -> CodeValidationResponse:\\n    effective_code = resolve_component_code_for_action(\\n        code.code,\\n        user=user,\\n        settings=get_settings_service().settings,\\n        snapshot=get_catalog_policy_service().snapshot,\\n        disabled_detail=\\\"Custom component validation is disabled\\\",\\n        admin_only_detail=\\\"Custom component validation is restricted to administrators\\\",\\n    )\\n    try:\\n        errors = validate_code(effective_code)\\n        return CodeValidationResponse(\\n            imports=errors.get(\\\"imports\\\", {}),\\n            function=errors.get(\\\"function\\\", {}),\\n        )\\n    except Exception as e:\\n        logger.debug(\\\"Error validating code\\\", exc_info=True)\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.post(\\\"/prompt\\\", status_code=200, dependencies=[Depends(get_current_active_user)], include_in_schema=False)\\nasync def post_validate_prompt(\\n    prompt_request: ValidatePromptRequest,\\n) -> PromptValidationResponse:\\n    try:\\n        if not prompt_request.frontend_node:\\n            return PromptValidationResponse(\\n                input_variables=[],\\n                frontend_node=None,\\n            )\\n\\n        # Process the prompt template using direct attributes\\n        input_variables = process_prompt_template(\\n            template=prompt_request.template,\\n            name=prompt_request.name,\\n            custom_fields=prompt_request.frontend_node.custom_fields,\\n            frontend_node_template=prompt_request.frontend_node.template,\\n            is_mustache=prompt_request.mustache,\\n        )\\n\\n        return PromptValidationResponse(\\n            input_variables=input_variables,\\n            frontend_node=prompt_request.frontend_node,\\n        )\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/variable.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6dc32930f7155016cdeb8026a820eb58ee3d10fc17ab130e6ee58fdad0bd33de\",\"content\":\"import asyncio\\nimport json\\nimport logging\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, HTTPException\\nfrom lfx.base.models.unified_models import (\\n    get_all_variables_for_provider,\\n    get_model_provider_variable_mapping,\\n    get_model_providers,\\n    get_provider_all_variables,\\n    validate_model_provider_key,\\n)\\nfrom lfx.services.model_provider_policy import ModelProviderPolicyPurpose\\nfrom sqlalchemy.exc import NoResultFound\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.v1.model_provider_policy_scope import ProviderPolicyAttributesDependency\\nfrom langflow.api.v1.models import (\\n    DISABLED_MODELS_VAR,\\n    ENABLED_MODELS_VAR,\\n    _aresolve_policy,\\n    _require_provider,\\n    build_model_providers_by_name,\\n    get_provider_from_variable_name,\\n    normalize_model_status_entries,\\n)\\nfrom langflow.api.v1.schemas.deployments import DetectVarsRequest, DetectVarsResponse\\nfrom langflow.services.authorization import VariableAction, ensure_variable_permission\\nfrom langflow.services.authorization.fetch import authorized_or_owner_scoped, deny_to_404\\nfrom langflow.services.authorization.listing import visible_scope_prefilter\\nfrom langflow.services.database.models.flow_version.crud import get_flow_version_entries_by_ids\\nfrom langflow.services.database.models.variable.model import Variable, VariableCreate, VariableRead, VariableUpdate\\nfrom langflow.services.deps import get_variable_service\\nfrom langflow.services.variable.constants import CREDENTIAL_TYPE, GENERIC_TYPE\\nfrom langflow.services.variable.service import DatabaseVariableService, has_variable_value\\n\\nrouter = APIRouter(prefix=\\\"/variables\\\", tags=[\\\"Variables\\\"])\\nlogger = logging.getLogger(__name__)\\n\\n\\nasync def _cleanup_model_list_variable(\\n    variable_service: DatabaseVariableService,\\n    user_id: UUID,\\n    variable_name: str,\\n    provider: str,\\n    providers_by_name: dict[str, set[str]],\\n    session: DbSession,\\n) -> None:\\n    \\\"\\\"\\\"Remove one provider's models from a persisted model-status variable.\\n\\n    If all models are removed, the variable is deleted entirely.\\n    If the variable doesn't exist, this is a no-op.\\n    \\\"\\\"\\\"\\n    try:\\n        model_list_var = await variable_service.get_variable_object(\\n            user_id=user_id, name=variable_name, session=session\\n        )\\n    except ValueError:\\n        # Variable doesn't exist, nothing to clean up\\n        return\\n\\n    if not model_list_var or not model_list_var.value:\\n        return\\n\\n    # Parse current models\\n    try:\\n        parsed_value = json.loads(model_list_var.value)\\n        current_models = (\\n            {str(item) for item in parsed_value if isinstance(item, str)} if isinstance(parsed_value, list) else set()\\n        )\\n    except (json.JSONDecodeError, TypeError):\\n        current_models = set()\\n\\n    # Migrate known legacy bare names first so shared aliases retain the other\\n    # provider identities, then remove only the deleted provider's qualified\\n    # entries (including live/custom deployment names absent from the catalog).\\n    normalized_models = normalize_model_status_entries(current_models, providers_by_name)\\n    provider_prefix = f\\\"{provider}::\\\"\\n    filtered_models = {model for model in normalized_models if not model.startswith(provider_prefix)}\\n\\n    # Nothing changed, no update needed\\n    if filtered_models == current_models:\\n        return\\n\\n    if filtered_models:\\n        # Update with filtered list\\n        if model_list_var.id is not None:\\n            await variable_service.update_variable_fields(\\n                user_id=user_id,\\n                variable_id=model_list_var.id,\\n                variable=VariableUpdate(\\n                    id=model_list_var.id,\\n                    name=variable_name,\\n                    value=json.dumps(list(filtered_models)),\\n                    type=GENERIC_TYPE,\\n                ),\\n                session=session,\\n            )\\n    else:\\n        # No models left, delete the variable\\n        await variable_service.delete_variable(user_id=user_id, name=variable_name, session=session)\\n\\n\\nasync def _cleanup_provider_models(\\n    variable_service: DatabaseVariableService,\\n    user_id: UUID,\\n    provider: str,\\n    session: DbSession,\\n) -> None:\\n    \\\"\\\"\\\"Clean up disabled and enabled model lists for a deleted provider credential.\\\"\\\"\\\"\\n    try:\\n        providers_by_name = build_model_providers_by_name()\\n    except ValueError:\\n        logger.exception(\\\"Provider model retrieval failed\\\")\\n        return\\n\\n    # Clean up disabled and enabled models\\n    await _cleanup_model_list_variable(\\n        variable_service,\\n        user_id,\\n        DISABLED_MODELS_VAR,\\n        provider,\\n        providers_by_name,\\n        session,\\n    )\\n    await _cleanup_model_list_variable(\\n        variable_service,\\n        user_id,\\n        ENABLED_MODELS_VAR,\\n        provider,\\n        providers_by_name,\\n        session,\\n    )\\n\\n\\n@router.post(\\\"/\\\", response_model=VariableRead, status_code=201, include_in_schema=False)\\nasync def create_variable(\\n    *,\\n    session: DbSession,\\n    variable: VariableCreate,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n):\\n    \\\"\\\"\\\"Create a new variable.\\\"\\\"\\\"\\n    await ensure_variable_permission(\\n        current_user,\\n        VariableAction.CREATE,\\n        variable_user_id=current_user.id,\\n    )\\n    variable_service = get_variable_service()\\n    if not variable.name and not variable.value:\\n        raise HTTPException(status_code=400, detail=\\\"Variable name and value cannot be empty\\\")\\n\\n    if not variable.name:\\n        raise HTTPException(status_code=400, detail=\\\"Variable name cannot be empty\\\")\\n\\n    if not variable.value:\\n        raise HTTPException(status_code=400, detail=\\\"Variable value cannot be empty\\\")\\n\\n    # Provider variables contributed by core or extensions are policy-gated\\n    # before credential lookup, SDK import, validation, or persistence.\\n    provider = get_provider_from_variable_name(variable.name)\\n    if provider is not None:\\n        await _require_provider(\\n            current_user,\\n            provider,\\n            ModelProviderPolicyPurpose.CONFIGURE,\\n            provider_policy_attributes,\\n        )\\n\\n    if variable.name in await variable_service.list_variables(user_id=current_user.id, session=session):\\n        raise HTTPException(status_code=400, detail=\\\"Variable name already exists\\\")\\n\\n    if provider is not None and variable.name == get_model_provider_variable_mapping().get(provider):\\n        provider_vars = await asyncio.to_thread(get_all_variables_for_provider, current_user.id, provider)\\n        try:\\n            await asyncio.to_thread(\\n                validate_model_provider_key,\\n                provider,\\n                {**provider_vars, variable.name: variable.value},\\n            )\\n        except ValueError as e:\\n            raise HTTPException(status_code=400, detail=str(e)) from e\\n\\n    try:\\n        created_variable = await variable_service.create_variable(\\n            user_id=current_user.id,\\n            name=variable.name,\\n            value=variable.value,\\n            default_fields=variable.default_fields or [],\\n            type_=variable.type or CREDENTIAL_TYPE,\\n            session=session,\\n        )\\n    except Exception as e:\\n        if isinstance(e, HTTPException):\\n            raise\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n    else:\\n        response = VariableRead.model_validate(created_variable, from_attributes=True)\\n        response.has_value = has_variable_value(created_variable)\\n        response.is_owner = True\\n        response.can_manage_shares = True\\n        return response\\n\\n\\n@router.get(\\\"/\\\", response_model=list[VariableRead], status_code=200, include_in_schema=False)\\nasync def read_variables(\\n    *,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n):\\n    \\\"\\\"\\\"Read all variables.\\n\\n    Model provider credentials are validated when they are created or updated,\\n    not on every read. This avoids latency from external API calls on read operations.\\n\\n    Returns a list of variables.\\n    \\\"\\\"\\\"\\n    await ensure_variable_permission(\\n        current_user,\\n        VariableAction.READ,\\n        variable_user_id=current_user.id,\\n    )\\n    provider_policy = await _aresolve_policy(\\n        current_user,\\n        ModelProviderPolicyPurpose.CONFIGURE,\\n        provider_policy_attributes,\\n    )\\n    variable_service = get_variable_service()\\n    if not isinstance(variable_service, DatabaseVariableService):\\n        msg = \\\"Variable service is not an instance of DatabaseVariableService\\\"\\n        raise TypeError(msg)\\n    try:\\n        visibility = await visible_scope_prefilter(\\n            current_user,\\n            resource_type=\\\"variable\\\",\\n            act=VariableAction.READ,\\n        )\\n        resettable_provider_variables = {\\n            variable[\\\"variable_key\\\"]\\n            for provider in get_model_providers()\\n            for variable in get_provider_all_variables(provider)\\n            if not variable.get(\\\"required\\\")\\n            and not variable.get(\\\"is_secret\\\")\\n            and isinstance(variable.get(\\\"variable_key\\\"), str)\\n        }\\n        all_variables = await variable_service.get_all(\\n            user_id=current_user.id,\\n            session=session,\\n            visibility=visibility,\\n            include_empty_names=resettable_provider_variables,\\n        )\\n\\n        # Filter out internal variables (those starting and ending with __)\\n        filtered_variables = []\\n        for var in all_variables:\\n            if var.name and var.name.startswith(\\\"__\\\") and var.name.endswith(\\\"__\\\"):\\n                continue\\n            provider = get_provider_from_variable_name(var.name) if var.name else None\\n            if provider is not None and not provider_policy.allows(provider):\\n                continue\\n            filtered_variables.append(var)\\n\\n        # Mark model provider credentials - validation status is based on existence\\n        # (actual validation happens on create/update)\\n        primary_provider_variables = set(get_model_provider_variable_mapping().values())\\n        for var in filtered_variables:\\n            if var.name and var.name in primary_provider_variables and var.type == CREDENTIAL_TYPE:\\n                # Credential exists and was validated on save\\n                var.is_valid = True\\n                var.validation_error = None\\n            else:\\n                # Not a model provider credential\\n                var.is_valid = None\\n                var.validation_error = None\\n\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n    else:\\n        return filtered_variables\\n\\n\\n@router.patch(\\\"/{variable_id}\\\", response_model=VariableRead, status_code=200, include_in_schema=False)\\nasync def update_variable(\\n    *,\\n    session: DbSession,\\n    variable_id: UUID,\\n    variable: VariableUpdate,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n):\\n    \\\"\\\"\\\"Update a variable.\\\"\\\"\\\"\\n    variable_service = get_variable_service()\\n    if not isinstance(variable_service, DatabaseVariableService):\\n        msg = \\\"Variable service is not an instance of DatabaseVariableService\\\"\\n        raise TypeError(msg)\\n    try:\\n        # Share-aware fetch: load by id when a plugin enables cross-user fetch,\\n        # otherwise scope to the owner (OSS default \u2014 behavior unchanged).\\n        existing_variable = await authorized_or_owner_scoped(\\n            session,\\n            Variable,\\n            id_column=Variable.id,\\n            resource_id=variable_id,\\n            owner_column=Variable.user_id,\\n            owner_id=current_user.id,\\n        )\\n        if existing_variable is None:\\n            raise HTTPException(status_code=404, detail=\\\"Variable not found\\\")\\n        # Pass the *resource* owner so the owner-override only fast-paths the real\\n        # owner; a non-owner falls through to the plugin's enforce(). Plugin deny\\n        # \u2192 404 (UUID privacy), matching the flow/deployment routes.\\n        owner_id = existing_variable.user_id\\n        try:\\n            await ensure_variable_permission(\\n                current_user,\\n                VariableAction.WRITE,\\n                variable_id=variable_id,\\n                variable_user_id=owner_id,\\n            )\\n        except HTTPException as exc:\\n            raise deny_to_404(exc, detail=\\\"Variable not found\\\") from exc\\n\\n        # Validate provider variables using their effective post-update name.\\n        # This closes the rename path from a generic variable into a hidden\\n        # provider credential while still allowing rename/delete cleanup.\\n        effective_name = variable.name or existing_variable.name\\n        provider = get_provider_from_variable_name(effective_name)\\n        if provider is not None:\\n            await _require_provider(\\n                current_user,\\n                provider,\\n                ModelProviderPolicyPurpose.CONFIGURE,\\n                provider_policy_attributes,\\n            )\\n            if variable.value and effective_name == get_model_provider_variable_mapping().get(provider):\\n                # Run validation off the event loop; owner context (not caller) for share-aware updates.\\n                provider_vars = await asyncio.to_thread(get_all_variables_for_provider, owner_id, provider)\\n                try:\\n                    await asyncio.to_thread(\\n                        validate_model_provider_key,\\n                        provider,\\n                        {**provider_vars, effective_name: variable.value},\\n                    )\\n                except ValueError as e:\\n                    raise HTTPException(status_code=400, detail=str(e)) from e\\n\\n        # Mutate against the resolved owner so the owner-scoped service query\\n        # matches the row a share-aware fetch resolved.\\n        updated_variable = await variable_service.update_variable_fields(\\n            user_id=owner_id,\\n            variable_id=variable_id,\\n            variable=variable,\\n            session=session,\\n        )\\n        is_owner = str(owner_id) == str(current_user.id)\\n        response = VariableRead.model_validate(updated_variable, from_attributes=True)\\n        response.has_value = has_variable_value(updated_variable)\\n        response.is_owner = is_owner\\n        response.can_manage_shares = is_owner\\n        # A shared variable may be used by runtime resolution, but mutation\\n        # responses must never disclose the owner's existing stored value when\\n        # a recipient patches metadata or omits ``value`` entirely.\\n        if not is_owner:\\n            response.value = None\\n    except NoResultFound as e:\\n        raise HTTPException(status_code=404, detail=\\\"Variable not found\\\") from e\\n    except ValueError as e:\\n        raise HTTPException(status_code=404, detail=\\\"Variable not found\\\") from e\\n    except Exception as e:\\n        if isinstance(e, HTTPException):\\n            raise\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n    else:\\n        return response\\n\\n\\n@router.delete(\\\"/{variable_id}\\\", status_code=204, include_in_schema=False)\\nasync def delete_variable(\\n    *,\\n    session: DbSession,\\n    variable_id: UUID,\\n    current_user: CurrentActiveUser,\\n    _provider_policy_attributes: ProviderPolicyAttributesDependency,\\n) -> None:\\n    \\\"\\\"\\\"Delete a variable.\\n\\n    If the deleted variable is a model provider credential (e.g., OPENAI_API_KEY),\\n    all disabled models for that provider are automatically cleared.\\n    \\\"\\\"\\\"\\n    variable_service = get_variable_service()\\n    try:\\n        # Share-aware fetch (see update_variable): load by id when a plugin\\n        # enables cross-user fetch, else owner-scoped (OSS default).\\n        variable_to_delete = await authorized_or_owner_scoped(\\n            session,\\n            Variable,\\n            id_column=Variable.id,\\n            resource_id=variable_id,\\n            owner_column=Variable.user_id,\\n            owner_id=current_user.id,\\n        )\\n        if variable_to_delete is None:\\n            raise HTTPException(status_code=404, detail=\\\"Variable not found\\\")\\n        owner_id = variable_to_delete.user_id\\n        try:\\n            await ensure_variable_permission(\\n                current_user,\\n                VariableAction.DELETE,\\n                variable_id=variable_id,\\n                variable_user_id=owner_id,\\n            )\\n        except HTTPException as exc:\\n            raise deny_to_404(exc, detail=\\\"Variable not found\\\") from exc\\n\\n        # Check if this variable is a model provider credential\\n        provider = get_provider_from_variable_name(variable_to_delete.name)\\n\\n        # Delete the variable, scoped to the resolved owner so a shared delete\\n        # removes the owner's row.\\n        await variable_service.delete_variable_by_id(user_id=owner_id, variable_id=variable_id, session=session)\\n\\n        # If this was a provider credential, clean up the *owner's* disabled and\\n        # enabled model lists for that provider.\\n        if provider and isinstance(variable_service, DatabaseVariableService):\\n            await _cleanup_provider_models(variable_service, owner_id, provider, session)\\n\\n    except Exception as e:\\n        # Preserve 404 / deny_to_404 (and any other HTTPException) instead of\\n        # masking it as a 500.\\n        if isinstance(e, HTTPException):\\n            raise\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\ndef _collect_candidate_variable_keys_from_flow_data(data: dict) -> set[str]:\\n    \\\"\\\"\\\"Collect explicit global-variable keys from flow data.\\\"\\\"\\\"\\n    candidate_keys: set[str] = set()\\n\\n    for node in data.get(\\\"nodes\\\", []):\\n        template = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n        if not isinstance(template, dict):\\n            continue\\n        for field in template.values():\\n            if not isinstance(field, dict):\\n                continue\\n            if field.get(\\\"load_from_db\\\") is True:\\n                var_name = field.get(\\\"value\\\")\\n                normalized_var_name = var_name.strip() if isinstance(var_name, str) else None\\n                if normalized_var_name:\\n                    candidate_keys.add(normalized_var_name)\\n\\n    return candidate_keys\\n\\n\\ndef _validate_flow_or_422(*, version_id: UUID, data: object) -> dict:\\n    \\\"\\\"\\\"Validate flow version data structure and raise HTTP 422 on malformed input.\\\"\\\"\\\"\\n    if not (isinstance(data, dict) and \\\"nodes\\\" in data and isinstance(data[\\\"nodes\\\"], list)):\\n        raise HTTPException(\\n            status_code=422,\\n            detail=(\\n                f\\\"Flow version {version_id} data must be a JSON object with a 'nodes' list containing node templates.\\\"\\n            ),\\n        )\\n    return data\\n\\n\\n@router.post(\\\"/detections\\\", response_model=DetectVarsResponse, include_in_schema=False)\\nasync def detect_env_vars(\\n    payload: DetectVarsRequest,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n):\\n    \\\"\\\"\\\"Detect global variable references used by the given flow version IDs.\\n\\n    Candidates are inferred only from ``load_from_db=True`` fields, where\\n    the field value is interpreted as the referenced global variable name.\\n\\n    Returned values are cross-checked against the user's existing global\\n    variable names. This is a security guardrail: it prevents echoing arbitrary\\n    template values (including accidental secrets) and ensures results are\\n    actual stored global variables.\\n    \\\"\\\"\\\"\\n    await ensure_variable_permission(\\n        current_user,\\n        VariableAction.READ,\\n        variable_user_id=current_user.id,\\n    )\\n    provider_policy = await _aresolve_policy(\\n        current_user,\\n        ModelProviderPolicyPurpose.CONFIGURE,\\n        provider_policy_attributes,\\n    )\\n    variable_service = get_variable_service()\\n    existing_variable_names = {\\n        name\\n        for name in await variable_service.list_variables(user_id=current_user.id, session=session)\\n        if isinstance(name, str) and name\\n    }\\n\\n    candidate_keys: set[str] = set()\\n    versions_by_id = await get_flow_version_entries_by_ids(\\n        session,\\n        version_ids=payload.flow_version_ids,\\n        user_id=current_user.id,\\n    )\\n\\n    for version_id in payload.flow_version_ids:\\n        version = versions_by_id.get(version_id)\\n        if version is None:\\n            raise HTTPException(status_code=404, detail=f\\\"Flow version {version_id} not found\\\")\\n\\n        data = _validate_flow_or_422(version_id=version_id, data=version.data)\\n        candidate_keys.update(_collect_candidate_variable_keys_from_flow_data(data))\\n\\n    visible_candidate_keys = {\\n        variable_key\\n        for variable_key in candidate_keys\\n        if (provider := get_provider_from_variable_name(variable_key)) is None or provider_policy.allows(provider)\\n    }\\n\\n    return DetectVarsResponse(variables=sorted(existing_variable_names.intersection(visible_candidate_keys)))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/voice_mode.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"78936aac6a64b75baaa45a28cd15c53f1711fd26b66a68c1d6049578a97838d8\",\"content\":\"import asyncio\\nimport base64\\nimport json\\nimport os\\nimport time\\nimport traceback\\nimport uuid\\nfrom collections import defaultdict\\nfrom contextlib import ExitStack\\nfrom datetime import datetime, timezone\\nfrom functools import lru_cache, partial\\nfrom typing import Any\\nfrom uuid import UUID, uuid4\\n\\nimport numpy as np\\nimport requests\\nimport sqlalchemy\\nimport websockets\\nfrom cryptography.fernet import InvalidToken\\nfrom elevenlabs import ElevenLabs\\nfrom fastapi import APIRouter, BackgroundTasks, HTTPException\\nfrom lfx.log import logger\\nfrom lfx.observability import execution_protocol\\nfrom lfx.schema.schema import InputValueRequest\\nfrom lfx.services.model_provider_policy import (\\n    ModelProviderPolicyError,\\n    ModelProviderPolicyPurpose,\\n    aresolve_model_provider_policy,\\n)\\nfrom lfx.utils.secrets import secret_value_to_str\\nfrom sqlmodel import select\\nfrom starlette.websockets import WebSocket, WebSocketDisconnect\\nfrom websockets.asyncio.client import ClientConnection\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.v1.chat import build_flow_and_stream\\nfrom langflow.api.v1.flows_helpers import _read_flow\\nfrom langflow.memory import aadd_messagetables\\nfrom langflow.schema.properties import Properties\\nfrom langflow.services.auth.utils import get_current_user_for_websocket\\nfrom langflow.services.authorization import FlowAction, VoiceAction, ensure_flow_permission, ensure_voice_permission\\nfrom langflow.services.authorization.fetch import deny_to_404\\nfrom langflow.services.database.models.flow.model import AccessTypeEnum, Flow\\nfrom langflow.services.database.models.message.model import MessageTable\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_variable_service\\nfrom langflow.services.model_provider_policy_scope import scoped_model_provider_policy_for_flow\\nfrom langflow.utils.voice_utils import BYTES_PER_24K_FRAME, VAD_SAMPLE_RATE_16K, resample_24k_to_16k\\n\\nrouter = APIRouter(prefix=\\\"/voice\\\", tags=[\\\"Voice\\\"], include_in_schema=False)\\n\\n\\nSILENCE_THRESHOLD = 0.1\\nPREFIX_PADDING_MS = 100\\nSILENCE_DURATION_MS = 300\\nAUDIO_SAMPLE_THRESHOLD = 100\\nSESSION_INSTRUCTIONS = \\\"\\\"\\\"\\nYour instructions will be divided into three mutually exclusive sections: \\\"Permanent\\\", \\\"Default\\\", and \\\"Additional\\\".\\n\\\"Permanent\\\" instructions are to never be overrided, superceded or otherwise ignored.\\n\\\"Default\\\" instructions are provided by default. They may never override \\\"Permanent\\\"\\n  or \\\"Additional\\\" instructions, and they may likewise be superceded by those same other rules.\\n\\\"Additional\\\" instructions may be empty. When relevant, they override \\\"Default\\\" instructions,\\n  but never \\\"Permanent\\\" instructions.\\n\\n[PERMANENT] The following instructions are to be considered \\\"Permanent\\\"\\n* When the user's query necessitates use of one of the enumerated tools, call the execute_flow\\n  function to assist, and pass in the user's entire query as the input parameter, and use that\\n  to craft your responses.\\n* No other function is allowed to be registered besides the execute_flow function\\n\\n[DEFAULT] The following instructions are to be considered only \\\"Default\\\"\\n* Converse with the user to assist with their question.\\n* Never provide URLs in repsonses, but you may use URLs in tool calls or when processing those\\n  URLs' content.\\n* Always (and I mean *always*) let the user know before you will be\\n  doing so.\\n* Always update the user with the required information, when the function returns.\\n* Unless otherwise requested, only summarize the return results. Do not repeat everything.\\n* Always call the function again when requested, regardless of whether execute_flow previously\\n  succeeded or failed.\\n* Never provide URLs in repsonses, but you may use URLs in tool calls or when processing those\\n  URLs' content.\\n\\n[ADDITIONAL] The following instructions are to be considered only \\\"Additional\\\"\\n\\\"\\\"\\\"\\n\\nLF_TO_OPENAI = \\\"LF \u2192 OpenAI\\\"\\nLF_TO_CLIENT = \\\"LF \u2192 Client\\\"\\nOPENAI_TO_LF = \\\"OpenAI \u2192 LF\\\"\\nCLIENT_TO_LF = \\\"Client \u2192 LF\\\"\\n# --- Helper Functions ---\\n\\n\\n@lru_cache(maxsize=1)\\ndef get_vad():\\n    import webrtcvad\\n\\n    return webrtcvad.Vad(mode=3)\\n\\n\\nasync def authenticate_and_get_openai_key(session: DbSession, user: User, websocket: WebSocket):\\n    \\\"\\\"\\\"Authenticate the user using a token or API key and retrieve the OpenAI API key.\\n\\n    Returns a tuple: (current_user, openai_key). If authentication fails, sends an error\\n    message to the client and returns (None, None).\\n    \\\"\\\"\\\"\\n    if user is None:\\n        await websocket.send_json(\\n            {\\n                \\\"type\\\": \\\"error\\\",\\n                \\\"code\\\": \\\"langflow_auth\\\",\\n                \\\"message\\\": \\\"You must pass a valid Langflow token or cookie.\\\",\\n            }\\n        )\\n        return None, None\\n\\n    try:\\n        provider_policy = await aresolve_model_provider_policy(\\n            user_id=user.id,\\n            providers=[\\\"OpenAI\\\"],\\n            purpose=ModelProviderPolicyPurpose.USE,\\n        )\\n        provider_policy.require(\\\"OpenAI\\\")\\n    except ModelProviderPolicyError as exc:\\n        await websocket.send_json(\\n            {\\n                \\\"type\\\": \\\"error\\\",\\n                \\\"code\\\": exc.code,\\n                \\\"message\\\": str(exc),\\n            }\\n        )\\n        return None, None\\n\\n    variable_service = get_variable_service()\\n    try:\\n        openai_key_value = await variable_service.get_variable(\\n            user_id=user.id, name=\\\"OPENAI_API_KEY\\\", field=\\\"openai_api_key\\\", session=session\\n        )\\n        openai_key = secret_value_to_str(openai_key_value) or os.getenv(\\\"OPENAI_API_KEY\\\", \\\"\\\")\\n        if not openai_key or openai_key == \\\"dummy\\\":\\n            await websocket.send_json(\\n                {\\n                    \\\"type\\\": \\\"error\\\",\\n                    \\\"code\\\": \\\"api_key_missing\\\",\\n                    \\\"key_name\\\": \\\"OPENAI_API_KEY\\\",\\n                    \\\"message\\\": \\\"OpenAI API key not found. Please set your API key as an env var or a global variable.\\\",\\n                }\\n            )\\n            return None, None\\n    except Exception as e:  # noqa: BLE001\\n        await logger.aerror(f\\\"Error with API key: {e}\\\")\\n        await logger.aerror(traceback.format_exc())\\n        return None, None\\n    return user, openai_key\\n\\n\\nclass VoiceConfig:\\n    def __init__(self, session_id: str):\\n        self.session_id = session_id\\n        self.use_elevenlabs = False\\n        self.elevenlabs_voice = \\\"JBFqnCBsd6RMkjVDRZzb\\\"\\n        self.elevenlabs_model = \\\"eleven_multilingual_v2\\\"\\n        self.elevenlabs_client = None\\n        self.elevenlabs_key = None\\n        self._barge_in_enabled = False\\n        self.progress_enabled = True\\n\\n        self.default_openai_realtime_session = {\\n            \\\"modalities\\\": [\\\"text\\\", \\\"audio\\\"],\\n            \\\"instructions\\\": SESSION_INSTRUCTIONS,\\n            \\\"voice\\\": \\\"echo\\\",\\n            \\\"temperature\\\": 0.8,\\n            \\\"input_audio_format\\\": \\\"pcm16\\\",\\n            \\\"output_audio_format\\\": \\\"pcm16\\\",\\n            \\\"turn_detection\\\": {\\n                \\\"type\\\": \\\"server_vad\\\",\\n                \\\"threshold\\\": SILENCE_THRESHOLD,\\n                \\\"prefix_padding_ms\\\": PREFIX_PADDING_MS,\\n                \\\"silence_duration_ms\\\": SILENCE_DURATION_MS,\\n            },\\n            \\\"input_audio_transcription\\\": {\\\"model\\\": \\\"whisper-1\\\"},\\n            \\\"tools\\\": [],\\n            \\\"tool_choice\\\": \\\"auto\\\",\\n        }\\n        self.openai_realtime_session: dict[str, Any] = {}\\n\\n    @property\\n    def barge_in_enabled(self):\\n        # Later on we may want to tie this value\\n        # to the availability of the webrtcvad package.\\n        return self._barge_in_enabled\\n\\n    def get_session_dict(self):\\n        return dict(self.default_openai_realtime_session)\\n\\n\\ndef get_voice_config(session_id: str, user_id: UUID | None = None) -> VoiceConfig:\\n    if session_id is None:\\n        msg = \\\"session_id cannot be None\\\"\\n        raise ValueError(msg)\\n    # Key the cache by (user_id, session_id). session_id is client-supplied (the\\n    # human chat-session name), so keying on it alone let two different users\\n    # collide on the same session and share cached config/clients across tenants.\\n    # Binding the key to the authenticated user prevents that.\\n    cache_key = (user_id, session_id)\\n    if cache_key not in voice_config_cache:\\n        voice_config_cache[cache_key] = VoiceConfig(session_id)\\n    return voice_config_cache[cache_key]\\n\\n\\nclass TTSConfig:\\n    def __init__(self, session_id: str, openai_key: str):\\n        try:\\n            from openai import OpenAI\\n        except ImportError as exc:\\n            msg = \\\"Voice mode requires the OpenAI SDK. Install it with `pip install 'langflow-base[audio]'`.\\\"\\n            raise ImportError(msg) from exc\\n\\n        self.session_id = session_id\\n        self.use_elevenlabs = False\\n        self.elevenlabs_voice = \\\"JBFqnCBsd6RMkjVDRZzb\\\"\\n        self.elevenlabs_model = \\\"eleven_multilingual_v2\\\"\\n        self.elevenlabs_client = None\\n        self.default_tts_session = {\\n            \\\"type\\\": \\\"transcription_session.update\\\",\\n            \\\"session\\\": {\\n                \\\"input_audio_format\\\": \\\"pcm16\\\",\\n                \\\"input_audio_transcription\\\": {\\n                    \\\"model\\\": \\\"gpt-4o-transcribe\\\",\\n                    \\\"language\\\": \\\"en\\\",\\n                },\\n                \\\"turn_detection\\\": {\\n                    \\\"type\\\": \\\"server_vad\\\",\\n                    \\\"threshold\\\": SILENCE_THRESHOLD,\\n                    \\\"prefix_padding_ms\\\": PREFIX_PADDING_MS,\\n                    \\\"silence_duration_ms\\\": SILENCE_DURATION_MS,\\n                },\\n                \\\"input_audio_noise_reduction\\\": {\\\"type\\\": \\\"near_field\\\"},\\n                \\\"include\\\": [],\\n            },\\n        }\\n        self.tts_session: dict[str, Any] = {}\\n        self.oai_client = OpenAI(api_key=openai_key)\\n        self.openai_voice = \\\"echo\\\"\\n\\n    def get_session_dict(self):\\n        return dict(self.default_tts_session)\\n\\n    def get_openai_client(self):\\n        return self.oai_client\\n\\n    def get_openai_voice(self):\\n        return self.openai_voice\\n\\n\\ndef get_tts_config(session_id: str, openai_key: str, user_id: UUID | None = None) -> TTSConfig:\\n    if session_id is None:\\n        msg = \\\"session_id cannot be None\\\"\\n        raise ValueError(msg)\\n    # Key by (user_id, session_id) so a client-supplied session_id cannot make one\\n    # user reuse another user's cached TTSConfig \u2014 which holds an OpenAI client\\n    # built from that other user's key.\\n    cache_key = (user_id, session_id)\\n    if cache_key not in tts_config_cache:\\n        tts_config_cache[cache_key] = TTSConfig(session_id, openai_key)\\n    return tts_config_cache[cache_key]\\n\\n\\nasync def add_message_to_db(message, session, flow_id, session_id, sender, sender_name):\\n    \\\"\\\"\\\"Enforce alternating sequence by checking the last sender.\\n\\n    If two consecutive messages come from the same party (e.g. AI/AI), wait briefly.\\n    \\\"\\\"\\\"\\n    queue_key = f\\\"{flow_id}:{session_id}\\\"\\n\\n    # If the incoming sender is the same as the last recorded sender,\\n    # wait for a change (with a timeout as a fallback).\\n    if last_sender_by_session[queue_key] == sender:\\n        await wait_for_sender_change(queue_key, sender, timeout=5)\\n    last_sender_by_session[queue_key] = sender\\n\\n    # Now proceed to create the message\\n    message_obj = MessageTable(\\n        text=message,\\n        sender=sender,\\n        sender_name=sender_name,\\n        session_id=session_id,\\n        files=[],\\n        flow_id=uuid.UUID(flow_id) if isinstance(flow_id, str) else flow_id,\\n        properties=Properties().model_dump(),\\n        content_blocks=[],\\n        category=\\\"message\\\",\\n    )\\n\\n    await message_queues[queue_key].put(message_obj)\\n    # Update last sender for this session\\n\\n    if queue_key not in message_tasks or message_tasks[queue_key].done():\\n        message_tasks[queue_key] = asyncio.create_task(process_message_queue(queue_key, session))\\n\\n\\nasync def wait_for_sender_change(queue_key, current_sender, timeout=5):\\n    \\\"\\\"\\\"Wait until the last sender for this session is not the same as current_sender.\\n\\n    or until the timeout expires.\\n    \\\"\\\"\\\"\\n    waited = 0\\n    interval = 0.05\\n    while last_sender_by_session[queue_key] == current_sender and waited < timeout:\\n        await asyncio.sleep(interval)\\n        waited += interval\\n\\n\\nasync def process_message_queue(queue_key, session):\\n    \\\"\\\"\\\"Process messages from the queue one by one.\\\"\\\"\\\"\\n    try:\\n        while True:\\n            message = await message_queues[queue_key].get()\\n\\n            try:\\n                await aadd_messagetables([message], session)\\n                await logger.adebug(f\\\"Added message to DB: {message.text[:30]}...\\\")\\n            except ValueError as e:\\n                await logger.aerror(f\\\"Error saving message to database (ValueError): {e}\\\")\\n                await logger.aerror(traceback.format_exc())\\n            except sqlalchemy.exc.SQLAlchemyError as e:\\n                await logger.aerror(f\\\"Error saving message to database (SQLAlchemyError): {e}\\\")\\n                await logger.aerror(traceback.format_exc())\\n            except (KeyError, AttributeError, TypeError) as e:\\n                # More specific exceptions instead of blind Exception\\n                await logger.aerror(f\\\"Error saving message to database: {e}\\\")\\n                await logger.aerror(traceback.format_exc())\\n            finally:\\n                message_queues[queue_key].task_done()\\n\\n            if message_queues[queue_key].empty():\\n                break\\n    except Exception as e:  # noqa: BLE001\\n        await logger.adebug(f\\\"Message queue processor for {queue_key} was cancelled: {e}\\\")\\n        await logger.aerror(traceback.format_exc())\\n\\n\\nclass SendQueues:\\n    def __init__(self, openai_ws: ClientConnection, client_ws: WebSocket, log_event):\\n        self.openai_ws: ClientConnection = openai_ws\\n        self.openai_send_q: asyncio.Queue[tuple] = asyncio.Queue()\\n        self.openai_writer_task: asyncio.Task = asyncio.create_task(self.__openai_writer())\\n\\n        self.block: asyncio.Event = asyncio.Event()\\n        self.block.set()\\n\\n        self.client_ws: WebSocket = client_ws\\n        self.client_send_q: asyncio.Queue[dict] = asyncio.Queue()\\n        self.client_writer_task: asyncio.Task = asyncio.create_task(self.__client_writer())\\n        self.log_event = log_event\\n\\n    def openai_send(self, payload, *, is_blocking=False):\\n        try:\\n            self.openai_send_q.put_nowait([payload, is_blocking])\\n        except Exception:  # noqa: BLE001\\n            logger.error(traceback.format_exc())\\n\\n    def openai_unblock(self):\\n        logger.trace(\\\"OPENAI UNBLOCKING\\\")\\n        self.block.set()\\n\\n    async def __openai_writer(self):\\n        try:\\n            while True:\\n                msg, is_blocking = await self.openai_send_q.get()\\n                if msg is None:\\n                    break\\n                await self.block.wait()\\n                await self.openai_ws.send(json.dumps(msg))\\n                self.log_event(msg, LF_TO_OPENAI)\\n                if is_blocking:\\n                    self.block.clear()\\n                    logger.trace(\\\"OPENAI BLOCKING\\\")\\n                # log_event(msg, DIRECTION_TO_OPENAI)\\n        except Exception:  # noqa: BLE001\\n            await logger.aerror(traceback.format_exc())\\n\\n    def client_send(self, payload):\\n        try:\\n            self.client_send_q.put_nowait(payload)\\n            self.log_event(payload, LF_TO_OPENAI)\\n        except Exception:  # noqa: BLE001\\n            logger.error(traceback.format_exc())\\n\\n    async def __client_writer(self):\\n        try:\\n            while True:\\n                msg = await self.client_send_q.get()\\n                if msg is None:\\n                    break\\n                self.log_event(msg, LF_TO_CLIENT)\\n                await self.client_ws.send_text(json.dumps(msg))\\n        except Exception:  # noqa: BLE001\\n            await logger.aerror(traceback.format_exc())\\n\\n    async def close(self):\\n        self.openai_send_q.put_nowait(None)\\n        self.client_send_q.put_nowait(None)\\n        await self.openai_writer_task\\n        await self.client_writer_task\\n\\n\\ndef get_create_response(send_handler: SendQueues, session_id, user_id=None):\\n    def create_response(original: dict | None = None):\\n        msg = {}\\n        if original is not None:\\n            msg = original\\n        msg[\\\"type\\\"] = \\\"response.create\\\"\\n        voice_config = get_voice_config(session_id, user_id)\\n        if voice_config.use_elevenlabs:\\n            response = msg.setdefault(\\\"response\\\", {})\\n            response[\\\"modalities\\\"] = [\\\"text\\\"]\\n        send_handler.openai_send(payload=msg, is_blocking=True)\\n\\n    return create_response\\n\\n\\nasync def handle_function_call(\\n    function_call: dict,\\n    function_call_args: str,\\n    flow_id: str,\\n    background_tasks: BackgroundTasks,\\n    current_user: CurrentActiveUser,\\n    conversation_id: str,\\n    session_id: str,\\n    msg_handler: SendQueues,\\n):\\n    create_response = get_create_response(msg_handler, session_id, current_user.id)\\n    \\\"\\\"\\\"Handle function calls from the OpenAI API.\\\"\\\"\\\"\\n    try:\\n        args = json.loads(function_call_args) if function_call_args else {}\\n        input_request = InputValueRequest(\\n            input_value=args.get(\\\"input\\\"), components=[], type=\\\"chat\\\", session=conversation_id\\n        )\\n        # Bound around the call, not the drain: the build task is created inside and copies the\\n        # context then, so the drain below runs outside the scope without losing the label.\\n        with execution_protocol(\\\"voice\\\"):\\n            response = await build_flow_and_stream(\\n                flow_id=UUID(flow_id),\\n                inputs=input_request,\\n                background_tasks=background_tasks,\\n                current_user=current_user,\\n            )\\n        result = \\\"\\\"\\n        async for line in response.body_iterator:\\n            if not line:\\n                continue\\n            event_data = json.loads(line)\\n            msg_handler.client_send({\\\"type\\\": \\\"flow.build.progress\\\", \\\"data\\\": event_data})\\n            if event_data.get(\\\"event\\\") == \\\"end_vertex\\\":\\n                text_part = (\\n                    event_data.get(\\\"data\\\", {})\\n                    .get(\\\"build_data\\\", \\\"\\\")\\n                    .get(\\\"data\\\", {})\\n                    .get(\\\"results\\\", {})\\n                    .get(\\\"message\\\", {})\\n                    .get(\\\"text\\\", \\\"\\\")\\n                )\\n                result += text_part\\n        function_output = {\\n            \\\"type\\\": \\\"conversation.item.create\\\",\\n            \\\"item\\\": {\\n                \\\"type\\\": \\\"function_call_output\\\",\\n                \\\"call_id\\\": function_call.get(\\\"call_id\\\"),\\n                \\\"output\\\": str(result),\\n            },\\n        }\\n        msg_handler.openai_send(function_output)\\n        create_response()\\n    except json.JSONDecodeError as e:\\n        trace = traceback.format_exc()\\n        await logger.aerror(f\\\"JSON decode error: {e!s}\\\\ntrace: {trace}\\\")\\n        function_output = {\\n            \\\"type\\\": \\\"conversation.item.create\\\",\\n            \\\"item\\\": {\\n                \\\"type\\\": \\\"function_call_output\\\",\\n                \\\"call_id\\\": function_call.get(\\\"call_id\\\"),\\n                \\\"output\\\": f\\\"Error parsing arguments: {e!s}\\\",\\n            },\\n        }\\n        msg_handler.openai_send(function_output)\\n    except ValueError as e:\\n        trace = traceback.format_exc()\\n        await logger.aerror(f\\\"Value error: {e!s}\\\\ntrace: {trace}\\\")\\n        function_output = {\\n            \\\"type\\\": \\\"conversation.item.create\\\",\\n            \\\"item\\\": {\\n                \\\"type\\\": \\\"function_call_output\\\",\\n                \\\"call_id\\\": function_call.get(\\\"call_id\\\"),\\n                \\\"output\\\": f\\\"Error with input values: {e!s}\\\",\\n            },\\n        }\\n        msg_handler.openai_send(function_output)\\n    except (ConnectionError, websockets.exceptions.WebSocketException) as e:\\n        trace = traceback.format_exc()\\n        await logger.aerror(f\\\"Connection error: {e!s}\\\\ntrace: {trace}\\\")\\n        function_output = {\\n            \\\"type\\\": \\\"conversation.item.create\\\",\\n            \\\"item\\\": {\\n                \\\"type\\\": \\\"function_call_output\\\",\\n                \\\"call_id\\\": function_call.get(\\\"call_id\\\"),\\n                \\\"output\\\": f\\\"Connection error: {e!s}\\\",\\n            },\\n        }\\n        msg_handler.openai_send(function_output)\\n    except (KeyError, AttributeError, TypeError) as e:\\n        await logger.aerror(f\\\"Error executing flow: {e}\\\")\\n        await logger.aerror(traceback.format_exc())\\n        function_output = {\\n            \\\"type\\\": \\\"conversation.item.create\\\",\\n            \\\"item\\\": {\\n                \\\"type\\\": \\\"function_call_output\\\",\\n                \\\"call_id\\\": function_call.get(\\\"call_id\\\"),\\n                \\\"output\\\": f\\\"Error executing flow: {e}\\\",\\n            },\\n        }\\n        msg_handler.openai_send(function_output)\\n\\n\\nvoice_config_cache: dict[tuple[UUID | None, str], VoiceConfig] = {}\\ntts_config_cache: dict[tuple[UUID | None, str], TTSConfig] = {}\\n\\n\\n# --- Global Queues and Message Processing ---\\n\\nmessage_queues: dict[str, asyncio.Queue] = defaultdict(asyncio.Queue)\\nmessage_tasks: dict[str, asyncio.Task] = {}\\nlast_sender_by_session: defaultdict[str, str | None] = defaultdict(lambda: None)\\n\\n\\nasync def _get_authorized_voice_flow(flow_id: str, current_user: CurrentActiveUser, session: DbSession) -> Flow:\\n    \\\"\\\"\\\"Load a voice flow with the same share-aware execute policy as standard builds.\\\"\\\"\\\"\\n    flow_uuid = UUID(flow_id)\\n    flow = await _read_flow(session, flow_uuid, current_user.id)\\n    if flow is None:\\n        public_stmt = select(Flow).where(\\n            Flow.id == flow_uuid,\\n            Flow.access_type == AccessTypeEnum.PUBLIC,\\n        )\\n        flow = (await session.exec(public_stmt)).first()\\n    if flow is None:\\n        raise HTTPException(status_code=404, detail=\\\"Flow not found\\\")\\n\\n    try:\\n        await ensure_flow_permission(\\n            current_user,\\n            FlowAction.EXECUTE,\\n            flow_id=flow_uuid,\\n            flow_user_id=flow.user_id,\\n            workspace_id=flow.workspace_id,\\n            folder_id=flow.folder_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Flow not found\\\") from exc\\n    return flow\\n\\n\\nasync def get_or_create_elevenlabs_client(user_id=None, session=None):\\n    \\\"\\\"\\\"Build an ElevenLabs client scoped to the requesting user.\\n\\n    Security: this previously delegated to a process-global singleton\\n    (``ElevenLabsClientManager``) that cached the *first* caller's API key and\\n    returned that same client to every subsequent user. As a result one tenant's\\n    ElevenLabs account was billed for everyone's TTS (cross-tenant billing\\n    siphon) and their voice library was exposed via /voice/elevenlabs/voice_ids.\\n\\n    Build a fresh client from the requesting user's own key on each call and never\\n    cache it on a class/module global.\\n    \\\"\\\"\\\"\\n    if not (user_id and session):\\n        return None\\n    variable_service = get_variable_service()\\n    try:\\n        api_key = await variable_service.get_variable(\\n            user_id=user_id,\\n            name=\\\"ELEVENLABS_API_KEY\\\",\\n            field=\\\"elevenlabs_api_key\\\",\\n            session=session,\\n        )\\n        api_key = secret_value_to_str(api_key)\\n    except (InvalidToken, ValueError) as e:\\n        await logger.aerror(f\\\"Error with ElevenLabs API key: {e}\\\")\\n        api_key = os.getenv(\\\"ELEVENLABS_API_KEY\\\", \\\"\\\")\\n    except (KeyError, AttributeError, sqlalchemy.exc.SQLAlchemyError) as e:\\n        await logger.aerror(f\\\"Exception getting ElevenLabs API key: {e}\\\")\\n        return None\\n    if not api_key:\\n        await logger.aerror(\\\"ElevenLabs API key not found\\\")\\n        return None\\n    return ElevenLabs(api_key=api_key)\\n\\n\\ndef pcm16_to_float_array(pcm_data):\\n    values = np.frombuffer(pcm_data, dtype=np.int16).astype(np.float32)\\n    return values / 32768.0\\n\\n\\nasync def text_chunker_with_timeout(chunks, timeout=0.3):\\n    splitters = (\\\".\\\", \\\",\\\", \\\"?\\\", \\\"!\\\", \\\";\\\", \\\":\\\", \\\"\u2014\\\", \\\"-\\\", \\\"(\\\", \\\")\\\", \\\"[\\\", \\\"]\\\", \\\"}\\\", \\\" \\\")\\n    buffer = \\\"\\\"\\n    ait = chunks.__aiter__()\\n    while True:\\n        try:\\n            text = await asyncio.wait_for(ait.__anext__(), timeout=timeout)\\n        except asyncio.TimeoutError:\\n            if buffer:\\n                yield buffer + \\\" \\\"\\n                buffer = \\\"\\\"\\n            continue\\n        except StopAsyncIteration:\\n            break\\n        if text is None:\\n            if buffer:\\n                yield buffer + \\\" \\\"\\n            break\\n        if buffer and buffer[-1] in splitters:\\n            yield buffer + \\\" \\\"\\n            buffer = text\\n        elif text and text[0] in splitters:\\n            yield buffer + text[0] + \\\" \\\"\\n            buffer = text[1:]\\n        else:\\n            buffer += text\\n    if buffer:\\n        yield buffer + \\\" \\\"\\n\\n\\nasync def queue_generator(queue: asyncio.Queue):\\n    while True:\\n        item = await queue.get()\\n        if item is None:\\n            break\\n        yield item\\n\\n\\ndef create_event_logger():\\n    state = {\\\"last_event_type\\\": None, \\\"event_count\\\": 0}\\n\\n    def log_event(event: dict, provenance: str) -> None:\\n        event_type = event.get(\\\"type\\\", \\\"None\\\")\\n        response_id = event.get(\\\"response_id\\\") or event.get(\\\"response\\\", {}).get(\\\"id\\\", None)\\n        if event_type != state[\\\"last_event_type\\\"]:\\n            logger.debug(f\\\"Event (response_id - {response_id}): {provenance} {event_type}\\\")\\n            state[\\\"last_event_type\\\"] = event_type\\n            state[\\\"event_count\\\"] = 0\\n            if event_type == \\\"response.created\\\":\\n                response_id = event.get(\\\"response\\\", {}).get(\\\"id\\\")\\n                logger.debug(f\\\"response_id: {response_id}\\\")\\n            if \\\"error\\\" in event_type:\\n                logger.debug(f\\\"Error {event}\\\")\\n        current_count = 0 if state[\\\"event_count\\\"] is None else state[\\\"event_count\\\"]\\n        state[\\\"event_count\\\"] = current_count + 1\\n\\n    return log_event\\n\\n\\nTTL_SECONDS = 60\\n_completed: dict[str, float] = {}\\n\\n\\ndef mark_response_done(response_id: str):\\n    logger.debug(f\\\"Marking response {response_id} as done\\\")\\n    _completed[response_id] = time.time()\\n\\n\\n# Don't let this grow unbounded\\ndef is_response_done(response_id: str) -> bool:\\n    now = time.time()\\n    # prune old entries\\n    for k, ts in list(_completed.items()):\\n        if now - ts > TTL_SECONDS:\\n            del _completed[k]\\n    completed = response_id in _completed\\n    if completed:\\n        logger.debug(f\\\"Response {response_id} is done: {completed}\\\")\\n    return completed\\n\\n\\nclass FunctionCall:\\n    def __init__(\\n        self,\\n        item: dict,\\n        msg_handler,\\n        flow_id: str,\\n        background_tasks,\\n        current_user,\\n        conversation_id: str,\\n        session_id: str,\\n        *,\\n        is_prog_enabled: bool,\\n    ):\\n        self.item = item\\n        self.args = \\\"\\\"\\n        self.done = False\\n        self.prog_rsp_id: str | None = None\\n        self.func_rsp_id: str | None = None\\n        self.func_task: asyncio.Task | None = None\\n        self.is_prog_enabled = is_prog_enabled\\n        self.msg_handler = msg_handler\\n        self.flow_id = flow_id\\n        self.background_tasks = background_tasks\\n        self.current_user = current_user\\n        self.conversation_id = conversation_id\\n        self.session_id = session_id\\n\\n    def append_args(self, args: str):\\n        self.args += args\\n\\n    def execute(self):\\n        if self.is_prog_enabled:\\n            self._send_progress_message()\\n        self._send_function_call()\\n\\n    def _send_progress_message(self):\\n        # Summarize and notify user of in-progress function call\\n        self.msg_handler.openai_send(\\n            {\\n                \\\"type\\\": \\\"conversation.item.create\\\",\\n                \\\"item\\\": {\\n                    \\\"type\\\": \\\"message\\\",\\n                    \\\"role\\\": \\\"system\\\",\\n                    \\\"content\\\": [\\n                        {\\n                            \\\"type\\\": \\\"input_text\\\",\\n                            \\\"text\\\": \\\"Tell the user you are now looking into or solving a request.\\\"\\n                            \\\"and summarize what is being requested.\\\"\\n                            \\\"Keep it very short.\\\"\\n                            f\\\"\\\\n\\\\nThe request: {self.args}\\\",\\n                        }\\n                    ],\\n                },\\n            }\\n        )\\n        create_response = partial(get_create_response(self.msg_handler, self.session_id, self.current_user.id))\\n        create_response()\\n\\n    def _send_function_call(self):\\n        async def _call():\\n            await handle_function_call(\\n                function_call=self.item,\\n                function_call_args=self.args,\\n                flow_id=self.flow_id,\\n                background_tasks=self.background_tasks,\\n                current_user=self.current_user,\\n                conversation_id=self.conversation_id,\\n                session_id=self.session_id,\\n                msg_handler=self.msg_handler,\\n            )\\n            self.done = True\\n\\n        self.func_task = asyncio.create_task(_call())\\n\\n\\n# --- WebSocket Endpoints for Flow-as-Tool ---\\n@router.websocket(\\\"/ws/flow_as_tool/{flow_id}\\\")\\nasync def flow_as_tool_websocket_no_session(\\n    client_websocket: WebSocket,\\n    flow_id: str,\\n    background_tasks: BackgroundTasks,\\n    session: DbSession,\\n):\\n    session_id = str(uuid4())\\n    await flow_as_tool_websocket(\\n        client_websocket=client_websocket,\\n        flow_id=flow_id,\\n        background_tasks=background_tasks,\\n        session=session,\\n        session_id=session_id,\\n    )\\n\\n\\n@router.websocket(\\\"/ws/flow_as_tool/{flow_id}/{session_id}\\\")\\nasync def flow_as_tool_websocket(\\n    client_websocket: WebSocket,\\n    flow_id: str,\\n    background_tasks: BackgroundTasks,\\n    session: DbSession,\\n    session_id: str,\\n):\\n    \\\"\\\"\\\"WebSocket endpoint registering the flow as a tool for real-time interaction.\\\"\\\"\\\"\\n    provider_policy_scope = ExitStack()\\n    vad_task: asyncio.Task | None = None\\n    try:\\n        await client_websocket.accept()\\n\\n        log_event = create_event_logger()\\n\\n        current_user: User = await get_current_user_for_websocket(client_websocket, session)\\n        try:\\n            flow = await _get_authorized_voice_flow(flow_id, current_user, session)\\n            flow_description = flow.description\\n            flow_tool = {\\n                \\\"name\\\": \\\"execute_flow\\\",\\n                \\\"type\\\": \\\"function\\\",\\n                \\\"description\\\": flow_description or \\\"Execute the flow with the given input\\\",\\n                \\\"parameters\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\\"input\\\": {\\\"type\\\": \\\"string\\\", \\\"description\\\": \\\"The input to send to the flow\\\"}},\\n                    \\\"required\\\": [\\\"input\\\"],\\n                },\\n            }\\n        except Exception as e:  # noqa: BLE001\\n            err_msg = {\\\"error\\\": f\\\"Failed to load flow: {e!s}\\\"}\\n            await client_websocket.send_json(err_msg)\\n            await logger.aerror(f\\\"Failed to load flow: {e}\\\")\\n            return\\n\\n        provider_policy_scope.enter_context(\\n            scoped_model_provider_policy_for_flow(\\n                flow,\\n                user_id=current_user.id,\\n                is_superuser=bool(getattr(current_user, \\\"is_superuser\\\", False)),\\n            )\\n        )\\n        current_user, openai_key = await authenticate_and_get_openai_key(session, current_user, client_websocket)\\n        if current_user is None or openai_key is None:\\n            return\\n\\n        # Resolve voice config only after authentication and flow authorization,\\n        # scoped to this user.\\n        voice_config = get_voice_config(session_id, current_user.id)\\n\\n        url = \\\"wss://api.openai.com/v1/realtime?model=gpt-4o-mini-realtime-preview\\\"\\n        headers = {\\n            \\\"Authorization\\\": f\\\"Bearer {openai_key}\\\",\\n            \\\"OpenAI-Beta\\\": \\\"realtime=v1\\\",\\n        }\\n\\n        def init_session_dict():\\n            session_dict = voice_config.get_session_dict()\\n            session_dict[\\\"tools\\\"] = [flow_tool]\\n            return session_dict\\n\\n        async with websockets.connect(url, additional_headers=headers) as openai_ws:\\n            msg_handler = SendQueues(openai_ws, client_websocket, log_event)\\n\\n            openai_realtime_session = init_session_dict()\\n\\n            session_update = {\\\"type\\\": \\\"session.update\\\", \\\"session\\\": openai_realtime_session}\\n            msg_handler.openai_send(session_update)\\n\\n            # Setup for VAD processing.\\n            vad_queue: asyncio.Queue = asyncio.Queue()\\n            vad_audio_buffer = bytearray()\\n            bot_speaking_flag = [False]\\n\\n            async def process_vad_audio() -> None:\\n                nonlocal vad_audio_buffer\\n                last_speech_time = datetime.now(tz=timezone.utc)\\n                vad = get_vad()\\n                while True:\\n                    base64_data = await vad_queue.get()\\n                    raw_chunk_24k = base64.b64decode(base64_data)\\n                    vad_audio_buffer.extend(raw_chunk_24k)\\n                    has_speech = False\\n                    while len(vad_audio_buffer) >= BYTES_PER_24K_FRAME:\\n                        frame_24k = vad_audio_buffer[:BYTES_PER_24K_FRAME]\\n                        del vad_audio_buffer[:BYTES_PER_24K_FRAME]\\n                        try:\\n                            frame_16k = resample_24k_to_16k(frame_24k)\\n                            is_speech = vad.is_speech(frame_16k, VAD_SAMPLE_RATE_16K)\\n                            if is_speech:\\n                                has_speech = True\\n                                logger.trace(\\\"!\\\", end=\\\"\\\")\\n                                if bot_speaking_flag[0]:\\n                                    msg_handler.openai_send({\\\"type\\\": \\\"response.cancel\\\"})\\n                                    bot_speaking_flag[0] = False\\n                        except Exception as e:  # noqa: BLE001\\n                            await logger.aerror(f\\\"[ERROR] VAD processing failed (ValueError): {e}\\\")\\n                            continue\\n                    if has_speech:\\n                        last_speech_time = datetime.now(tz=timezone.utc)\\n                        logger.trace(\\\".\\\", end=\\\"\\\")\\n                    else:\\n                        time_since_speech = (datetime.now(tz=timezone.utc) - last_speech_time).total_seconds()\\n                        if time_since_speech >= 1.0:\\n                            logger.trace(\\\"_\\\", end=\\\"\\\")\\n\\n            def client_send_event_from_thread(event, loop) -> None:\\n                return loop.call_soon_threadsafe(msg_handler.client_send, event)\\n\\n            def pass_through(from_dict, to_dict, keys):\\n                for key in keys:\\n                    if key in from_dict:\\n                        to_dict[key] = from_dict[key]\\n\\n            def merge(from_dict, to_dict, keys):\\n                for key in keys:\\n                    if key in from_dict:\\n                        if not isinstance(from_dict[key], str):\\n                            msg = f\\\"Only string values are supported for merge. Issue with key: {key}\\\"\\n                            raise ValueError(msg)\\n                        new_value = from_dict[key]\\n\\n                        if key not in to_dict:\\n                            to_dict[key] = new_value\\n                        else:\\n                            if not isinstance(to_dict[key], str):\\n                                msg = f\\\"Only string values are supported for merge. Issue with key: {key}\\\"\\n                                raise ValueError(msg)\\n                            old_value = to_dict[key]\\n\\n                            to_dict[key] = f\\\"{old_value}\\\\n{new_value}\\\"\\n\\n            def warn_if_present(config_dict, keys):\\n                for key in keys:\\n                    if key in config_dict:\\n                        logger.warning(f\\\"Removing key {key} from session.update.\\\")\\n\\n            def update_global_session(from_session):\\n                # Create a new session dict instead of modifying global\\n                new_session = init_session_dict()\\n                pass_through(\\n                    from_session,\\n                    new_session,\\n                    [\\\"voice\\\", \\\"temperature\\\", \\\"turn_detection\\\", \\\"input_audio_transcription\\\"],\\n                )\\n                merge(from_session, new_session, [\\\"instructions\\\"])\\n                warn_if_present(\\n                    from_session, [\\\"modalities\\\", \\\"tools\\\", \\\"tool_choice\\\", \\\"input_audio_format\\\", \\\"output_audio_format\\\"]\\n                )\\n                return new_session\\n\\n            class Response:\\n                def __init__(self, response_id: str, *, use_elevenlabs: bool | None = None):\\n                    if use_elevenlabs is None:\\n                        use_elevenlabs = False\\n                    self.response_id = response_id\\n                    if use_elevenlabs:\\n                        self.text_delta_queue: asyncio.Queue = asyncio.Queue()\\n                        self.text_delta_task = asyncio.create_task(process_text_deltas(self))\\n\\n            responses = {}\\n\\n            async def process_text_deltas(rsp: Response):\\n                \\\"\\\"\\\"Transfer text deltas from the async queue to a synchronous queue.\\n\\n                then run the ElevenLabs TTS call (which expects a sync generator) in a separate thread.\\n                \\\"\\\"\\\"\\n                try:\\n                    elevenlabs_client = await get_or_create_elevenlabs_client(current_user.id, session)\\n                    if elevenlabs_client is None:\\n                        return\\n\\n                    async def get_chunks(q: asyncio.Queue):\\n                        delims = [\\\".\\\", \\\"?\\\", \\\";\\\", \\\"!\\\"]\\n                        buf: str = \\\"\\\"\\n                        while True:\\n                            text = await q.get()\\n                            if text is None:\\n                                if len(buf) > 0:\\n                                    yield buf\\n                                return\\n                            buf += text\\n                            delim_locs = []\\n                            for delim in delims:\\n                                i = buf.find(delim)\\n                                while i != -1:\\n                                    delim_locs.append(i)\\n                                    i = buf.find(delim, i + 1)\\n                            substr_begin = 0\\n                            for delim_loc in delim_locs:\\n                                chunk = buf[substr_begin : delim_loc + 1]\\n                                substr_begin = delim_loc + 1\\n                                yield chunk\\n                            buf = buf[substr_begin:]\\n\\n                    chunk_gen = get_chunks(rsp.text_delta_queue)\\n\\n                    async for text_chunk in chunk_gen:\\n                        audio_chunks = elevenlabs_client.generate(\\n                            voice=voice_config.elevenlabs_voice,\\n                            output_format=\\\"pcm_24000\\\",\\n                            text=text_chunk,  # synchronous generator expected by ElevenLabs\\n                            model=voice_config.elevenlabs_model,\\n                            voice_settings=None,\\n                            stream=True,\\n                        )\\n                        for audio_chunk in audio_chunks:\\n                            base64_audio = base64.b64encode(audio_chunk).decode(\\\"utf-8\\\")\\n                            # Schedule sending the audio chunk in the main event loop.\\n                            event = {\\n                                \\\"type\\\": \\\"response.audio.delta\\\",\\n                                \\\"delta\\\": base64_audio,\\n                                \\\"response_id\\\": rsp.response_id,\\n                            }\\n                            # client_send_event_from_thread(event, main_loop)\\n                            msg_handler.client_send(event)\\n\\n                    event = {\\\"type\\\": \\\"response.audio.done\\\", \\\"response_id\\\": rsp.response_id}\\n                    # client_send_event_from_thread(event, main_loop)\\n                    msg_handler.client_send(event)\\n                except Exception:  # noqa: BLE001\\n                    await logger.aerror(traceback.format_exc())\\n\\n            async def forward_to_openai() -> None:\\n                nonlocal openai_realtime_session\\n                create_response = get_create_response(msg_handler, session_id, current_user.id)\\n                try:\\n                    num_audio_samples = 0  # Initialize as an integer instead of None\\n                    while True:\\n                        message_text = await client_websocket.receive_text()\\n                        msg = json.loads(message_text)\\n                        log_event(msg, CLIENT_TO_LF)\\n                        if msg.get(\\\"type\\\") == \\\"input_audio_buffer.append\\\":\\n                            logger.trace(f\\\"buffer_id {msg.get('buffer_id', '')}\\\")\\n                            base64_data = msg.get(\\\"audio\\\", \\\"\\\")\\n                            if not base64_data:\\n                                continue\\n                            # Ensure we're adding to an integer\\n                            num_audio_samples += len(base64_data)\\n                            event = {\\\"type\\\": \\\"input_audio_buffer.append\\\", \\\"audio\\\": base64_data}\\n                            msg_handler.openai_send(event)\\n                            if voice_config.barge_in_enabled:\\n                                await vad_queue.put(base64_data)\\n                        elif msg.get(\\\"type\\\") == \\\"response.create\\\":\\n                            create_response(msg)\\n                        elif msg.get(\\\"type\\\") == \\\"input_audio_buffer.commit\\\":\\n                            if num_audio_samples > AUDIO_SAMPLE_THRESHOLD:\\n                                msg_handler.openai_send(msg)\\n                                num_audio_samples = 0\\n                        elif msg.get(\\\"type\\\") == \\\"langflow.voice_mode.config\\\":\\n                            await logger.ainfo(f\\\"langflow.voice_mode.config {msg}\\\")\\n                            voice_config.progress_enabled = msg.get(\\\"progress_enabled\\\", True)\\n                        elif msg.get(\\\"type\\\") == \\\"langflow.elevenlabs.config\\\":\\n                            await logger.ainfo(f\\\"langflow.elevenlabs.config {msg}\\\")\\n                            voice_config.use_elevenlabs = msg[\\\"enabled\\\"]\\n                            voice_config.elevenlabs_voice = msg.get(\\\"voice_id\\\", voice_config.elevenlabs_voice)\\n\\n                            # Update modalities based on TTS choice\\n                            modalities = [\\\"text\\\"] if voice_config.use_elevenlabs else [\\\"audio\\\", \\\"text\\\"]\\n                            openai_realtime_session[\\\"modalities\\\"] = modalities\\n                            session_update = {\\\"type\\\": \\\"session.update\\\", \\\"session\\\": openai_realtime_session}\\n                            msg_handler.openai_send(session_update)\\n                        elif msg.get(\\\"type\\\") == \\\"session.update\\\":\\n                            openai_realtime_session = update_global_session(msg[\\\"session\\\"])\\n                            session_update = {\\\"type\\\": \\\"session.update\\\", \\\"session\\\": openai_realtime_session}\\n                            msg_handler.openai_send(session_update)\\n                        else:\\n                            msg_handler.openai_send(msg)\\n                except (WebSocketDisconnect, websockets.ConnectionClosedOK, websockets.ConnectionClosedError):\\n                    pass\\n\\n            async def forward_to_client() -> None:\\n                nonlocal bot_speaking_flag, responses\\n                conversation_id = str(uuid4())\\n                function_call = None\\n                rsp: Response | None = None\\n                # Store function call tasks to prevent garbage collection\\n\\n                try:\\n                    while True:\\n                        data = await openai_ws.recv()\\n                        event = json.loads(data)\\n                        log_event(event, OPENAI_TO_LF)\\n                        event_type = event.get(\\\"type\\\")\\n                        response_id = event.get(\\\"response_id\\\", None) or event.get(\\\"response\\\", {}).get(\\\"id\\\", None)\\n\\n                        do_forward = True\\n                        do_forward = do_forward and not (event_type == \\\"response.done\\\" and voice_config.use_elevenlabs)\\n                        do_forward = do_forward and event_type.find(\\\"flow.\\\") != 0\\n\\n                        if do_forward:\\n                            msg_handler.client_send(event)\\n                        if event_type == \\\"response.created\\\":\\n                            responses[response_id] = Response(response_id, use_elevenlabs=voice_config.use_elevenlabs)\\n                            if function_call:\\n                                if function_call.is_prog_enabled and not function_call.prog_rsp_id:\\n                                    function_call.prog_rsp_id = response_id\\n                                elif not function_call.func_rsp_id:\\n                                    function_call.func_rsp_id = response_id\\n                        elif event_type == \\\"response.text.delta\\\":\\n                            rsp = responses[response_id]\\n                            if voice_config.use_elevenlabs:\\n                                delta = event.get(\\\"delta\\\", \\\"\\\")\\n                                await rsp.text_delta_queue.put(delta)\\n                        elif event_type == \\\"response.text.done\\\":\\n                            rsp = responses[response_id]\\n                            if voice_config.use_elevenlabs:\\n                                await rsp.text_delta_queue.put(None)\\n                                if rsp.text_delta_task and not rsp.text_delta_task.done():\\n                                    await rsp.text_delta_task\\n                                responses.pop(response_id)\\n                                msg_handler.client_send({\\\"type\\\": \\\"response.done\\\", \\\"response\\\": {\\\"id\\\": response_id}})\\n\\n                                try:\\n                                    message_text = event.get(\\\"text\\\", \\\"\\\")\\n                                    await add_message_to_db(message_text, session, flow_id, session_id, \\\"Machine\\\", \\\"AI\\\")\\n                                except ValueError as err:\\n                                    await logger.aerror(f\\\"Error saving message to database (ValueError): {err}\\\")\\n                                    await logger.aerror(traceback.format_exc())\\n                                except (KeyError, AttributeError, TypeError) as err:\\n                                    # Replace blind Exception with specific exceptions\\n                                    await logger.aerror(f\\\"Error saving message to database: {err}\\\")\\n                                    await logger.aerror(traceback.format_exc())\\n\\n                        elif event_type == \\\"response.output_item.added\\\":\\n                            bot_speaking_flag[0] = True\\n                            item = event.get(\\\"item\\\", {})\\n                            if item.get(\\\"type\\\") == \\\"function_call\\\" and (\\n                                not function_call or (function_call and function_call.done)\\n                            ):\\n                                function_call = FunctionCall(\\n                                    item=item,\\n                                    msg_handler=msg_handler,\\n                                    flow_id=flow_id,\\n                                    background_tasks=background_tasks,\\n                                    current_user=current_user,\\n                                    conversation_id=conversation_id,\\n                                    session_id=session_id,\\n                                    is_prog_enabled=voice_config.progress_enabled,\\n                                )\\n                        elif event_type == \\\"response.output_item.done\\\":\\n                            try:\\n                                transcript = extract_transcript(event)\\n                                if transcript and transcript.strip():\\n                                    await add_message_to_db(transcript, session, flow_id, session_id, \\\"Machine\\\", \\\"AI\\\")\\n                            except ValueError as err:\\n                                await logger.aerror(f\\\"Error saving message to database (ValueError): {err}\\\")\\n                                await logger.aerror(traceback.format_exc())\\n                            except (KeyError, AttributeError, TypeError) as err:\\n                                # Replace blind Exception with specific exceptions\\n                                await logger.aerror(f\\\"Error saving message to database: {err}\\\")\\n                                await logger.aerror(traceback.format_exc())\\n                            bot_speaking_flag[0] = False\\n                        elif event_type == \\\"response.done\\\":\\n                            msg_handler.openai_unblock()\\n                        elif event_type == \\\"response.function_call_arguments.delta\\\":\\n                            if function_call and response_id not in (\\n                                function_call.prog_rsp_id,\\n                                function_call.func_rsp_id,\\n                            ):\\n                                function_call.append_args(event.get(\\\"delta\\\", \\\"\\\"))\\n                        elif event_type == \\\"response.function_call_arguments.done\\\":\\n                            if function_call and response_id not in (\\n                                function_call.prog_rsp_id,\\n                                function_call.func_rsp_id,\\n                            ):\\n                                function_call.execute()\\n                        elif event_type == \\\"response.audio.delta\\\":\\n                            # there are no audio deltas from OpenAI if ElevenLabs is used (because modality = [\\\"text\\\"]).\\n                            event.get(\\\"delta\\\", \\\"\\\")\\n                        elif event_type == \\\"conversation.item.input_audio_transcription.completed\\\":\\n                            try:\\n                                message_text = event.get(\\\"transcript\\\", \\\"\\\")\\n                                if message_text and message_text.strip():\\n                                    await add_message_to_db(message_text, session, flow_id, session_id, \\\"User\\\", \\\"User\\\")\\n                            except ValueError as e:\\n                                await logger.aerror(f\\\"Error saving message to database (ValueError): {e}\\\")\\n                                await logger.aerror(traceback.format_exc())\\n                            except (KeyError, AttributeError, TypeError) as e:\\n                                # Replace blind Exception with specific exceptions\\n                                await logger.aerror(f\\\"Error saving message to database: {e}\\\")\\n                                await logger.aerror(traceback.format_exc())\\n                        elif event_type == \\\"error\\\":\\n                            pass\\n\\n                except (WebSocketDisconnect, websockets.ConnectionClosedOK, websockets.ConnectionClosedError):\\n                    pass\\n\\n            if voice_config.barge_in_enabled:\\n                # Store the task reference to prevent it from being garbage collected\\n                vad_task = asyncio.create_task(process_vad_audio())\\n\\n            try:\\n                # Use gather with return_exceptions to collect any exceptions\\n                tasks = [asyncio.create_task(forward_to_openai()), asyncio.create_task(forward_to_client())]\\n                results = await asyncio.gather(*tasks, return_exceptions=True)\\n\\n                # Check for exceptions in results\\n                for result in results:\\n                    if isinstance(result, Exception):\\n                        await logger.aerror(\\\"WS loop failed:\\\", exc_info=result)\\n                        await logger.aerror(traceback.format_exc())\\n            except Exception as e:  # noqa: BLE001\\n                # Handle any other exceptions\\n                await logger.aerror(f\\\"WS loop failed: {e}\\\")\\n                await logger.aerror(traceback.format_exc())\\n            finally:\\n                # shared cleanup for writers & sockets\\n                async def close():\\n                    await msg_handler.close()\\n                    await client_websocket.close()\\n                    await openai_ws.close()\\n\\n                await close()\\n    except Exception as e:  # noqa: BLE001\\n        await logger.aerror(f\\\"Unexpected error: {e}\\\")\\n        await logger.aerror(traceback.format_exc())\\n    finally:\\n        provider_policy_scope.close()\\n        # Make sure to clean up the task\\n        if vad_task and not vad_task.done():\\n            vad_task.cancel()\\n\\n\\n@router.websocket(\\\"/ws/flow_tts/{flow_id}\\\")\\nasync def flow_tts_websocket_no_session(\\n    client_websocket: WebSocket,\\n    flow_id: str,\\n    background_tasks: BackgroundTasks,\\n    session: DbSession,\\n):\\n    session_id = str(uuid4())\\n    await flow_tts_websocket(\\n        client_websocket=client_websocket,\\n        flow_id=flow_id,\\n        background_tasks=background_tasks,\\n        session=session,\\n        session_id=session_id,\\n    )\\n\\n\\n@router.websocket(\\\"/ws/flow_tts/{flow_id}/{session_id}\\\")\\nasync def flow_tts_websocket(\\n    client_websocket: WebSocket,\\n    flow_id: str,\\n    background_tasks: BackgroundTasks,\\n    session: DbSession,\\n    session_id: str,\\n):\\n    \\\"\\\"\\\"WebSocket endpoint for direct flow text-to-speech interaction.\\\"\\\"\\\"\\n    provider_policy_scope = ExitStack()\\n    try:\\n        await client_websocket.accept()\\n\\n        openai_send_q: asyncio.Queue[dict] = asyncio.Queue()\\n        client_send_q: asyncio.Queue[dict] = asyncio.Queue()\\n\\n        log_event = create_event_logger()\\n\\n        async def openai_writer():\\n            while True:\\n                msg = await openai_send_q.get()\\n                if msg is None:\\n                    break\\n                logger.trace(f\\\"Sending text {LF_TO_OPENAI}: {msg['type']}\\\")\\n                await openai_ws.send(json.dumps(msg))\\n                logger.trace(\\\"JSON sent.\\\")\\n                log_event(msg, LF_TO_OPENAI)\\n\\n        async def client_writer():\\n            while True:\\n                msg = await client_send_q.get()\\n                if msg is None:\\n                    break\\n                logger.trace(f\\\"Sending JSON {LF_TO_CLIENT}: {msg['type']}\\\")\\n                await client_websocket.send_text(json.dumps(msg))\\n                logger.trace(\\\"JSON sent.\\\")\\n                log_event(msg, LF_TO_CLIENT)\\n\\n        def openai_send(payload):\\n            log_event(payload, LF_TO_OPENAI)\\n            logger.trace(f\\\"Sending text {LF_TO_OPENAI}: {payload['type']}\\\")\\n            openai_send_q.put_nowait(payload)\\n            logger.trace(\\\"JSON sent.\\\")\\n\\n        def client_send(payload):\\n            log_event(payload, LF_TO_CLIENT)\\n            logger.trace(f\\\"Sending JSON {LF_TO_CLIENT}: {payload['type']}\\\")\\n            client_send_q.put_nowait(payload)\\n            logger.trace(\\\"JSON sent.\\\")\\n\\n        async def close():\\n            openai_send_q.put_nowait(None)\\n            client_send_q.put_nowait(None)\\n            await openai_writer_task\\n            await client_writer_task\\n            await client_websocket.close()\\n            await openai_ws.close()\\n\\n        current_user: User = await get_current_user_for_websocket(client_websocket, session)\\n        try:\\n            flow = await _get_authorized_voice_flow(flow_id, current_user, session)\\n        except Exception as e:  # noqa: BLE001\\n            err_msg = {\\\"error\\\": f\\\"Failed to load flow: {e!s}\\\"}\\n            await client_websocket.send_json(err_msg)\\n            await logger.aerror(f\\\"Failed to load flow: {e}\\\")\\n            return\\n\\n        provider_policy_scope.enter_context(\\n            scoped_model_provider_policy_for_flow(\\n                flow,\\n                user_id=current_user.id,\\n                is_superuser=bool(getattr(current_user, \\\"is_superuser\\\", False)),\\n            )\\n        )\\n        current_user, openai_key = await authenticate_and_get_openai_key(session, current_user, client_websocket)\\n        if current_user is None or openai_key is None:\\n            return\\n        url = \\\"wss://api.openai.com/v1/realtime?intent=transcription\\\"\\n        headers = {\\n            \\\"Authorization\\\": f\\\"Bearer {openai_key}\\\",\\n            \\\"OpenAI-Beta\\\": \\\"realtime=v1\\\",\\n        }\\n\\n        tts_config = get_tts_config(session_id, openai_key, current_user.id)\\n        async with websockets.connect(url, additional_headers=headers) as openai_ws:\\n            openai_writer_task = asyncio.create_task(openai_writer())\\n            client_writer_task = asyncio.create_task(client_writer())\\n\\n            tts_realtime_session = tts_config.get_session_dict()\\n\\n            openai_send(tts_realtime_session)\\n\\n            async def forward_to_openai() -> None:\\n                try:\\n                    while True:\\n                        message_text = await client_websocket.receive_text()\\n                        event = json.loads(message_text)\\n                        if event.get(\\\"type\\\") == \\\"input_audio_buffer.append\\\":\\n                            base64_data = event.get(\\\"audio\\\", \\\"\\\")\\n                            if not base64_data:\\n                                continue\\n                            out_event = {\\\"type\\\": \\\"input_audio_buffer.append\\\", \\\"audio\\\": base64_data}\\n                            openai_send(out_event)\\n                        elif event.get(\\\"type\\\") == \\\"input_audio_buffer.commit\\\":\\n                            openai_send(event)\\n                        elif event.get(\\\"type\\\") == \\\"langflow.elevenlabs.config\\\":\\n                            await logger.ainfo(f\\\"langflow.elevenlabs.config {event}\\\")\\n                            tts_config.use_elevenlabs = event[\\\"enabled\\\"]\\n                            tts_config.elevenlabs_voice = event.get(\\\"voice_id\\\", tts_config.elevenlabs_voice)\\n                        elif event.get(\\\"type\\\") == \\\"voice.settings\\\":\\n                            # Store the voice setting\\n                            if event.get(\\\"voice\\\"):\\n                                tts_config.openai_voice = event.get(\\\"voice\\\")\\n                                await logger.ainfo(f\\\"Updated OpenAI voice to: {tts_config.openai_voice}\\\")\\n                except Exception as e:  # noqa: BLE001\\n                    await logger.aerror(f\\\"Error in WebSocket communication: {e}\\\")\\n\\n            async def forward_to_client() -> None:\\n                try:\\n                    while True:\\n                        data = await openai_ws.recv()\\n                        event = json.loads(data)\\n                        client_send(event)\\n                        if event.get(\\\"type\\\") == \\\"conversation.item.input_audio_transcription.completed\\\":\\n                            transcript = event.get(\\\"transcript\\\")\\n                            if transcript is not None and transcript != \\\"\\\":\\n                                input_request = InputValueRequest(\\n                                    input_value=transcript, components=[], type=\\\"chat\\\", session=session_id\\n                                )\\n                                with execution_protocol(\\\"voice\\\"):\\n                                    response = await build_flow_and_stream(\\n                                        flow_id=UUID(flow_id),\\n                                        inputs=input_request,\\n                                        background_tasks=background_tasks,\\n                                        current_user=current_user,\\n                                    )\\n                                result = \\\"\\\"\\n                                async for line in response.body_iterator:\\n                                    if not line:\\n                                        continue\\n                                    event_data = json.loads(line)\\n                                    client_send({\\\"type\\\": \\\"flow.build.progress\\\", \\\"data\\\": event_data})\\n                                    if event_data.get(\\\"event\\\") == \\\"end_vertex\\\":\\n                                        text = (\\n                                            event_data.get(\\\"data\\\", {})\\n                                            .get(\\\"build_data\\\", \\\"\\\")\\n                                            .get(\\\"data\\\", {})\\n                                            .get(\\\"results\\\", {})\\n                                            .get(\\\"message\\\", {})\\n                                            .get(\\\"text\\\", \\\"\\\")\\n                                        )\\n                                        if text:\\n                                            result = text\\n                                if result != \\\"\\\":\\n                                    if tts_config.use_elevenlabs:\\n                                        elevenlabs_client = await get_or_create_elevenlabs_client(\\n                                            current_user.id, session\\n                                        )\\n                                        if elevenlabs_client is None:\\n                                            return\\n                                        audio_stream = elevenlabs_client.generate(\\n                                            voice=tts_config.elevenlabs_voice,\\n                                            output_format=\\\"pcm_24000\\\",\\n                                            text=result,\\n                                            model=tts_config.elevenlabs_model,\\n                                            voice_settings=None,\\n                                            stream=True,\\n                                        )\\n                                        for chunk in audio_stream:\\n                                            base64_audio = base64.b64encode(chunk).decode(\\\"utf-8\\\")\\n                                            audio_event = {\\\"type\\\": \\\"response.audio.delta\\\", \\\"delta\\\": base64_audio}\\n                                            client_send(audio_event)\\n                                    else:\\n                                        oai_client = tts_config.get_openai_client()\\n                                        voice = tts_config.get_openai_voice()\\n                                        response = oai_client.audio.speech.create(\\n                                            model=\\\"gpt-4o-mini-tts\\\",\\n                                            voice=voice,\\n                                            input=result,  # Use result instead of undefined input variable\\n                                            instructions=\\\"be cheerful\\\",\\n                                            response_format=\\\"pcm\\\",\\n                                        )\\n\\n                                        base64_audio = base64.b64encode(response.content).decode(\\\"utf-8\\\")\\n                                        audio_event = {\\\"type\\\": \\\"response.audio.delta\\\", \\\"delta\\\": base64_audio}\\n                                        client_send(audio_event)\\n                except Exception as e:  # noqa: BLE001\\n                    await logger.aerror(f\\\"Error in WebSocket communication: {e}\\\")\\n\\n            try:\\n                # Create tasks and gather them for concurrent execution\\n                task1 = asyncio.create_task(forward_to_openai())\\n                task2 = asyncio.create_task(forward_to_client())\\n                await asyncio.gather(task1, task2)\\n            except Exception as exc:  # noqa: BLE001\\n                # handle any exceptions from any task\\n                await logger.aerror(\\\"WS loop failed:\\\", exc_info=exc)\\n            finally:\\n                # shared cleanup for writers & sockets\\n                await close()\\n    except Exception as e:  # noqa: BLE001\\n        await logger.aerror(f\\\"Unexpected error: {e}\\\")\\n        await logger.aerror(traceback.format_exc())\\n    finally:\\n        provider_policy_scope.close()\\n\\n\\ndef extract_transcript(json_data):\\n    try:\\n        content_list = json_data.get(\\\"item\\\", {}).get(\\\"content\\\", [])\\n        for content_item in content_list:\\n            if content_item.get(\\\"type\\\") == \\\"audio\\\":\\n                return content_item.get(\\\"transcript\\\", \\\"\\\")\\n    except (KeyError, TypeError, AttributeError) as e:\\n        logger.debug(f\\\"Error extracting transcript: {e}\\\")\\n        return \\\"\\\"\\n    else:\\n        return \\\"\\\"\\n\\n\\n@router.get(\\\"/elevenlabs/voice_ids\\\")\\nasync def get_elevenlabs_voice_ids(\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n):\\n    \\\"\\\"\\\"Get available voice IDs from ElevenLabs API.\\\"\\\"\\\"\\n    try:\\n        await ensure_voice_permission(\\n            current_user,\\n            VoiceAction.READ,\\n            voice_user_id=current_user.id,\\n        )\\n        # Get or create the ElevenLabs client\\n        elevenlabs_client = await get_or_create_elevenlabs_client(current_user.id, session)\\n        if elevenlabs_client is None:\\n            return {\\\"error\\\": \\\"ElevenLabs API key not found or invalid\\\"}\\n\\n        voices_response = elevenlabs_client.voices.get_all()\\n        voices = voices_response.voices\\n\\n        # Fix for PERF401: Use list comprehension\\n        return [\\n            {\\n                \\\"voice_id\\\": voice.voice_id,\\n                \\\"name\\\": voice.name,\\n            }\\n            for voice in voices\\n        ]\\n    except ValueError as e:\\n        await logger.aerror(f\\\"Error fetching ElevenLabs voices (ValueError): {e}\\\")\\n        return {\\\"error\\\": str(e)}\\n    except requests.RequestException as e:\\n        await logger.aerror(f\\\"Error fetching ElevenLabs voices (RequestException): {e}\\\")\\n        return {\\\"error\\\": str(e)}\\n    except (KeyError, AttributeError, TypeError) as e:\\n        # More specific exceptions instead of blind Exception\\n        await logger.aerror(f\\\"Error fetching ElevenLabs voices: {e}\\\")\\n        await logger.aerror(traceback.format_exc())\\n        return {\\\"error\\\": str(e)}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v2/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"42ca0969d39b6824c6ddb9df4af3c7833556e698fe43d837e9eae86e6326bd75\",\"content\":\"\\\"\\\"\\\"V2 API module.\\\"\\\"\\\"\\n\\nfrom .files import router as files_router\\nfrom .mcp import router as mcp_router\\nfrom .registration import router as registration_router\\nfrom .workflow import router as workflow_background_router\\nfrom .workflow_host import LangflowWorkflowHost\\nfrom .workflow_public import router as workflow_public_router\\n\\n__all__ = [\\n    \\\"LangflowWorkflowHost\\\",\\n    \\\"files_router\\\",\\n    \\\"mcp_router\\\",\\n    \\\"registration_router\\\",\\n    \\\"workflow_background_router\\\",\\n    \\\"workflow_public_router\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v2/files.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1a09a0a2e1d2c4b49a3a41842130913e34025cee67cb245be5cef5fe4139e3ec\",\"content\":\"import io\\nimport re\\nimport uuid\\nimport zipfile\\nfrom collections.abc import AsyncGenerator, AsyncIterable\\nfrom datetime import datetime\\nfrom http import HTTPStatus\\nfrom pathlib import Path\\nfrom typing import Annotated\\nfrom zoneinfo import ZoneInfo\\n\\nfrom fastapi import APIRouter, Depends, File, HTTPException, UploadFile\\nfrom fastapi.responses import StreamingResponse\\nfrom lfx.log.logger import logger\\nfrom sqlmodel import col, select\\n\\nfrom langflow.api.schemas import UploadFileResponse\\nfrom langflow.api.utils import CurrentActiveUser, DbSession, build_content_disposition\\nfrom langflow.services.authorization import FileAction, ensure_file_permission\\nfrom langflow.services.authorization.fetch import authorized_or_owner_scoped, deny_to_404\\nfrom langflow.services.authorization.listing import restrict_to_owned_or_visible_scope, visible_scope_prefilter\\nfrom langflow.services.database.models.file.model import File as UserFile\\nfrom langflow.services.deps import get_settings_service, get_storage_service\\nfrom langflow.services.settings.service import SettingsService\\nfrom langflow.services.storage.service import StorageService\\n\\nrouter = APIRouter(tags=[\\\"Files\\\"], prefix=\\\"/files\\\")\\n\\n# Set the static name of the MCP servers file\\nMCP_SERVERS_FILE = \\\"_mcp_servers\\\"\\nSAMPLE_DATA_DIR = Path(__file__).parent / \\\"sample_data\\\"\\n\\n\\ndef is_permanent_storage_failure(error: Exception) -> bool:\\n    \\\"\\\"\\\"Check if a storage deletion error is a permanent failure (file/storage gone).\\n\\n    Permanent failures are safe to delete from DB because the file/storage is already gone.\\n    Transient failures (network, permissions) should keep DB record for retry.\\n\\n    Args:\\n        error: The exception raised during storage deletion\\n\\n    Returns:\\n        True if this is a permanent failure (safe to delete from DB), False otherwise\\n    \\\"\\\"\\\"\\n    # Check for standard Python file not found errors (local storage)\\n    if isinstance(error, FileNotFoundError):\\n        return True\\n\\n    # Check for S3 error codes (boto3/aiobotocore)\\n    # S3 errors have a 'response' attribute with Error.Code\\n    if hasattr(error, \\\"response\\\"):\\n        response = error.response\\n        if isinstance(response, dict):\\n            error_code = response.get(\\\"Error\\\", {}).get(\\\"Code\\\")\\n            # Permanent failures: file/bucket doesn't exist\\n            if error_code in (\\\"NoSuchBucket\\\", \\\"NoSuchKey\\\", \\\"404\\\"):\\n                return True\\n\\n    # Fallback: Check error message for known permanent failure patterns\\n    # This is less ideal but provides a safety net for edge cases\\n    error_str = str(error)\\n    permanent_patterns = (\\\"NoSuchBucket\\\", \\\"NoSuchKey\\\", \\\"not found\\\", \\\"FileNotFoundError\\\")\\n\\n    return any(pattern in error_str for pattern in permanent_patterns)\\n\\n\\nasync def get_mcp_file(current_user: CurrentActiveUser, *, extension: bool = False) -> str:\\n    # Create a unique MCP servers file with the user id appended\\n    return f\\\"{MCP_SERVERS_FILE}_{current_user.id!s}\\\" + (\\\".json\\\" if extension else \\\"\\\")\\n\\n\\nasync def _validate_uploaded_mcp_config(file: UploadFile) -> dict[str, dict]:\\n    \\\"\\\"\\\"Validate an uploaded MCP servers config against MCPServerConfig.\\n\\n    Security: the uploaded bytes become the user's MCP servers config, whose\\n    ``command``/``args`` are later spawned via the stdio transport. The structured\\n    ``/api/v2/mcp/servers`` endpoints validate each entry with ``MCPServerConfig``\\n    (command allow-list, arg/env checks); this file-upload path must apply the SAME\\n    validation so it cannot be used to bypass the allow-list and run an arbitrary\\n    command on the server. Rewinds the file so the subsequent save re-reads it.\\n    \\\"\\\"\\\"\\n    import json\\n\\n    from pydantic import ValidationError\\n\\n    from langflow.api.v2.schemas import MCPServerConfig\\n\\n    raw = await file.read()\\n    await file.seek(0)\\n    try:\\n        parsed = json.loads(raw)\\n    except (json.JSONDecodeError, UnicodeDecodeError) as exc:\\n        raise HTTPException(status_code=422, detail=\\\"Invalid MCP servers config: not valid JSON\\\") from exc\\n    servers = parsed.get(\\\"mcpServers\\\") if isinstance(parsed, dict) else None\\n    if not isinstance(servers, dict):\\n        raise HTTPException(status_code=422, detail=\\\"Invalid MCP servers config: expected an 'mcpServers' object\\\")\\n    for name, cfg in servers.items():\\n        try:\\n            MCPServerConfig.model_validate(cfg)\\n        except ValidationError as exc:\\n            raise HTTPException(status_code=422, detail=f\\\"Invalid MCP server '{name}': {exc}\\\") from exc\\n    return servers\\n\\n\\nasync def byte_stream_generator(file_input, chunk_size: int = 8192) -> AsyncGenerator[bytes, None]:\\n    \\\"\\\"\\\"Convert bytes object or stream into an async generator that yields chunks.\\\"\\\"\\\"\\n    if isinstance(file_input, bytes):\\n        # Handle bytes object\\n        for i in range(0, len(file_input), chunk_size):\\n            yield file_input[i : i + chunk_size]\\n    # Handle stream object\\n    elif hasattr(file_input, \\\"read\\\"):\\n        while True:\\n            chunk = await file_input.read(chunk_size) if callable(file_input.read) else file_input.read(chunk_size)\\n            if not chunk:\\n                break\\n            yield chunk\\n    else:\\n        # Handle async iterator\\n        async for chunk in file_input:\\n            yield chunk\\n\\n\\nasync def fetch_file_object(file_id: uuid.UUID, current_user: CurrentActiveUser, session: DbSession):\\n    # Share-aware fetch. Under the OSS pass-through this keeps the existing\\n    # owner-scoped query (cannot widen visibility). Authorization plugins set\\n    # ``SUPPORTS_CROSS_USER_FETCH=True`` so a share grant can resolve here.\\n    file = await authorized_or_owner_scoped(\\n        session,\\n        UserFile,\\n        id_column=UserFile.id,\\n        resource_id=file_id,\\n        owner_column=UserFile.user_id,\\n        owner_id=current_user.id,\\n    )\\n\\n    # Check if the file exists\\n    if not file:\\n        raise HTTPException(status_code=404, detail=\\\"File not found\\\")\\n\\n    return file\\n\\n\\nasync def save_file_routine(\\n    file,\\n    storage_service,\\n    current_user: CurrentActiveUser,\\n    file_content=None,\\n    file_name=None,\\n    *,\\n    append: bool = False,\\n):\\n    \\\"\\\"\\\"Routine to save the file content to the storage service.\\\"\\\"\\\"\\n    file_id = uuid.uuid4()\\n\\n    if not file_content:\\n        file_content = await file.read()\\n    if not file_name:\\n        file_name = file.filename\\n\\n    # Save the file using the storage service.\\n    await storage_service.save_file(flow_id=str(current_user.id), file_name=file_name, data=file_content, append=append)\\n\\n    return file_id, file_name\\n\\n\\n@router.post(\\\"\\\", status_code=HTTPStatus.CREATED)\\n@router.post(\\\"/\\\", status_code=HTTPStatus.CREATED)\\nasync def upload_user_file(\\n    file: Annotated[UploadFile, File(...)],\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n    *,\\n    append: bool = False,\\n    ephemeral: bool = False,\\n) -> UploadFileResponse:\\n    \\\"\\\"\\\"Upload a file for the current user and track it in the database.\\\"\\\"\\\"\\n    await ensure_file_permission(\\n        current_user,\\n        FileAction.CREATE,\\n        file_user_id=current_user.id,\\n    )\\n    # Get the max allowed file size from settings (in MB)\\n    try:\\n        max_file_size_upload = settings_service.settings.max_file_size_upload\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=f\\\"Settings error: {e}\\\") from e\\n\\n    # Validate that a file is actually provided\\n    if not file or not file.filename:\\n        raise HTTPException(status_code=400, detail=\\\"No file provided\\\")\\n\\n    # Validate file size (convert MB to bytes)\\n    if file.size > max_file_size_upload * 1024 * 1024:\\n        raise HTTPException(\\n            status_code=413,\\n            detail=f\\\"File size is larger than the maximum file size {max_file_size_upload}MB.\\\",\\n        )\\n\\n    # Create a new database record for the uploaded file.\\n    try:\\n        # SECURITY FIX: Validate and sanitize multipart upload filename to prevent path traversal attacks\\n        # First, validate the original filename to reject obvious malicious attempts\\n        if not file.filename:\\n            raise HTTPException(status_code=400, detail=\\\"No filename provided\\\")\\n\\n        # Reject filenames containing directory traversal sequences or path separators\\n        # This prevents attackers from using directory traversal in the Content-Disposition header\\n        # Check for: path separators (/, \\\\), traversal (..), null bytes, and other dangerous chars\\n        dangerous_chars = [\\\"..\\\", \\\"/\\\", \\\"\\\\\\\\\\\", \\\"\\\\x00\\\", \\\"\\\\n\\\", \\\"\\\\r\\\"]\\n        if any(char in file.filename for char in dangerous_chars):\\n            raise HTTPException(\\n                status_code=400,\\n                detail=(\\n                    \\\"Invalid file name. Filename must not contain directory paths, \\\"\\n                    \\\"'..' sequences, or control characters.\\\"\\n                ),\\n            )\\n\\n        # Additional check: reject filenames that are too long (prevent DoS)\\n        # Most filesystems have a 255 byte limit for filenames\\n        MAX_FILENAME_BYTES = 255  # noqa: N806\\n        if len(file.filename.encode(\\\"utf-8\\\")) > MAX_FILENAME_BYTES:\\n            raise HTTPException(\\n                status_code=400,\\n                detail=\\\"File name is too long. Maximum 255 bytes allowed.\\\",\\n            )\\n\\n        # Extract only the basename as an additional safety measure\\n        # This provides defense-in-depth in case the above checks are bypassed\\n        new_filename = Path(file.filename).name\\n\\n        # Final validation: ensure the sanitized filename is valid and not empty\\n        if not new_filename or new_filename in (\\\".\\\", \\\"..\\\"):\\n            raise HTTPException(status_code=400, detail=\\\"Invalid file name after sanitization\\\")\\n\\n        # Reject reserved filenames on Windows (CON, PRN, AUX, NUL, COM1-9, LPT1-9)\\n        # This prevents issues when code runs on Windows systems\\n        reserved_names = {\\n            \\\"CON\\\",\\n            \\\"PRN\\\",\\n            \\\"AUX\\\",\\n            \\\"NUL\\\",\\n            \\\"COM1\\\",\\n            \\\"COM2\\\",\\n            \\\"COM3\\\",\\n            \\\"COM4\\\",\\n            \\\"COM5\\\",\\n            \\\"COM6\\\",\\n            \\\"COM7\\\",\\n            \\\"COM8\\\",\\n            \\\"COM9\\\",\\n            \\\"LPT1\\\",\\n            \\\"LPT2\\\",\\n            \\\"LPT3\\\",\\n            \\\"LPT4\\\",\\n            \\\"LPT5\\\",\\n            \\\"LPT6\\\",\\n            \\\"LPT7\\\",\\n            \\\"LPT8\\\",\\n            \\\"LPT9\\\",\\n        }\\n        name_without_ext = new_filename.rsplit(\\\".\\\", 1)[0].upper()\\n        if name_without_ext in reserved_names:\\n            raise HTTPException(\\n                status_code=400,\\n                detail=f\\\"Invalid file name. '{name_without_ext}' is a reserved system name.\\\",\\n            )\\n\\n        # Enforce unique constraint on name, except for the special _mcp_servers file\\n        try:\\n            root_filename, file_extension = new_filename.rsplit(\\\".\\\", 1)\\n        except ValueError:\\n            root_filename, file_extension = new_filename, \\\"\\\"\\n\\n        # Special handling for the MCP servers config file: always keep the same root filename\\n        mcp_file = await get_mcp_file(current_user)\\n        mcp_file_ext = await get_mcp_file(current_user, extension=True)\\n\\n        # Initialize existing_file for append mode\\n        existing_file = None\\n\\n        if new_filename == mcp_file_ext:\\n            # Honor the MCP-servers lock on this path too. The structured\\n            # /api/v2/mcp/servers endpoints reject non-superuser writes when the lock\\n            # is on, but this branch writes the same _mcp_servers_<uid>.json that\\n            # get_server_list reads \u2014 so without the same guard a non-superuser could\\n            # replace their MCP config via the file-upload path while it's locked.\\n            from langflow.api.v2.mcp import ensure_mcp_stdio_access, is_mcp_servers_locked\\n\\n            if is_mcp_servers_locked(settings_service.settings) and not current_user.is_superuser:\\n                raise HTTPException(\\n                    status_code=403,\\n                    detail=\\\"MCP server configuration is locked. \\\"\\n                    \\\"Contact an administrator to manage external MCP servers.\\\",\\n                )\\n            # Validate the uploaded MCP servers config before storing it, so this\\n            # path can't bypass the command allow-list enforced by the structured\\n            # /api/v2/mcp/servers endpoints (otherwise an attacker-supplied command\\n            # would later be spawned via the stdio transport -> RCE).\\n            servers = await _validate_uploaded_mcp_config(file)\\n            for server_config in servers.values():\\n                ensure_mcp_stdio_access(server_config, current_user, settings_service.settings)\\n            # Check if an existing record exists; if so, delete it to replace with the new one\\n            existing_mcp_file = await get_file_by_name(mcp_file, current_user, session)\\n            if existing_mcp_file:\\n                await delete_file(existing_mcp_file.id, current_user, session, storage_service)\\n                # Flush the session to ensure the deletion is committed before creating the new file\\n                await session.flush()\\n            unique_filename = new_filename\\n        elif append:\\n            # In append mode, check if file exists and reuse the same filename\\n            existing_file = await get_file_by_name(root_filename, current_user, session)\\n            if existing_file:\\n                # File exists, append to it by reusing the same filename\\n                # Extract the filename from the path\\n                unique_filename = Path(existing_file.path).name\\n            else:\\n                # File doesn't exist yet, create new one with extension\\n                unique_filename = f\\\"{root_filename}.{file_extension}\\\" if file_extension else root_filename\\n        else:\\n            # For normal files, ensure unique name by appending a count if necessary\\n            stmt = select(UserFile).where(\\n                col(UserFile.name).like(f\\\"{root_filename}%\\\"), UserFile.user_id == current_user.id\\n            )\\n            existing_files = await session.exec(stmt)\\n            files = existing_files.all()  # Fetch all matching records\\n\\n            if files:\\n                counts = []\\n\\n                # Extract the count from the filename\\n                for my_file in files:\\n                    match = re.search(r\\\"\\\\((\\\\d+)\\\\)(?=\\\\.\\\\w+$|$)\\\", my_file.name)\\n                    if match:\\n                        counts.append(int(match.group(1)))\\n\\n                count = max(counts) if counts else 0\\n                root_filename = f\\\"{root_filename} ({count + 1})\\\"\\n\\n            # Create the unique filename with extension for storage\\n            unique_filename = f\\\"{root_filename}.{file_extension}\\\" if file_extension else root_filename\\n\\n        # Read file content, save with unique filename, and compute file size in one routine\\n        try:\\n            file_id, stored_file_name = await save_file_routine(\\n                file, storage_service, current_user, file_name=unique_filename, append=append\\n            )\\n            file_size = await storage_service.get_file_size(\\n                flow_id=str(current_user.id),\\n                file_name=stored_file_name,\\n            )\\n        except FileNotFoundError as e:\\n            # S3 bucket doesn't exist or file not found, or file was uploaded but can't be found\\n            raise HTTPException(status_code=404, detail=str(e)) from e\\n        except PermissionError as e:\\n            # Access denied or invalid credentials - return 500 as this is a server config issue\\n            raise HTTPException(status_code=500, detail=\\\"Error accessing storage\\\") from e\\n        except Exception as e:\\n            # General error saving file or getting file size\\n            raise HTTPException(status_code=500, detail=f\\\"Error accessing file: {e}\\\") from e\\n\\n        if ephemeral:\\n            # Ephemeral uploads: file is saved to storage (servable for chat history)\\n            # but no UserFile record is created (won't appear in \\\"My Files\\\")\\n            file_path = f\\\"{current_user.id}/{stored_file_name}\\\"\\n            return UploadFileResponse(id=file_id, name=root_filename, path=file_path, size=file_size)\\n\\n        if append and existing_file:\\n            existing_file.size = file_size\\n            session.add(existing_file)\\n            await session.commit()\\n            await session.refresh(existing_file)\\n            new_file = existing_file\\n        else:\\n            # Create a new file record\\n            new_file = UserFile(\\n                id=file_id,\\n                user_id=current_user.id,\\n                name=root_filename,\\n                path=f\\\"{current_user.id}/{stored_file_name}\\\",\\n                size=file_size,\\n            )\\n\\n        session.add(new_file)\\n        try:\\n            await session.flush()\\n            await session.refresh(new_file)\\n        except Exception as db_err:\\n            # Database insert failed - clean up the uploaded file to avoid orphaned files\\n            try:\\n                await storage_service.delete_file(flow_id=str(current_user.id), file_name=stored_file_name)\\n            except OSError as e:\\n                #  If delete fails, just log the error\\n                await logger.aerror(f\\\"Failed to clean up uploaded file {stored_file_name}: {e}\\\")\\n\\n            raise HTTPException(\\n                status_code=500, detail=f\\\"Error inserting file metadata into database: {db_err}\\\"\\n            ) from db_err\\n    except HTTPException:\\n        # Re-raise HTTP exceptions (like 409 conflicts) without modification\\n        raise\\n    except Exception as e:\\n        # Optionally, you could also delete the file from disk if the DB insert fails.\\n        raise HTTPException(status_code=500, detail=f\\\"Database error: {e}\\\") from e\\n\\n    return UploadFileResponse(id=new_file.id, name=new_file.name, path=new_file.path, size=new_file.size)\\n\\n\\nasync def get_file_by_name(\\n    file_name: str,  # The name of the file to search for\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> UserFile | None:\\n    \\\"\\\"\\\"Get the file associated with a given file name for the current user.\\\"\\\"\\\"\\n    try:\\n        # Fetch from the UserFile table\\n        stmt = select(UserFile).where(UserFile.user_id == current_user.id).where(UserFile.name == file_name)\\n        result = await session.exec(stmt)\\n\\n        return result.first() or None\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=f\\\"Error fetching file: {e}\\\") from e\\n\\n\\nasync def load_sample_files(current_user: CurrentActiveUser, session: DbSession, storage_service: StorageService):\\n    # Check if the sample files in the SAMPLE_DATA_DIR exist\\n    for sample_file_path in Path(SAMPLE_DATA_DIR).iterdir():\\n        sample_file_name = sample_file_path.name\\n        root_filename, _ = sample_file_name.rsplit(\\\".\\\", 1)\\n\\n        # Check if the sample file exists in the storage service\\n        existing_sample_file = await get_file_by_name(\\n            file_name=root_filename, current_user=current_user, session=session\\n        )\\n        if existing_sample_file:\\n            continue\\n\\n        # Read the binary data of the sample file\\n        binary_data = sample_file_path.read_bytes()\\n\\n        # Write the sample file content to the storage service\\n        file_id, _ = await save_file_routine(\\n            sample_file_path,\\n            storage_service,\\n            current_user,\\n            file_content=binary_data,\\n            file_name=sample_file_name,\\n        )\\n        file_size = await storage_service.get_file_size(\\n            flow_id=str(current_user.id),\\n            file_name=sample_file_name,\\n        )\\n        # Create a UserFile object for the sample file\\n        sample_file = UserFile(\\n            id=file_id,\\n            user_id=current_user.id,\\n            name=root_filename,\\n            path=sample_file_name,\\n            size=file_size,\\n        )\\n\\n        session.add(sample_file)\\n\\n        await session.flush()\\n        await session.refresh(sample_file)\\n\\n\\n@router.get(\\\"\\\")\\n@router.get(\\\"/\\\", status_code=HTTPStatus.OK)\\nasync def list_files(\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    # storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n) -> list[UserFile]:\\n    \\\"\\\"\\\"List the files available to the current user.\\\"\\\"\\\"\\n    await ensure_file_permission(\\n        current_user,\\n        FileAction.READ,\\n        file_user_id=current_user.id,\\n    )\\n    try:\\n        # Load sample files if they don't exist\\n        # TODO: Pending further testing\\n        # await load_sample_files(current_user, session, get_storage_service())\\n        # Fetch from the UserFile table\\n        visibility = await visible_scope_prefilter(\\n            current_user,\\n            resource_type=\\\"file\\\",\\n            act=FileAction.READ,\\n        )\\n        stmt = select(UserFile)\\n        if visibility is None:\\n            stmt = stmt.where(UserFile.user_id == current_user.id)\\n        else:\\n            # UserFile has no canonical workspace/project columns. Omitting\\n            # them intentionally keeps domain-only grants owner-scoped.\\n            stmt = restrict_to_owned_or_visible_scope(\\n                stmt,\\n                id_column=UserFile.id,\\n                owner_clause=UserFile.user_id == current_user.id,\\n                visibility=visibility,\\n            )\\n        results = await session.exec(stmt)\\n\\n        full_list = list(results)\\n\\n        # Reserved MCP configuration files are internal implementation details.\\n        # Derive the reserved name from each row's true owner because a widened\\n        # visibility scope can return files owned by multiple users.\\n        return [file for file in full_list if file.name != f\\\"{MCP_SERVERS_FILE}_{file.user_id!s}\\\"]\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=f\\\"Error listing files: {e}\\\") from e\\n\\n\\n@router.delete(\\\"/batch/\\\", status_code=HTTPStatus.OK)\\nasync def delete_files_batch(\\n    file_ids: list[uuid.UUID],\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    \\\"\\\"\\\"Delete multiple files by their IDs.\\\"\\\"\\\"\\n    try:\\n        # Share-aware fetch: when an authorization plugin supports cross-user\\n        # access, the SELECT loads by id alone so each row's true owner\\n        # surfaces and per-row ``ensure_file_permission`` can decide. The OSS\\n        # pass-through keeps the owner-scoped query.\\n        from langflow.services.deps import get_authorization_service\\n\\n        authz = get_authorization_service()\\n        share_aware = await authz.supports_cross_user_fetch() and await authz.is_enabled()\\n        stmt = select(UserFile).where(col(UserFile.id).in_(file_ids))\\n        if not share_aware:\\n            stmt = stmt.where(col(UserFile.user_id) == current_user.id)\\n        results = await session.exec(stmt)\\n        files = results.all()\\n\\n        if not files:\\n            raise HTTPException(status_code=404, detail=\\\"No files found\\\")\\n\\n        # Per-file authorization. Use the true owner so a delete share on\\n        # someone else's file is enforced against the right object key.\\n        for file in files:\\n            await ensure_file_permission(\\n                current_user,\\n                FileAction.DELETE,\\n                file_id=file.id,\\n                file_user_id=file.user_id,\\n            )\\n\\n        # Track storage deletion failures\\n        storage_failures = []\\n        # Track database deletion failures\\n        db_failures = []\\n\\n        # Delete all files from the storage service\\n        for file in files:\\n            # Extract just the filename from the path (strip user_id prefix).\\n            # The file lives under its owner's namespace.\\n            file_name = Path(file.path).name\\n            owner_id = str(file.user_id)\\n            storage_deleted = False\\n\\n            try:\\n                await storage_service.delete_file(flow_id=owner_id, file_name=file_name)\\n                storage_deleted = True\\n            except OSError as err:\\n                # Check if this is a \\\"permanent\\\" failure where file/storage is gone\\n                # These are safe to delete from DB even if storage deletion failed\\n                if is_permanent_storage_failure(err):\\n                    # File/storage is permanently gone - safe to delete from DB\\n                    await logger.awarning(\\n                        \\\"File %s not found in storage (permanent failure), will remove from database: %s\\\",\\n                        file_name,\\n                        err,\\n                    )\\n                    storage_deleted = True  # Treat as \\\"deleted\\\" for DB purposes\\n                else:\\n                    # Transient failure (network, timeout, permissions) - keep in DB for retry\\n                    storage_failures.append(f\\\"{file_name}: {err}\\\")\\n                    await logger.awarning(\\n                        \\\"Failed to delete file %s from storage (transient error, keeping in database for retry): %s\\\",\\n                        file_name,\\n                        err,\\n                    )\\n\\n            # Only delete from database if storage deletion succeeded OR it was a permanent failure\\n            if storage_deleted:\\n                try:\\n                    await session.delete(file)\\n                except OSError as db_error:\\n                    # Log database deletion failure but continue processing remaining files\\n                    db_failures.append(f\\\"{file_name}: {db_error}\\\")\\n                    await logger.aerror(\\n                        \\\"Failed to delete file %s from database: %s\\\",\\n                        file_name,\\n                        db_error,\\n                    )\\n\\n        # If there were storage failures, include them in the response\\n        if storage_failures:\\n            await logger.awarning(\\n                \\\"Batch delete completed with %d storage failures: %s\\\", len(storage_failures), storage_failures\\n            )\\n        # If there were database failures, log them\\n        if db_failures:\\n            await logger.aerror(\\\"Batch delete completed with %d database failures: %s\\\", len(db_failures), db_failures)\\n            # If all database deletions failed, raise an error\\n            if len(db_failures) == len(files):\\n                raise HTTPException(status_code=500, detail=f\\\"Failed to delete any files from database: {db_failures}\\\")\\n\\n        # Calculate how many files were actually deleted from database\\n        # Files successfully deleted = total - (kept due to transient storage failures) - (DB deletion failures)\\n        files_deleted = len(files) - len(storage_failures) - len(db_failures)\\n        files_kept = len(storage_failures)  # Files with transient storage failures kept in DB\\n\\n        # Build response message\\n        if files_deleted == len(files):\\n            message = f\\\"{files_deleted} files deleted successfully\\\"\\n        elif files_deleted > 0:\\n            message = f\\\"{files_deleted} files deleted successfully\\\"\\n            if files_kept > 0:\\n                message += f\\\", {files_kept} files kept in database due to transient storage errors (can retry)\\\"\\n        else:\\n            message = \\\"No files were deleted from database\\\"\\n\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=f\\\"Error deleting files: {e}\\\") from e\\n\\n    return {\\\"message\\\": message}\\n\\n\\n@router.post(\\\"/batch/\\\", status_code=HTTPStatus.OK)\\nasync def download_files_batch(\\n    file_ids: list[uuid.UUID],\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    \\\"\\\"\\\"Download multiple files as a zip file by their IDs.\\\"\\\"\\\"\\n    try:\\n        # Share-aware SELECT so a non-owner with a read share resolves the\\n        # row; per-row ensure_file_permission below uses the true owner.\\n        from langflow.services.deps import get_authorization_service\\n\\n        authz = get_authorization_service()\\n        share_aware = await authz.supports_cross_user_fetch() and await authz.is_enabled()\\n        stmt = select(UserFile).where(col(UserFile.id).in_(file_ids))\\n        if not share_aware:\\n            stmt = stmt.where(col(UserFile.user_id) == current_user.id)\\n        results = await session.exec(stmt)\\n        files = results.all()\\n\\n        if not files:\\n            raise HTTPException(status_code=404, detail=\\\"No files found\\\")\\n\\n        for file in files:\\n            await ensure_file_permission(\\n                current_user,\\n                FileAction.READ,\\n                file_id=file.id,\\n                file_user_id=file.user_id,\\n            )\\n\\n        # Create a byte stream to hold the ZIP file\\n        zip_stream = io.BytesIO()\\n\\n        # Create a ZIP file. Each file is read from its owner's storage\\n        # namespace, not the actor's.\\n        with zipfile.ZipFile(zip_stream, \\\"w\\\") as zip_file:\\n            for file in files:\\n                file_content = await storage_service.get_file(flow_id=str(file.user_id), file_name=Path(file.path).name)\\n\\n                # Get the file extension from the original filename\\n                file_extension = Path(file.path).suffix\\n                # Create the filename with extension\\n                filename_with_extension = f\\\"{file.name}{file_extension}\\\"\\n\\n                # Write the file to the ZIP with the proper extension\\n                zip_file.writestr(filename_with_extension, file_content)\\n\\n        # Seek to the beginning of the byte stream\\n        zip_stream.seek(0)\\n\\n        # Generate the filename with the current datetime\\n        current_time = datetime.now(tz=ZoneInfo(\\\"UTC\\\")).astimezone().strftime(\\\"%Y%m%d_%H%M%S\\\")\\n        filename = f\\\"{current_time}_langflow_files.zip\\\"\\n\\n        cd = build_content_disposition(filename)\\n        return StreamingResponse(\\n            zip_stream,\\n            media_type=\\\"application/x-zip-compressed\\\",\\n            headers={\\\"Content-Disposition\\\": cd},\\n        )\\n\\n    except FileNotFoundError as e:\\n        raise HTTPException(status_code=404, detail=f\\\"File not found: {e}\\\") from e\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=f\\\"Error downloading files: {e}\\\") from e\\n\\n\\nasync def read_file_content(file_stream: AsyncIterable[bytes] | bytes, *, decode: bool = True) -> str | bytes:\\n    \\\"\\\"\\\"Read file content from a stream or bytes into a string or bytes.\\n\\n    Args:\\n        file_stream: An async iterable yielding bytes or a bytes object.\\n        decode: If True, decode the content to UTF-8; otherwise, return bytes.\\n\\n    Returns:\\n        The file content as a string (if decode=True) or bytes.\\n\\n    Raises:\\n        ValueError: If the stream yields non-bytes chunks.\\n        HTTPException: If decoding fails or an error occurs while reading.\\n    \\\"\\\"\\\"\\n    content = b\\\"\\\"\\n    try:\\n        if isinstance(file_stream, bytes):\\n            content = file_stream\\n        else:\\n            async for chunk in file_stream:\\n                if not isinstance(chunk, bytes):\\n                    msg = \\\"File stream must yield bytes\\\"\\n                    raise TypeError(msg)\\n                content += chunk\\n        if not decode:\\n            return content\\n        try:\\n            return content.decode(\\\"utf-8\\\")\\n        except UnicodeDecodeError as exc:\\n            raise HTTPException(status_code=500, detail=\\\"Invalid file encoding\\\") from exc\\n    except ValueError as exc:\\n        raise HTTPException(status_code=500, detail=f\\\"Error reading file: {exc}\\\") from exc\\n    except Exception as exc:\\n        raise HTTPException(status_code=500, detail=f\\\"Error reading file: {exc}\\\") from exc\\n\\n\\n@router.get(\\\"/{file_id}\\\")\\nasync def download_file(\\n    file_id: uuid.UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n    *,\\n    return_content: bool = False,\\n):\\n    \\\"\\\"\\\"Download a file by its ID or return its content as a string/bytes.\\n\\n    Args:\\n        file_id: UUID of the file.\\n        current_user: Authenticated user.\\n        session: Database session.\\n        storage_service: File storage service.\\n        return_content: If True, return raw content (str) instead of StreamingResponse.\\n\\n    Returns:\\n        StreamingResponse for client downloads or str for internal use.\\n    \\\"\\\"\\\"\\n    try:\\n        # Fetch the file from the DB\\n        file = await fetch_file_object(file_id, current_user, session)\\n        if not file:\\n            raise HTTPException(status_code=404, detail=\\\"File not found\\\")\\n\\n        try:\\n            await ensure_file_permission(\\n                current_user,\\n                FileAction.READ,\\n                file_id=file.id,\\n                file_user_id=file.user_id,\\n            )\\n        except HTTPException as exc:\\n            raise deny_to_404(exc, detail=\\\"File not found\\\") from exc\\n\\n        # Get the basename of the file path. The file lives under the owner's\\n        # storage namespace, not the actor's \u2014 for a shared-file read by a\\n        # non-owner the bytes are at ``flow_id=str(file.user_id)``.\\n        file_name = Path(file.path).name\\n        owner_id = str(file.user_id)\\n\\n        # If return_content is True, read the file content and return it\\n        if return_content:\\n            # For content return, get the full file\\n            file_content = await storage_service.get_file(flow_id=owner_id, file_name=file_name)\\n            if file_content is None:\\n                raise HTTPException(status_code=404, detail=\\\"File not found\\\")\\n            return await read_file_content(file_content, decode=True)\\n\\n        # Check file exists before streaming (to catch errors before response headers are sent)\\n        # This is important because once StreamingResponse starts, we can't change the status code\\n        try:\\n            await storage_service.get_file_size(flow_id=owner_id, file_name=file_name)\\n        except FileNotFoundError as e:\\n            raise HTTPException(status_code=404, detail=f\\\"File not found: {e}\\\") from e\\n\\n        # Wrap the async generator in byte_stream_generator to ensure proper iteration\\n        file_stream = storage_service.get_file_stream(flow_id=owner_id, file_name=file_name)\\n        byte_stream = byte_stream_generator(file_stream)\\n\\n        # Create the filename with extension\\n        file_extension = Path(file.path).suffix\\n        filename_with_extension = f\\\"{file.name}{file_extension}\\\"\\n\\n        # Return the file as a streaming response\\n        cd = build_content_disposition(filename_with_extension)\\n        return StreamingResponse(\\n            byte_stream,\\n            media_type=\\\"application/octet-stream\\\",\\n            headers={\\\"Content-Disposition\\\": cd},\\n        )\\n\\n    except HTTPException:\\n        raise\\n    except FileNotFoundError as e:\\n        raise HTTPException(status_code=404, detail=f\\\"File not found: {e}\\\") from e\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=f\\\"Error downloading file: {e}\\\") from e\\n\\n\\n@router.put(\\\"/{file_id}\\\")\\nasync def edit_file_name(\\n    file_id: uuid.UUID,\\n    name: str,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> UploadFileResponse:\\n    \\\"\\\"\\\"Edit the name of a file by its ID.\\\"\\\"\\\"\\n    try:\\n        # Fetch the file from the DB\\n        file = await fetch_file_object(file_id, current_user, session)\\n        try:\\n            await ensure_file_permission(\\n                current_user,\\n                FileAction.WRITE,\\n                file_id=file.id,\\n                file_user_id=file.user_id,\\n            )\\n        except HTTPException as exc:\\n            raise deny_to_404(exc, detail=\\\"File not found\\\") from exc\\n\\n        # Update the file name\\n        file.name = name\\n        session.add(file)\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=f\\\"Error editing file: {e}\\\") from e\\n\\n    return UploadFileResponse(id=file.id, name=file.name, path=file.path, size=file.size)\\n\\n\\n@router.delete(\\\"/{file_id}\\\")\\nasync def delete_file(\\n    file_id: uuid.UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    \\\"\\\"\\\"Delete a file by its ID.\\\"\\\"\\\"\\n    try:\\n        # Fetch the file object\\n        file_to_delete = await fetch_file_object(file_id, current_user, session)\\n        if not file_to_delete:\\n            raise HTTPException(status_code=404, detail=\\\"File not found\\\")\\n\\n        try:\\n            await ensure_file_permission(\\n                current_user,\\n                FileAction.DELETE,\\n                file_id=file_to_delete.id,\\n                file_user_id=file_to_delete.user_id,\\n            )\\n        except HTTPException as exc:\\n            raise deny_to_404(exc, detail=\\\"File not found\\\") from exc\\n\\n        # Extract just the filename from the path (strip user_id prefix).\\n        # The file lives under the owner's namespace; for shared-file deletes\\n        # by a non-owner, we must point at ``file_to_delete.user_id``.\\n        file_name = Path(file_to_delete.path).name\\n        owner_id = str(file_to_delete.user_id)\\n\\n        # Delete the file from the storage service first\\n        storage_deleted = False\\n        try:\\n            await storage_service.delete_file(flow_id=owner_id, file_name=file_name)\\n            storage_deleted = True\\n        except Exception as err:\\n            # Check if this is a \\\"permanent\\\" failure where file/storage is gone\\n            # These are safe to delete from DB even if storage deletion failed\\n            if is_permanent_storage_failure(err):\\n                await logger.awarning(\\n                    \\\"File %s not found in storage (permanent failure), will remove from database: %s\\\",\\n                    file_name,\\n                    err,\\n                )\\n                storage_deleted = True\\n            else:\\n                # Transient failure (network, timeout, permissions) - keep in DB for retry\\n                await logger.awarning(\\n                    \\\"Failed to delete file %s from storage (transient error, keeping in database for retry): %s\\\",\\n                    file_name,\\n                    err,\\n                )\\n                # Don't delete from DB - user can retry\\n                raise HTTPException(\\n                    status_code=500,\\n                    detail=f\\\"Failed to delete file from storage. Please try again. Error: {err}\\\",\\n                ) from err\\n\\n        # Only delete from database if storage deletion succeeded OR it was a permanent failure\\n        if storage_deleted:\\n            try:\\n                await session.delete(file_to_delete)\\n            except Exception as db_error:\\n                await logger.aerror(\\n                    \\\"Failed to delete file %s from database: %s\\\",\\n                    file_to_delete.name,\\n                    db_error,\\n                )\\n                raise HTTPException(\\n                    status_code=500, detail=f\\\"Error deleting file from database: {db_error}\\\"\\n                ) from db_error\\n\\n            return {\\\"detail\\\": f\\\"File {file_to_delete.name} deleted successfully\\\"}\\n    except HTTPException:\\n        # Re-raise HTTPException to avoid being caught by the generic exception handler\\n        raise\\n    except Exception as e:\\n        # Log and return a generic server error\\n        await logger.aerror(\\\"Error deleting file %s: %s\\\", file_id, e)\\n        raise HTTPException(status_code=500, detail=f\\\"Error deleting file: {e}\\\") from e\\n\\n\\n@router.delete(\\\"\\\")\\n@router.delete(\\\"/\\\", status_code=HTTPStatus.OK)\\nasync def delete_all_files(\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    \\\"\\\"\\\"Delete all files for the current user.\\\"\\\"\\\"\\n    await ensure_file_permission(\\n        current_user,\\n        FileAction.DELETE,\\n        file_user_id=current_user.id,\\n    )\\n    try:\\n        # Fetch all files from the DB\\n        stmt = select(UserFile).where(UserFile.user_id == current_user.id)\\n        results = await session.exec(stmt)\\n        files = results.all()\\n\\n        storage_failures = []\\n        db_failures = []\\n\\n        # Delete all files from the storage service\\n        for file in files:\\n            # Extract just the filename from the path (strip user_id prefix)\\n            file_name = Path(file.path).name\\n            storage_deleted = False\\n\\n            try:\\n                await storage_service.delete_file(flow_id=str(current_user.id), file_name=file_name)\\n                storage_deleted = True\\n            except OSError as err:\\n                # Check if this is a \\\"permanent\\\" failure where file/storage is gone\\n                # These are safe to delete from DB even if storage deletion failed\\n                if is_permanent_storage_failure(err):\\n                    # File/storage is permanently gone - safe to delete from DB\\n                    await logger.awarning(\\n                        \\\"File %s not found in storage, also removing from database: %s\\\",\\n                        file_name,\\n                        err,\\n                    )\\n                    storage_deleted = True\\n                else:\\n                    # Transient failure (network, timeout, permissions) - keep in DB for retry\\n                    storage_failures.append(f\\\"{file_name}: {err}\\\")\\n                    await logger.awarning(\\n                        \\\"Failed to delete file %s from storage (transient error, keeping in database for retry): %s\\\",\\n                        file_name,\\n                        err,\\n                    )\\n\\n            # Only delete from database if storage deletion succeeded OR it was a permanent failure\\n            if storage_deleted:\\n                try:\\n                    await session.delete(file)\\n                except OSError as db_error:\\n                    # Log database deletion failure but continue processing remaining files\\n                    db_failures.append(f\\\"{file_name}: {db_error}\\\")\\n                    await logger.aerror(\\n                        \\\"Failed to delete file %s from database: %s\\\",\\n                        file_name,\\n                        db_error,\\n                    )\\n\\n        if storage_failures:\\n            await logger.awarning(\\n                \\\"Batch delete completed with %d storage failures: %s\\\", len(storage_failures), storage_failures\\n            )\\n\\n        if db_failures:\\n            await logger.aerror(\\\"Batch delete completed with %d database failures: %s\\\", len(db_failures), db_failures)\\n            # If all database deletions failed, raise an error\\n            if len(db_failures) == len(files):\\n                raise HTTPException(status_code=500, detail=f\\\"Failed to delete any files from database: {db_failures}\\\")\\n\\n        # Calculate how many files were actually deleted from database\\n        # Files successfully deleted = total - (kept due to transient storage failures) - (DB deletion failures)\\n        files_deleted = len(files) - len(storage_failures) - len(db_failures)\\n        files_kept = len(storage_failures) + len(db_failures)\\n\\n        if files_deleted == len(files):\\n            message = f\\\"All {files_deleted} files deleted successfully\\\"\\n        elif files_deleted > 0:\\n            message = f\\\"{files_deleted} files deleted successfully\\\"\\n            if files_kept > 0:\\n                message += f\\\", {files_kept} files failed to delete. See logs for details.\\\"\\n        else:\\n            message = \\\"Failed to delete files. See logs for details.\\\"\\n\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=f\\\"Error deleting all files: {e}\\\") from e\\n\\n    return {\\\"message\\\": message}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v2/hitl.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"75ac5d042e1b5c428c0181e83fa11a8e0a9fa89e59daea9124bf9cc912e0d61f\",\"content\":\"\\\"\\\"\\\"Human-in-the-loop persistence + decision validation for the v2 workflows API.\\n\\nThe pause is stored as a chat message so the interactive card survives reload;\\non resume the same message is updated with the chosen action so a reloaded\\nsession renders it as resolved instead of re-offering the decision.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport uuid\\nfrom uuid import UUID\\n\\nfrom lfx.log import logger\\nfrom lfx.run.hitl import reroute_decision_on_timeout\\nfrom sqlalchemy.orm.attributes import flag_modified\\n\\nfrom langflow.services.deps import get_job_service\\n\\n__all__ = [\\n    \\\"ensure_resume_execute_permission\\\",\\n    \\\"is_decision_allowed\\\",\\n    \\\"list_pending_human_requests\\\",\\n    \\\"mark_card_answered\\\",\\n    \\\"persist_human_input_card\\\",\\n    \\\"reroute_decision_on_timeout\\\",\\n]\\n\\n\\nasync def ensure_resume_execute_permission(current_user, flow_id: UUID) -> None:\\n    \\\"\\\"\\\"Re-enforce flow:execute before applying a resume decision.\\n\\n    Resume executes the remainder of the flow; job ownership alone is not enough \u2014\\n    shared access revoked while the run was suspended must not let the decision through.\\n    \\\"\\\"\\\"\\n    from langflow.helpers.flow import get_flow_by_id_or_endpoint_name\\n    from langflow.services.authorization import FlowAction, ensure_flow_permission\\n\\n    flow = await get_flow_by_id_or_endpoint_name(str(flow_id), current_user.id, widen_for_shares=True)\\n    await ensure_flow_permission(\\n        current_user,\\n        FlowAction.EXECUTE,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=getattr(flow, \\\"workspace_id\\\", None),\\n        folder_id=getattr(flow, \\\"folder_id\\\", None),\\n    )\\n\\n\\nasync def list_pending_human_requests(\\n    flow_id: UUID,\\n    user_id: UUID,\\n    *,\\n    request_end_user_id: str | None = None,\\n    include_all_end_users: bool = False,\\n) -> list[dict]:\\n    \\\"\\\"\\\"Suspended HITL jobs for a flow + their pending request, for the Traces overlay.\\n\\n    Traces and jobs are separate stores; the paused state lives on the SUSPENDED job, so\\n    the frontend correlates these to trace rows by ``session_id``.\\n\\n    Serving-plane isolation (B1): this enumerates by flow_id and each row exposes the merged\\n    ``session_id`` + the HITL prompt, so rows are filtered to the requesting end user by the SAME\\n    rule the single-job guard uses (``_end_user_matches``). ``include_all_end_users`` bypasses the\\n    filter for a superuser. Default (feature off / anonymous) keeps only end-user-less jobs, which\\n    on an editor plane is every job \u2014 unchanged behavior.\\n    \\\"\\\"\\\"\\n    from sqlmodel import select\\n\\n    from langflow.api.v2.workflow import _end_user_matches\\n    from langflow.services.database.models.jobs.model import Job, JobStatus, JobType\\n    from langflow.services.deps import session_scope\\n\\n    async with session_scope() as session:\\n        result = await session.exec(\\n            select(Job).where(\\n                Job.flow_id == flow_id,\\n                Job.user_id == user_id,\\n                Job.status == JobStatus.SUSPENDED,\\n                Job.type == JobType.WORKFLOW,\\n            )\\n        )\\n        jobs = list(result.all())\\n\\n    pending: list[dict] = []\\n    for job in jobs:\\n        if not include_all_end_users and not _end_user_matches(request_end_user_id, job.job_metadata):\\n            continue\\n        request = await get_job_service().get_pending_human_request(job.job_id)\\n        if not request:\\n            continue\\n        session_id = ((job.job_metadata or {}).get(\\\"request\\\") or {}).get(\\\"session_id\\\")\\n        pending.append(\\n            {\\n                \\\"job_id\\\": str(job.job_id),\\n                \\\"flow_id\\\": str(job.flow_id),\\n                \\\"session_id\\\": session_id,\\n                \\\"created_at\\\": job.created_timestamp.isoformat() if job.created_timestamp else None,\\n                \\\"request_id\\\": request.get(\\\"request_id\\\"),\\n                \\\"kind\\\": request.get(\\\"kind\\\"),\\n                \\\"prompt\\\": request.get(\\\"prompt\\\"),\\n                \\\"options\\\": request.get(\\\"options\\\") or [],\\n                \\\"allowed_decisions\\\": request.get(\\\"allowed_decisions\\\") or [],\\n            }\\n        )\\n    return pending\\n\\n\\nasync def is_decision_allowed(job_id: UUID, decision: dict) -> bool:\\n    \\\"\\\"\\\"Whether ``decision.action_id`` is one of the pause's allowed decisions.\\n\\n    Returns True when there is no pending request constraining the choice (nothing\\n    to enforce); otherwise the chosen action must be in ``allowed_decisions``.\\n    \\\"\\\"\\\"\\n    pending = await get_job_service().get_pending_human_request(job_id)\\n    allowed = (pending or {}).get(\\\"allowed_decisions\\\") or []\\n    if not allowed:\\n        return True\\n    return decision.get(\\\"action_id\\\") in allowed\\n\\n\\nasync def persist_human_input_card(data: dict, flow_id: uuid.UUID, session_id: str, job_id) -> None:\\n    \\\"\\\"\\\"Persist the pause as a chat message so the interactive card survives reload.\\n\\n    The card carries request_id + job_id, so a reloaded session can resume the run.\\n    Records the card's message id in job metadata so resume can mark it answered.\\n    \\\"\\\"\\\"\\n    from lfx.memory.flow_context import derive_message_owner_uuid\\n    from lfx.schema.content_block import ContentBlock\\n    from lfx.schema.content_types import HumanInputContent\\n    from lfx.schema.message import Message\\n    from lfx.workflow.end_user_identity import end_user_id_from_scoped_session\\n\\n    from langflow.memory import astore_message\\n\\n    content = HumanInputContent(\\n        request_id=data.get(\\\"request_id\\\", \\\"\\\"),\\n        job_id=str(job_id) if job_id else None,\\n        kind=data.get(\\\"kind\\\", \\\"node_input\\\"),\\n        prompt=data.get(\\\"prompt\\\"),\\n        options=data.get(\\\"options\\\") or [],\\n        fields=data.get(\\\"schema\\\") or [],\\n        allowed_decisions=data.get(\\\"allowed_decisions\\\") or [],\\n    )\\n    block = ContentBlock(title=\\\"Human input required\\\", contents=[content])\\n    message = Message(\\n        text=\\\"\\\",\\n        sender=\\\"Machine\\\",\\n        sender_name=\\\"AI\\\",\\n        session_id=session_id,\\n        flow_id=flow_id,\\n        content_blocks=[block],\\n    )\\n    # Stamp the serving-plane owner so this card is retrievable through the per-user monitor pull\\n    # (GET /monitor/messages?end_user_id=...). The card is built by hand and bypasses\\n    # Component._store_message, so without this it persists user_id=NULL and the owner's own pull\\n    # misses it (the pull's predicate is an exact owner match, so NULL never returns). The scoped\\n    # session carries the end user (<end_user>::<base>); resolve it through the same helpers the\\n    # component write path and the monitor read path use so write == read. None off / editor /\\n    # anonymous -> NULL, unchanged. See BUG-02.\\n    owner_end_user = end_user_id_from_scoped_session(session_id)\\n    owner_user_id = derive_message_owner_uuid(owner_end_user) if owner_end_user else None\\n    try:\\n        stored = await astore_message(\\n            message, flow_id=flow_id, run_id=str(job_id) if job_id else None, user_id=owner_user_id\\n        )\\n        if stored and job_id is not None:\\n            await get_job_service().update_job_metadata(uuid.UUID(str(job_id)), {\\\"card_message_id\\\": str(stored[0].id)})\\n    except Exception:  # noqa: BLE001\\n        await logger.awarning(\\\"Failed to persist human-input card for flow %s\\\", flow_id, exc_info=True)\\n\\n\\ndef _set_submitted_action(content_blocks: list, action_id: str | None, request_id: str | None = None) -> bool:\\n    \\\"\\\"\\\"Stamp ``submitted_action`` on the card's content in place, preserving the rest.\\n\\n    With ``request_id`` set, only a content whose ``request_id`` matches is stamped, so\\n    a decision can never resolve a different pause's card.\\n    \\\"\\\"\\\"\\n    changed = False\\n    for block in content_blocks or []:\\n        contents = block.get(\\\"contents\\\") if isinstance(block, dict) else getattr(block, \\\"contents\\\", None)\\n        for content in contents or []:\\n            is_dict = isinstance(content, dict)\\n            ctype = content.get(\\\"type\\\") if is_dict else getattr(content, \\\"type\\\", None)\\n            if ctype != \\\"human_input\\\":\\n                continue\\n            card_request_id = content.get(\\\"request_id\\\") if is_dict else getattr(content, \\\"request_id\\\", None)\\n            if request_id is not None and card_request_id != request_id:\\n                continue\\n            if is_dict:\\n                content[\\\"submitted_action\\\"] = action_id\\n            else:\\n                content.submitted_action = action_id\\n            changed = True\\n    return changed\\n\\n\\ndef _mark_superseded(content_blocks: list) -> bool:\\n    \\\"\\\"\\\"Flag every still-open human_input content as superseded, in place.\\\"\\\"\\\"\\n    changed = False\\n    for block in content_blocks or []:\\n        contents = block.get(\\\"contents\\\") if isinstance(block, dict) else getattr(block, \\\"contents\\\", None)\\n        for content in contents or []:\\n            is_dict = isinstance(content, dict)\\n            ctype = content.get(\\\"type\\\") if is_dict else getattr(content, \\\"type\\\", None)\\n            if ctype != \\\"human_input\\\":\\n                continue\\n            answered = content.get(\\\"submitted_action\\\") if is_dict else getattr(content, \\\"submitted_action\\\", None)\\n            if answered is not None:\\n                continue\\n            if is_dict:\\n                content[\\\"superseded\\\"] = True\\n            else:\\n                content.superseded = True\\n            changed = True\\n    return changed\\n\\n\\nasync def mark_card_superseded(job_id: UUID) -> None:\\n    \\\"\\\"\\\"Close the persisted card of a run cancelled by supersede/stop.\\n\\n    Without this the reloaded card (no ``submitted_action``) turns interactive\\n    again and every click 409s against the cancelled job. Patched in place like\\n    ``mark_card_answered`` so prompt/options are preserved for the history.\\n    \\\"\\\"\\\"\\n    from lfx.services.deps import session_scope\\n\\n    from langflow.services.database.models.message.model import MessageTable\\n\\n    job = await get_job_service().get_job_by_job_id(job_id)\\n    card_message_id = (job.job_metadata or {}).get(\\\"card_message_id\\\") if job else None\\n    if not card_message_id:\\n        return\\n    try:\\n        async with session_scope() as session:\\n            message = await session.get(MessageTable, UUID(str(card_message_id)))\\n            if message is None:\\n                return\\n            if _mark_superseded(message.content_blocks):\\n                flag_modified(message, \\\"content_blocks\\\")\\n                session.add(message)\\n    except Exception as _e:  # noqa: BLE001\\n        await logger.awarning(\\\"Failed to mark human-input card superseded for job %s: %r\\\", job_id, _e)\\n\\n\\nasync def mark_card_answered(job_id: UUID, request_id: str, decision: dict, *, card_message_id=None) -> None:\\n    \\\"\\\"\\\"Record the chosen action on the persisted card message for ``job_id``.\\n\\n    Patches the existing card in place so the prompt/options it was stored with are\\n    preserved \u2014 rebuilding from the suspend event would drop them. Callers should pass\\n    the ``card_message_id`` they read BEFORE enqueuing the continuation: the resumed run\\n    may reach another pause and overwrite job metadata, and the stamp must land on the\\n    answered card, not the new one (``request_id`` is enforced against the card content\\n    as a second guard).\\n    \\\"\\\"\\\"\\n    from lfx.services.deps import session_scope\\n\\n    from langflow.services.database.models.message.model import MessageTable\\n\\n    if card_message_id is None:\\n        job = await get_job_service().get_job_by_job_id(job_id)\\n        card_message_id = (job.job_metadata or {}).get(\\\"card_message_id\\\") if job else None\\n    if not card_message_id:\\n        return\\n    try:\\n        async with session_scope() as session:\\n            message = await session.get(MessageTable, UUID(str(card_message_id)))\\n            if message is None:\\n                return\\n            if _set_submitted_action(message.content_blocks, decision.get(\\\"action_id\\\"), request_id):\\n                flag_modified(message, \\\"content_blocks\\\")\\n                session.add(message)\\n    except Exception as _e:  # noqa: BLE001\\n        await logger.awarning(\\\"Failed to mark human-input card answered for job %s: %r\\\", job_id, _e)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v2/mcp.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4d807eaa7431902251a53f11624ce8a73931c639c8b290edbec31b875bec961e\",\"content\":\"import json\\nfrom datetime import datetime, timezone\\nfrom io import BytesIO\\nfrom typing import Annotated\\n\\nfrom fastapi import APIRouter, Body, Depends, HTTPException, UploadFile\\nfrom lfx.base.agents.utils import safe_cache_get, safe_cache_set\\nfrom lfx.base.mcp.util import update_tools\\nfrom sqlalchemy import update\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlmodel import select\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.v2.files import (\\n    MCP_SERVERS_FILE,\\n    download_file,\\n    edit_file_name,\\n    get_file_by_name,\\n    get_mcp_file,\\n    upload_user_file,\\n)\\nfrom langflow.api.v2.schemas import MCPServerConfig\\nfrom langflow.logging import logger\\nfrom langflow.services.auth.mcp_encryption import decrypt_mcp_config, encrypt_mcp_config\\nfrom langflow.services.database.models import MCPServer\\nfrom langflow.services.deps import get_settings_service, get_shared_component_cache_service, get_storage_service\\nfrom langflow.services.settings.service import SettingsService\\nfrom langflow.services.storage.service import StorageService\\n\\nrouter = APIRouter(tags=[\\\"MCP\\\"], prefix=\\\"/mcp\\\")\\n\\n# Retry budget for the version-guarded merge-PATCH path (only same-server merges consume it).\\n_MAX_UPSERT_RETRIES = 12\\n\\n\\ndef is_mcp_servers_locked(settings: object) -> bool:\\n    \\\"\\\"\\\"Return True only when MCP lock is explicitly enabled.\\n\\n    Some tests patch settings with MagicMock objects where unknown attributes\\n    resolve to truthy placeholders. Using ``is True`` ensures lock enforcement\\n    only when the flag is explicitly set to ``True``.\\n    \\\"\\\"\\\"\\n    return getattr(settings, \\\"mcp_servers_locked\\\", False) is True\\n\\n\\ndef ensure_mcp_stdio_access(server_config: dict, current_user: CurrentActiveUser, settings: object) -> None:\\n    \\\"\\\"\\\"Restrict local MCP processes when custom code execution is restricted.\\\"\\\"\\\"\\n    mode = server_config.get(\\\"mode\\\")\\n    is_stdio = bool(server_config.get(\\\"command\\\")) or (isinstance(mode, str) and mode.lower() == \\\"stdio\\\")\\n    code_execution_restricted = (\\n        getattr(settings, \\\"allow_custom_components\\\", True) is False\\n        or getattr(settings, \\\"custom_component_admin_only\\\", False) is True\\n        or getattr(settings, \\\"block_code_interpreter_components\\\", False) is True\\n    )\\n\\n    if is_stdio and code_execution_restricted and getattr(current_user, \\\"is_superuser\\\", False) is not True:\\n        raise HTTPException(\\n            status_code=403,\\n            detail=\\\"MCP stdio servers are restricted to administrators when custom code execution is restricted.\\\",\\n        )\\n\\n\\ndef _enforce_immutable_server_name(server_name: str, server_config: dict) -> dict:\\n    \\\"\\\"\\\"Enforce that the server name is owned by the URL path, not the request body.\\n\\n    ``server_name`` is the immutable identifier for an MCP server: it is both the\\n    storage key and the POST/PATCH URL path segment. Because :class:`MCPServerConfig`\\n    permits extra fields (``extra=\\\"allow\\\"``), a ``name`` in the request body would\\n    otherwise be silently persisted as stray config data and \u2014 on PATCH \u2014 echoed back\\n    in the 200 response, falsely implying that a rename succeeded.\\n\\n    A body ``name`` that disagrees with the URL is rejected with 422 so the constraint\\n    is explicit. A redundant but matching ``name`` is dropped so it never pollutes the\\n    stored config.\\n\\n    Args:\\n        server_name: The server name from the URL path (the canonical identifier).\\n        server_config: The request body dumped to a dict.\\n\\n    Returns:\\n        A config dict with any ``name`` key removed.\\n\\n    Raises:\\n        HTTPException: 422 when ``name`` is present and differs from ``server_name``.\\n    \\\"\\\"\\\"\\n    if \\\"name\\\" not in server_config:\\n        return server_config\\n\\n    body_name = server_config[\\\"name\\\"]\\n    if body_name != server_name:\\n        raise HTTPException(\\n            status_code=422,\\n            detail=(\\n                f\\\"Server name is immutable and is determined by the URL path \\\"\\n                f\\\"('{server_name}'); it cannot be set or changed via the request body \\\"\\n                f\\\"(got '{body_name}'). To rename a server, delete it and create a new one.\\\"\\n            ),\\n        )\\n    # Matching name is redundant \u2014 drop it so it isn't persisted as stray config.\\n    return {key: value for key, value in server_config.items() if key != \\\"name\\\"}\\n\\n\\nasync def upload_server_config(\\n    server_config: dict,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n):\\n    content_str = json.dumps(server_config)\\n    content_bytes = content_str.encode(\\\"utf-8\\\")  # Convert to bytes\\n    file_obj = BytesIO(content_bytes)  # Use BytesIO for binary data\\n\\n    mcp_file = await get_mcp_file(current_user, extension=True)\\n    upload_file = UploadFile(file=file_obj, filename=mcp_file, size=len(content_str))\\n\\n    return await upload_user_file(\\n        file=upload_file,\\n        session=session,\\n        current_user=current_user,\\n        storage_service=storage_service,\\n        settings_service=settings_service,\\n    )\\n\\n\\nasync def get_server_list(\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],  # noqa: ARG001\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],  # noqa: ARG001\\n):\\n    \\\"\\\"\\\"Return the user's MCP servers as ``{\\\"mcpServers\\\": {name: config}}``.\\n\\n    Backed by the ``mcp_server`` table (one row per server), replacing the per-user\\n    JSON file. Secret-bearing values are decrypted on the way out so the response\\n    stays a runnable ``mcpServers`` map. ``storage_service`` / ``settings_service``\\n    are retained for signature compatibility with every caller.\\n    \\\"\\\"\\\"\\n    # Order by created_at so the list is stable and preserves insertion order, matching\\n    # the legacy file (a dict) that callers and the UI relied on (e.g. the starter\\n    # project server stays first).\\n    result = await session.exec(\\n        select(MCPServer).where(MCPServer.user_id == current_user.id).order_by(MCPServer.created_at)\\n    )\\n    servers = {row.name: decrypt_mcp_config(row.config or {}) for row in result.all()}\\n    return {\\\"mcpServers\\\": servers}\\n\\n\\nasync def _read_legacy_mcp_file(\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n    *,\\n    create_if_missing: bool = True,\\n):\\n    \\\"\\\"\\\"Read the legacy per-user ``_mcp_servers_<id>.json`` file from storage.\\n\\n    Preserved for the file\u2192table backfill (and any future file-fallback path); this\\n    is the pre-DB ``get_server_list`` body. Works against any storage backend (local\\n    disk or S3) because it goes through the storage service. ``create_if_missing=False``\\n    (used by the backfill) returns an empty config instead of writing a new empty file\\n    for users who never configured MCP.\\n    \\\"\\\"\\\"\\n    # Backwards compatibility with old format file name\\n    mcp_file = await get_mcp_file(current_user)\\n    old_format_config_file = await get_file_by_name(MCP_SERVERS_FILE, current_user, session)\\n    if old_format_config_file:\\n        await edit_file_name(old_format_config_file.id, mcp_file, current_user, session)\\n\\n    # Read the server configuration from a file using the files api\\n    server_config_file = await get_file_by_name(mcp_file, current_user, session)\\n\\n    # Attempt to download the configuration file content\\n    try:\\n        server_config_bytes = await download_file(\\n            server_config_file.id if server_config_file else None,\\n            current_user,\\n            session,\\n            storage_service=storage_service,\\n            return_content=True,\\n        )\\n    except (FileNotFoundError, HTTPException):\\n        if server_config_file:\\n            # DB record exists but storage file is missing \u2014 likely a transient state\\n            # during a concurrent update_server() write cycle. Return empty config\\n            # WITHOUT persisting to avoid permanently wiping existing servers.\\n            logger.warning(\\n                \\\"MCP config file missing from storage for user %s (transient). \\\"\\n                \\\"Returning empty config without persisting.\\\",\\n                current_user.id,\\n            )\\n            return {\\\"mcpServers\\\": {}}\\n\\n        # No DB record and no storage file \u2014 genuinely first-time use.\\n        if not create_if_missing:\\n            return {\\\"mcpServers\\\": {}}\\n        await upload_server_config(\\n            {\\\"mcpServers\\\": {}},\\n            current_user,\\n            session,\\n            storage_service=storage_service,\\n            settings_service=settings_service,\\n        )\\n\\n        # Fetch and download again\\n        mcp_file = await get_mcp_file(current_user)\\n        server_config_file = await get_file_by_name(mcp_file, current_user, session)\\n        if not server_config_file:\\n            raise HTTPException(status_code=500, detail=\\\"Failed to create MCP Servers configuration file\\\") from None\\n\\n        server_config_bytes = await download_file(\\n            server_config_file.id,\\n            current_user,\\n            session,\\n            storage_service=storage_service,\\n            return_content=True,\\n        )\\n\\n    # Parse JSON content\\n    try:\\n        servers = json.loads(server_config_bytes)\\n    except json.JSONDecodeError:\\n        raise HTTPException(status_code=500, detail=\\\"Invalid server configuration file format.\\\") from None\\n\\n    return servers\\n\\n\\nasync def get_server(\\n    server_name: str,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],  # noqa: ARG001\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],  # noqa: ARG001\\n    server_list: dict | None = None,\\n):\\n    \\\"\\\"\\\"Get a specific server's config (decrypted), or ``None`` if it doesn't exist.\\\"\\\"\\\"\\n    if server_list is not None:\\n        return server_list[\\\"mcpServers\\\"].get(server_name)\\n\\n    result = await session.exec(\\n        select(MCPServer).where(MCPServer.user_id == current_user.id, MCPServer.name == server_name)\\n    )\\n    row = result.first()\\n    if row is None:\\n        return None\\n    return decrypt_mcp_config(row.config or {})\\n\\n\\n# Define a Get servers endpoint\\n@router.get(\\\"/servers\\\")\\nasync def get_servers(\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n    *,\\n    action_count: bool | None = None,\\n):\\n    \\\"\\\"\\\"Get the list of available servers.\\\"\\\"\\\"\\n    import asyncio\\n\\n    from lfx.base.mcp.util import MCPStdioClient, MCPStreamableHttpClient\\n\\n    server_list = await get_server_list(current_user, session, storage_service, settings_service)\\n\\n    if not action_count:\\n        # Return only the server names, with mode and toolsCount as None\\n        return [{\\\"name\\\": server_name, \\\"mode\\\": None, \\\"toolsCount\\\": None} for server_name in server_list[\\\"mcpServers\\\"]]\\n\\n    for server_config in server_list[\\\"mcpServers\\\"].values():\\n        ensure_mcp_stdio_access(server_config, current_user, settings_service.settings)\\n\\n    # Check all of the tool counts for each server concurrently\\n    async def check_server(server_name: str) -> dict:\\n        server_info: dict[str, str | int | None] = {\\\"name\\\": server_name, \\\"mode\\\": None, \\\"toolsCount\\\": None}\\n        # Create clients that we control so we can clean them up after\\n        mcp_stdio_client = MCPStdioClient()\\n        mcp_streamable_http_client = MCPStreamableHttpClient()\\n        try:\\n            # Get global variables from database for header resolution\\n            request_variables = {}\\n            try:\\n                from sqlmodel import select\\n\\n                from langflow.services.auth import utils as auth_utils\\n                from langflow.services.database.models.variable.model import Variable\\n\\n                # Load variables directly from database and decrypt ALL types (including CREDENTIAL)\\n                stmt = select(Variable).where(Variable.user_id == current_user.id)\\n                variables = list((await session.exec(stmt)).all())\\n\\n                # Decrypt variables based on type (following the pattern from get_all_decrypted_variables)\\n                for variable in variables:\\n                    if variable.name and variable.value:\\n                        # Prior to v1.8, both Generic and Credential variables were encrypted.\\n                        # As such, must attempt to decrypt both types to ensure backwards-compatibility.\\n                        try:\\n                            decrypted_value = auth_utils.decrypt_api_key(variable.value)\\n                            request_variables[variable.name] = decrypted_value\\n                        except Exception as e:  # noqa: BLE001\\n                            await logger.aerror(\\n                                f\\\"Failed to decrypt credential variable '{variable.name}': {e}. \\\"\\n                                \\\"This credential will not be available for MCP server.\\\"\\n                            )\\n            except Exception as e:  # noqa: BLE001\\n                await logger.awarning(f\\\"Failed to load global variables for MCP server test: {e}\\\")\\n\\n            mode, tool_list, _ = await update_tools(\\n                server_name=server_name,\\n                server_config=server_list[\\\"mcpServers\\\"][server_name],\\n                mcp_stdio_client=mcp_stdio_client,\\n                mcp_streamable_http_client=mcp_streamable_http_client,\\n                request_variables=request_variables,\\n                # These are read straight from the variable table above, so they are the\\n                # DB-backed set the URL is allowed to resolve from.\\n                url_variables=request_variables,\\n                current_user_id=current_user.id,\\n            )\\n            server_info[\\\"mode\\\"] = mode.lower()\\n            server_info[\\\"toolsCount\\\"] = len(tool_list)\\n            if len(tool_list) == 0:\\n                server_info[\\\"error\\\"] = \\\"No tools found\\\"\\n        except ValueError as e:\\n            # Configuration validation errors, invalid URLs, etc.\\n            await logger.aerror(f\\\"Configuration error for server {server_name}: {e}\\\")\\n            server_info[\\\"error\\\"] = f\\\"Configuration error: {e}\\\"\\n        except ConnectionError as e:\\n            # Network connection and timeout issues\\n            await logger.aerror(f\\\"Connection error for server {server_name}: {e}\\\")\\n            server_info[\\\"error\\\"] = f\\\"Connection failed: {e}\\\"\\n        except (TimeoutError, asyncio.TimeoutError) as e:\\n            # Timeout errors\\n            await logger.aerror(f\\\"Timeout error for server {server_name}: {e}\\\")\\n            server_info[\\\"error\\\"] = \\\"Timeout when checking server tools\\\"\\n        except OSError as e:\\n            # System-level errors (process execution, file access)\\n            await logger.aerror(f\\\"System error for server {server_name}: {e}\\\")\\n            server_info[\\\"error\\\"] = f\\\"System error: {e}\\\"\\n        except (KeyError, TypeError) as e:\\n            # Data parsing and access errors\\n            await logger.aerror(f\\\"Data error for server {server_name}: {e}\\\")\\n            server_info[\\\"error\\\"] = f\\\"Configuration data error: {e}\\\"\\n        except (RuntimeError, ProcessLookupError, PermissionError) as e:\\n            # Runtime and process-related errors\\n            await logger.aerror(f\\\"Runtime error for server {server_name}: {e}\\\")\\n            server_info[\\\"error\\\"] = f\\\"Runtime error: {e}\\\"\\n        except Exception as e:  # noqa: BLE001\\n            # Generic catch-all for other exceptions (including ExceptionGroup)\\n            if hasattr(e, \\\"exceptions\\\") and e.exceptions:\\n                # Extract the first underlying exception for a more meaningful error message\\n                underlying_error = e.exceptions[0]\\n                if hasattr(underlying_error, \\\"exceptions\\\"):\\n                    await logger.aerror(\\n                        f\\\"Error checking server {server_name}: {underlying_error}, {underlying_error.exceptions}\\\"\\n                    )\\n                    underlying_error = underlying_error.exceptions[0]\\n                else:\\n                    await logger.aexception(f\\\"Error checking server {server_name}: {underlying_error}\\\")\\n                server_info[\\\"error\\\"] = f\\\"Error loading server: {underlying_error}\\\"\\n            else:\\n                await logger.aexception(f\\\"Error checking server {server_name}: {e}\\\")\\n                server_info[\\\"error\\\"] = f\\\"Error loading server: {e}\\\"\\n        finally:\\n            # Always disconnect clients to prevent mcp-proxy process leaks\\n            # These clients spawn subprocesses that need to be explicitly terminated\\n            await mcp_stdio_client.disconnect()\\n            await mcp_streamable_http_client.disconnect()\\n        return server_info\\n\\n    # Run all server checks concurrently\\n    tasks = [check_server(server) for server in server_list[\\\"mcpServers\\\"]]\\n    return await asyncio.gather(*tasks, return_exceptions=True)\\n\\n\\n@router.get(\\\"/servers/{server_name}\\\")\\nasync def get_server_endpoint(\\n    server_name: str,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n):\\n    \\\"\\\"\\\"Get a specific server.\\\"\\\"\\\"\\n    return await get_server(server_name, current_user, session, storage_service, settings_service)\\n\\n\\ndef _derive_transport(config: dict) -> str | None:\\n    \\\"\\\"\\\"Best-effort transport label stored alongside the row (informational).\\\"\\\"\\\"\\n    if config.get(\\\"command\\\"):\\n        return \\\"stdio\\\"\\n    return config.get(\\\"type\\\") or (\\\"streamable-http\\\" if config.get(\\\"url\\\") else None)\\n\\n\\ndef _clear_server_cache(server_name: str) -> None:\\n    \\\"\\\"\\\"Drop a server from the shared tool cache after it changes (best-effort).\\n\\n    Cache keys are ``{server_name}:{hash of headers+timeout}`` (see\\n    ``MCPComponent._mcp_servers_cache_key``), so a bare-name delete misses the\\n    hashed variants and leaves servers with custom headers/timeouts serving stale\\n    config. Clear the bare name and every ``{server_name}:`` variant.\\n    \\\"\\\"\\\"\\n    shared_component_cache_service = get_shared_component_cache_service()\\n    servers = safe_cache_get(shared_component_cache_service, \\\"servers\\\", {})\\n    if isinstance(servers, dict):\\n        stale = [key for key in servers if key == server_name or key.startswith(f\\\"{server_name}:\\\")]\\n        for key in stale:\\n            del servers[key]\\n        safe_cache_set(shared_component_cache_service, \\\"servers\\\", servers)\\n\\n\\nasync def _persist(session, *, owns_transaction: bool) -> None:\\n    \\\"\\\"\\\"Commit when we own the transaction, otherwise just flush for the owner.\\\"\\\"\\\"\\n    if owns_transaction:\\n        await session.commit()\\n    else:\\n        await session.flush()\\n\\n\\nasync def update_server(\\n    server_name: str,\\n    server_config: dict,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],  # noqa: ARG001\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n    *,\\n    check_existing: bool = False,\\n    delete: bool = False,\\n    merge_existing: bool = False,\\n    owns_transaction: bool = True,\\n):\\n    \\\"\\\"\\\"Create, update, or delete one MCP server row for the user.\\n\\n    Upserts a single row keyed on ``(user_id, name)`` so concurrent edits to different\\n    servers never contend. A merge PATCH guards its write with the row ``version`` and\\n    retries on conflict, so two concurrent PATCHes to the same server merge instead of\\n    last-writer-wins; a full replace updates unconditionally. ``current_user`` is read\\n    once into ``user_id`` because a later commit/rollback can expire it and re-reading it\\n    would attempt IO in an async context.\\n\\n    ``owns_transaction=False`` is for callers that already own the transaction - notably\\n    the startup reconciliation, which runs inside ``session.begin_nested()``. Committing\\n    there would end the transaction the caller's context manager owns, so every later\\n    statement (including this function's own trailing read) raises ``InvalidRequestError:\\n    Can't operate on closed transaction inside context manager``, and it would also\\n    escape any rollback the caller relies on for atomicity. Flushing instead keeps the\\n    write visible to the rest of the caller's transaction while leaving commit/rollback\\n    to whoever opened it.\\n    \\\"\\\"\\\"\\n    user_id = current_user.id\\n    settings = getattr(settings_service, \\\"settings\\\", None)\\n    if not delete:\\n        ensure_mcp_stdio_access(server_config, current_user, settings)\\n\\n    if delete:\\n        result = await session.exec(\\n            select(MCPServer).where(MCPServer.user_id == user_id, MCPServer.name == server_name)\\n        )\\n        existing = result.first()\\n        if existing is None:\\n            raise HTTPException(status_code=404, detail=\\\"Server not found.\\\")\\n        await session.delete(existing)\\n        await _persist(session, owns_transaction=owns_transaction)\\n        _clear_server_cache(server_name)\\n        return None\\n\\n    result = await session.exec(select(MCPServer).where(MCPServer.user_id == user_id, MCPServer.name == server_name))\\n    existing = result.first()\\n\\n    for _ in range(_MAX_UPSERT_RETRIES):\\n        if check_existing and existing is not None:\\n            raise HTTPException(status_code=409, detail=\\\"Server already exists.\\\")\\n\\n        if existing is None:\\n            session.add(\\n                MCPServer(\\n                    user_id=user_id,\\n                    name=server_name,\\n                    config=encrypt_mcp_config(server_config),\\n                    transport=_derive_transport(server_config),\\n                )\\n            )\\n            try:\\n                await _persist(session, owns_transaction=owns_transaction)\\n            except IntegrityError:\\n                # The expected IntegrityError here is the duplicate-name race: re-read the\\n                # winner and fall through to the update path. Any other integrity failure\\n                # (e.g. a bad FK) leaves no winning row, so re-raise it instead of masking\\n                # it as retries that end in a misleading 409.\\n                if not owns_transaction:\\n                    # Recovering here needs a rollback, which on a borrowed transaction would\\n                    # discard the caller's work too. Let the caller's savepoint unwind instead.\\n                    raise\\n                await session.rollback()\\n                result = await session.exec(\\n                    select(MCPServer).where(MCPServer.user_id == user_id, MCPServer.name == server_name)\\n                )\\n                existing = result.first()\\n                if existing is None:\\n                    raise\\n                continue\\n            break\\n\\n        if merge_existing:\\n            merged = {**decrypt_mcp_config(existing.config or {}), **server_config}\\n            ensure_mcp_stdio_access(merged, current_user, settings)\\n            updated = await session.execute(\\n                update(MCPServer)\\n                .where(MCPServer.id == existing.id, MCPServer.version == existing.version)\\n                .values(\\n                    config=encrypt_mcp_config(merged),\\n                    transport=_derive_transport(merged),\\n                    version=existing.version + 1,\\n                    updated_at=datetime.now(timezone.utc),\\n                )\\n            )\\n            await _persist(session, owns_transaction=owns_transaction)\\n            if updated.rowcount == 1:\\n                break\\n            # Version moved under us: expire and re-read so a concurrent delete reads as None.\\n            session.expire(existing)\\n            result = await session.exec(\\n                select(MCPServer).where(MCPServer.user_id == user_id, MCPServer.name == server_name)\\n            )\\n            existing = result.first()\\n            if existing is None:\\n                raise HTTPException(status_code=404, detail=\\\"Server not found.\\\")\\n            continue\\n\\n        # Full replace: last-writer-wins on config, but bump the version DB-side\\n        # (version = version + 1) so it stays strictly monotonic even when our ORM copy\\n        # is stale. An ORM `+= 1` off a stale read could reuse a version a concurrent\\n        # PATCH already consumed, letting a later guarded PATCH pass its version check.\\n        replaced = await session.execute(\\n            update(MCPServer)\\n            .where(MCPServer.id == existing.id)\\n            .values(\\n                config=encrypt_mcp_config(server_config),\\n                transport=_derive_transport(server_config),\\n                version=MCPServer.version + 1,\\n                updated_at=datetime.now(timezone.utc),\\n            )\\n        )\\n        await _persist(session, owns_transaction=owns_transaction)\\n        if replaced.rowcount == 1:\\n            break\\n        # Row deleted under us: re-read, and a still-missing row takes the create path\\n        # next iteration \u2014 the replace converges to a re-create instead of silently\\n        # returning None with the write lost.\\n        session.expire(existing)\\n        result = await session.exec(\\n            select(MCPServer).where(MCPServer.user_id == user_id, MCPServer.name == server_name)\\n        )\\n        existing = result.first()\\n    else:\\n        raise HTTPException(status_code=409, detail=\\\"MCP server was updated concurrently; please retry.\\\")\\n\\n    _clear_server_cache(server_name)\\n    result = await session.exec(select(MCPServer).where(MCPServer.user_id == user_id, MCPServer.name == server_name))\\n    row = result.first()\\n    return decrypt_mcp_config(row.config or {}) if row is not None else None\\n\\n\\n@router.post(\\\"/servers/{server_name}\\\")\\nasync def add_server(\\n    server_name: str,\\n    *,\\n    server_config: Annotated[MCPServerConfig, Body()],\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n):\\n    if is_mcp_servers_locked(settings_service.settings) and not current_user.is_superuser:\\n        raise HTTPException(\\n            status_code=403,\\n            detail=\\\"MCP server configuration is locked. Contact an administrator to manage external MCP servers.\\\",\\n        )\\n\\n    return await update_server(\\n        server_name,\\n        _enforce_immutable_server_name(server_name, server_config.model_dump(exclude_unset=True)),\\n        current_user,\\n        session,\\n        storage_service,\\n        settings_service,\\n        check_existing=True,\\n    )\\n\\n\\n@router.patch(\\\"/servers/{server_name}\\\")\\nasync def update_server_endpoint(\\n    server_name: str,\\n    *,\\n    server_config: Annotated[MCPServerConfig, Body()],\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n):\\n    if is_mcp_servers_locked(settings_service.settings) and not current_user.is_superuser:\\n        raise HTTPException(\\n            status_code=403,\\n            detail=\\\"MCP server configuration is locked. Contact an administrator to manage external MCP servers.\\\",\\n        )\\n\\n    return await update_server(\\n        server_name,\\n        _enforce_immutable_server_name(server_name, server_config.model_dump(exclude_unset=True)),\\n        current_user,\\n        session,\\n        storage_service,\\n        settings_service,\\n        merge_existing=True,\\n    )\\n\\n\\n@router.delete(\\\"/servers/{server_name}\\\")\\nasync def delete_server(\\n    server_name: str,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n):\\n    if is_mcp_servers_locked(settings_service.settings) and not current_user.is_superuser:\\n        raise HTTPException(\\n            status_code=403,\\n            detail=\\\"MCP server configuration is locked. Contact an administrator to manage external MCP servers.\\\",\\n        )\\n\\n    return await update_server(\\n        server_name,\\n        {},\\n        current_user,\\n        session,\\n        storage_service,\\n        settings_service,\\n        delete=True,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v2/registration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4205d879c6ab1337c54bca9cbe6733c45a2dea126bb3f26bf390f15ba07a1b09\",\"content\":\"import json\\nfrom asyncio import to_thread\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\n\\nfrom fastapi import APIRouter, Depends, HTTPException\\nfrom pydantic import BaseModel, EmailStr\\n\\nfrom langflow.logging import logger\\nfrom langflow.services.auth.utils import get_current_active_user\\nfrom langflow.services.deps import get_telemetry_service\\nfrom langflow.services.telemetry.schema import EmailPayload\\n\\nrouter = APIRouter(tags=[\\\"Registration API\\\"], prefix=\\\"/registration\\\", include_in_schema=False)\\n\\n\\n# Data model for registration\\nclass RegisterRequest(BaseModel):\\n    email: EmailStr\\n\\n\\nclass RegisterResponse(BaseModel):\\n    email: str\\n\\n\\n# File to store registrations\\nREGISTRATION_FILE = Path(\\\"data/user/registration.json\\\")\\n\\n\\ndef _ensure_registration_file():\\n    \\\"\\\"\\\"Ensure registration file and directory exist with proper permissions.\\\"\\\"\\\"\\n    try:\\n        # Ensure the directory exists with secure permissions\\n        REGISTRATION_FILE.parent.mkdir(parents=True, exist_ok=True)\\n        # Set directory permissions to owner read/write/execute only (if possible)\\n        REGISTRATION_FILE.parent.chmod(0o700)\\n    except Exception as e:\\n        logger.error(f\\\"Failed to create registration file/directory: {e}\\\")\\n        raise\\n\\n\\n# TODO: Move functions to a separate service module\\n\\n\\ndef load_registration() -> dict | None:\\n    \\\"\\\"\\\"Load the single registration from file.\\\"\\\"\\\"\\n    if not REGISTRATION_FILE.exists() or REGISTRATION_FILE.stat().st_size == 0:\\n        return None\\n    try:\\n        with REGISTRATION_FILE.open(\\\"rb\\\") as f:  # using binary mode for faster file IO\\n            content = f.read()\\n        return json.loads(content)\\n    except (json.JSONDecodeError, UnicodeDecodeError):\\n        logger.error(f\\\"Corrupted registration file: {REGISTRATION_FILE}\\\")\\n        return None\\n\\n\\ndef save_registration(email: str) -> bool:\\n    \\\"\\\"\\\"Save the single registration to file.\\n\\n    Args:\\n        email: Email to register\\n\\n    Returns:\\n        True if saved successfully\\n    \\\"\\\"\\\"\\n    try:\\n        # Ensure the registration file and directory exist\\n        _ensure_registration_file()\\n\\n        # Check if registration already exists\\n        existing = load_registration()\\n\\n        # Create new registration (replaces any existing)\\n        registration = {\\n            \\\"email\\\": email,\\n            \\\"registered_at\\\": datetime.now(tz=timezone.utc).isoformat(),\\n        }\\n\\n        # Log if replacing\\n        if existing:\\n            logger.info(f\\\"Replacing registration: {existing.get('email')} -> {email}\\\")\\n\\n        # Save to file\\n        with REGISTRATION_FILE.open(\\\"w\\\") as f:\\n            json.dump(registration, f, indent=2)\\n\\n        logger.info(f\\\"Registration saved: {email}\\\")\\n\\n    except Exception as e:\\n        logger.error(f\\\"Error saving registration: {e}\\\")\\n        raise\\n    else:\\n        return True\\n\\n\\n@router.post(\\\"/\\\", response_model=RegisterResponse, dependencies=[Depends(get_current_active_user)])\\nasync def register_user(request: RegisterRequest):\\n    \\\"\\\"\\\"Register the single user with email.\\n\\n    Note: Only one registration is allowed.\\n    \\\"\\\"\\\"\\n    try:\\n        email = request.email\\n        # Save to local file (replace existing) not dealing with 201 status for simplicity.\\n        if await to_thread(save_registration, email):\\n            await _send_email_telemetry(email=email)\\n            return RegisterResponse(email=email)\\n\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=f\\\"Registration failed: {e!s}\\\") from e\\n\\n\\nasync def _send_email_telemetry(email: str) -> None:\\n    \\\"\\\"\\\"Send the telemetry event for the registered email address.\\\"\\\"\\\"\\n    payload: EmailPayload | None = None\\n\\n    try:\\n        payload = EmailPayload(email=email)\\n    except ValueError as err:\\n        logger.error(f\\\"Email is not a valid email address: {email}: {err}.\\\")\\n        return\\n\\n    logger.debug(f\\\"Sending email telemetry event: {email}\\\")\\n\\n    telemetry_service = get_telemetry_service()\\n\\n    try:\\n        await telemetry_service.log_package_email(payload=payload)\\n    except Exception as err:  # noqa: BLE001\\n        logger.error(f\\\"Failed to send email telemetry event: {payload.email}: {err}\\\")\\n        return\\n\\n    logger.debug(f\\\"Successfully sent email telemetry event: {payload.email}\\\")\\n\\n\\n@router.get(\\\"/\\\", dependencies=[Depends(get_current_active_user)])\\nasync def get_registration():\\n    \\\"\\\"\\\"Get the registered user (if any).\\\"\\\"\\\"\\n    try:\\n        registration = await to_thread(load_registration)\\n        if registration:\\n            return registration\\n\\n        return {\\\"message\\\": \\\"No user registered\\\"}  # noqa: TRY300\\n\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=f\\\"Failed to load registration: {e!s}\\\") from e\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v2/schemas.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c5a8cef344006b7c3e9ff275192f55dc67022969a1d0720aa3945ca862c4b0a5\",\"content\":\"\\\"\\\"\\\"Pydantic schemas for v2 API endpoints.\\\"\\\"\\\"\\n\\n# SECURITY: the MCP stdio command/args/env security policy lives in lfx\\n# (lfx.base.mcp.security). Both this REST-layer model and the flow-execution-time enforcement\\n# in lfx.base.mcp.util call the SAME validate_mcp_stdio_config, so the allowlist/metacharacter/\\n# env/docker checks are byte-for-byte identical and can never drift. The allowlist/blocklist\\n# constants are re-exported here for backwards compatibility with code that imported them from\\n# this module before they were moved to lfx.\\nfrom lfx.base.mcp.security import (  # noqa: F401 - re-exported for backwards compatibility\\n    ALLOWED_MCP_COMMANDS,\\n    DANGEROUS_ENV_VARS,\\n    DANGEROUS_KEYWORDS,\\n    DANGEROUS_SHELL_CHARS,\\n    DOCKER_DANGEROUS_ARG_PREFIXES,\\n    DOCKER_DANGEROUS_ARGS,\\n    SHELL_EXEC_FLAGS,\\n    SHELL_WRAPPERS,\\n    validate_mcp_stdio_config,\\n)\\nfrom pydantic import BaseModel, ConfigDict, model_validator\\n\\n\\nclass MCPServerConfig(BaseModel):\\n    \\\"\\\"\\\"Pydantic model for MCP server configuration.\\\"\\\"\\\"\\n\\n    command: str | None = None\\n    args: list[str] | None = None\\n    env: dict[str, str] | None = None\\n    headers: dict[str, str] | None = None\\n    url: str | None = None\\n\\n    model_config = ConfigDict(extra=\\\"allow\\\")\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _validate_stdio_security(self) -> \\\"MCPServerConfig\\\":\\n        \\\"\\\"\\\"Enforce the MCP stdio command/args/env security policy.\\n\\n        Prevents command injection / arbitrary code execution via the MCP stdio interface:\\n        command allowlist (cmd/sh/bash may only WRAP another allowed command), shell-metacharacter\\n        and dangerous-keyword rejection in args, an environment-variable blocklist\\n        (LD_PRELOAD/NODE_OPTIONS/PATH/...), and docker isolation-breaking args. A command that\\n        embeds its own arguments (e.g. ``bash -c '<payload>'``) is tokenized before the checks so\\n        the embedded tokens cannot bypass them.\\n\\n        Delegates to ``lfx.base.mcp.security.validate_mcp_stdio_config`` (the single source of\\n        truth). It raises ``MCPStdioSecurityError`` (a ``ValueError``), which pydantic surfaces\\n        as a ``ValidationError``.\\n        \\\"\\\"\\\"\\n        validate_mcp_stdio_config(self.command, self.args, self.env)\\n        return self\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v2/workflow.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ef0da66cf55da87a39db11693ede047ca6e1d123eaffaea552e7cd62db557fb5\",\"content\":\"\\\"\\\"\\\"V2 Workflow execution endpoints.\\n\\nThis module implements the V2 Workflow API route handlers for executing flows\\nwith enhanced error handling, timeout protection, and structured responses.\\nThe execution machinery itself lives in sibling modules:\\n\\n    - ``workflow_validation``: request/permission guards.\\n    - ``workflow_execution``: sync + streaming run-driving.\\n    - ``services/background_execution``: durable, re-attachable background runs.\\n\\nEndpoints:\\n    POST /workflows: Execute a workflow (sync, stream, or background modes)\\n    GET /workflows: Get workflow job status by job_id\\n    POST /workflows/stop: Stop a running workflow execution\\n    GET /workflows/pending: List suspended HITL jobs for a flow\\n    POST /workflows/{job_id}/resume: Resume a suspended (HITL) workflow\\n    GET /workflows/{job_id}/events: Re-attach to a background run's event stream\\n\\nFeatures:\\n    - Comprehensive error handling with structured error responses\\n    - Timeout protection for long-running executions\\n    - Support for multiple execution modes (sync, stream, background)\\n    - Session-cookie or API-key authentication\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nfrom dataclasses import replace\\nfrom typing import Annotated\\nfrom uuid import UUID, uuid4\\n\\nfrom fastapi import APIRouter, BackgroundTasks, Depends, HTTPException, Query, Request, status\\nfrom fastapi.responses import EventSourceResponse, StreamingResponse\\nfrom lfx.exceptions.tweaks import TweakRefusedError\\nfrom lfx.log.logger import logger\\nfrom lfx.memory.flow_context import derive_message_owner_uuid\\nfrom lfx.schema.workflow import (\\n    WORKFLOW_STATUS_RESPONSES,\\n    JobId,\\n    JobStatus,\\n    WorkflowExecutionResponse,\\n    WorkflowJobResponse,\\n    WorkflowResumeRequest,\\n    WorkflowResumeResponse,\\n    WorkflowRunRequest,\\n    WorkflowStopRequest,\\n    WorkflowStopResponse,\\n)\\nfrom lfx.services.deps import injectable_session_scope_readonly\\nfrom lfx.workflow.actions import WorkflowAction\\nfrom lfx.workflow.adapters import (\\n    StreamAdapterContext,\\n    UnknownStreamProtocolError,\\n    get_stream_adapter,\\n)\\nfrom lfx.workflow.converters import (\\n    ParsedWorkflowRun,\\n    parse_workflow_run_request,\\n    workflow_response_from_output_events,\\n)\\nfrom lfx.workflow.end_user_identity import resolve_serving_end_user_id, serving_end_user_enabled\\nfrom pydantic_core import ValidationError as PydanticValidationError\\nfrom sqlalchemy.exc import OperationalError\\n\\nfrom langflow.api.utils.execution_errors import caller_owns_flow\\nfrom langflow.api.v2.workflow_execution import (\\n    _execute_streaming_workflow,\\n    _resolve_execution_timeout,\\n    _stream_event_frames,\\n    execute_sync_workflow_with_timeout,\\n)\\nfrom langflow.api.v2.workflow_reconstruction import reconstruct_workflow_response_from_job_id\\nfrom langflow.api.v2.workflow_validation import (\\n    _apply_flow_data_override_policy,\\n    _flow_not_found_privacy_exception,\\n    _reject_sync_only_fields,\\n    _reject_unsupported_sync_fields,\\n    _validate_flow_data_for_execution,\\n)\\nfrom langflow.exceptions.api import (\\n    WorkflowQueueFullError,\\n    WorkflowResourceError,\\n    WorkflowServiceUnavailableError,\\n    WorkflowTimeoutError,\\n    WorkflowValidationError,\\n)\\nfrom langflow.helpers.flow import get_flow_by_id_or_endpoint_name\\nfrom langflow.services.auth.utils import get_current_user_for_workflow\\nfrom langflow.services.authorization import FlowAction, ensure_flow_permission\\nfrom langflow.services.authorization.fetch import deny_to_404_unless_readable\\nfrom langflow.services.authorization.flow_data_override import resolve_flow_data_override\\nfrom langflow.services.background_execution.service import (\\n    InvalidRequestOverridesError,\\n    RequestOverridesUnavailableError,\\n)\\nfrom langflow.services.database.models.flow.model import FlowRead\\nfrom langflow.services.database.models.jobs.model import Job, JobType\\nfrom langflow.services.database.models.user.model import UserRead\\nfrom langflow.services.deps import (\\n    get_background_execution_service,\\n    get_job_service,\\n    get_memory_base_service,\\n    get_task_service,\\n)\\nfrom langflow.services.jobs.exceptions import DuplicateJobError\\nfrom langflow.services.warm_registry.resolver import resolve_warm_flow_for_execution\\n\\n# Finished states a late /stop must not rewrite (CANCELLED is handled separately\\n# with its own idempotent early return).\\n_TERMINAL_JOB_STATUSES = frozenset({JobStatus.COMPLETED, JobStatus.FAILED, JobStatus.TIMED_OUT})\\n\\n\\ndef _workflow_job_mode(job: Job) -> str | None:\\n    \\\"\\\"\\\"Return the persisted execution mode for a workflow job, if recognized.\\n\\n    Durable background submissions store their sanitized request under\\n    ``job_metadata[\\\"request\\\"]``. Sync and live-stream rows do not have that\\n    durable execution handle, so missing or malformed metadata intentionally\\n    resolves to ``None`` and is treated as non-cancellable.\\n    \\\"\\\"\\\"\\n    metadata = job.job_metadata if isinstance(job.job_metadata, dict) else {}\\n    request = metadata.get(\\\"request\\\")\\n    if not isinstance(request, dict):\\n        return None\\n    mode = request.get(\\\"mode\\\")\\n    return mode if mode in {\\\"background\\\", \\\"stream\\\", \\\"sync\\\"} else None\\n\\n\\n# The langflow durable background routes (GET status, POST /stop, GET /pending,\\n# POST /{job_id}/resume, GET /{job_id}/events). The POST run path is contributed\\n# by the shared lfx router (``lfx.workflow.router.create_workflow_router``)\\n# bound to ``LangflowWorkflowHost``; only these durable, behaviorally-rich\\n# routes stay langflow-owned. Both are mounted on the same ``/workflows``\\n# prefix in ``langflow.api.router``.\\nrouter = APIRouter(prefix=\\\"/workflows\\\", tags=[\\\"Workflow\\\"])\\n\\nFLOW_EXECUTE_DENIED_DETAIL = \\\"You don't have permission to execute this flow.\\\"\\n\\n\\ndef _flow_not_found_http_exception(flow_id: str) -> HTTPException:\\n    \\\"\\\"\\\"The structured 404 returned when a flow does not exist.\\\"\\\"\\\"\\n    return HTTPException(\\n        status_code=status.HTTP_404_NOT_FOUND,\\n        detail={\\n            \\\"error\\\": \\\"Flow not found\\\",\\n            \\\"code\\\": \\\"FLOW_NOT_FOUND\\\",\\n            \\\"message\\\": f\\\"Flow '{flow_id}' does not exist. Verify the flow_id and try again.\\\",\\n            \\\"flow_id\\\": flow_id,\\n        },\\n    )\\n\\n\\nasync def resolve_flow_for_execution(flow_id: str, current_user: UserRead):\\n    \\\"\\\"\\\"Share-aware fetch with the langflow error-to-HTTP mapping.\\n\\n    The lookup widens to shared flows when an authorization plugin is\\n    registered; ``authorize_flow_action`` enforces the action separately so an\\n    API key with cross-user fetch enabled cannot bypass policy. A missing flow\\n    becomes 404 FLOW_NOT_FOUND, a DB failure 503 DATABASE_ERROR, and anything\\n    unexpected a sanitized 500.\\n    \\\"\\\"\\\"\\n    try:\\n        warm_flow = await resolve_warm_flow_for_execution(\\n            str(flow_id),\\n            current_user.id,\\n            widen_for_shares=True,\\n        )\\n        if warm_flow is not None:\\n            return warm_flow\\n        return await get_flow_by_id_or_endpoint_name(\\n            str(flow_id),\\n            current_user.id,\\n            widen_for_shares=True,\\n        )\\n    except HTTPException as e:\\n        if e.status_code == status.HTTP_404_NOT_FOUND:\\n            raise _flow_not_found_http_exception(str(flow_id)) from e\\n        raise\\n    except OperationalError as e:\\n        await logger.aexception(\\\"Database error fetching flow for workflow execution\\\")\\n        raise HTTPException(\\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n            detail={\\n                \\\"error\\\": \\\"Service unavailable, Please try again.\\\",\\n                \\\"code\\\": \\\"DATABASE_ERROR\\\",\\n                \\\"message\\\": \\\"Failed to fetch flow. Please try again.\\\",\\n                \\\"flow_id\\\": str(flow_id),\\n            },\\n        ) from e\\n    except Exception as err:\\n        await logger.aexception(\\\"Unexpected error during workflow execution\\\")\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail={\\n                \\\"error\\\": \\\"Internal server error\\\",\\n                \\\"code\\\": \\\"INTERNAL_SERVER_ERROR\\\",\\n                \\\"message\\\": \\\"An unexpected error occurred.\\\",\\n                \\\"flow_id\\\": str(flow_id),\\n            },\\n        ) from err\\n\\n\\nasync def authorize_flow_action(\\n    current_user: UserRead, flow, action: WorkflowAction, *, requested_id: str | None = None\\n) -> None:\\n    \\\"\\\"\\\"Map a ``WorkflowAction`` to a ``FlowAction`` and enforce it.\\n\\n    A denied share-aware fetch is reframed to 404 so flow existence is not\\n    leaked through a raw 403. ``requested_id`` is the identifier the caller sent\\n    (an endpoint name or a UUID); the reframed body echoes it instead of the\\n    resolved internal UUID. Falls back to ``flow.id`` when not provided.\\n\\n    The 404 reframe is skipped when the caller can read the flow: they already\\n    know it exists, and \\\"verify the flow_id and try again\\\" sends them to debug\\n    an identifier that is correct. Those callers get an execute denial instead.\\n    \\\"\\\"\\\"\\n    flow_action = FlowAction.READ if action == WorkflowAction.READ else FlowAction.EXECUTE\\n    # Echo the identifier the caller requested (which may be an endpoint name),\\n    # not the resolved internal UUID, so a denial does not leak the canonical id.\\n    echo_id = requested_id if requested_id is not None else str(flow.id)\\n    try:\\n        await ensure_flow_permission(\\n            current_user,\\n            flow_action,\\n            flow_id=flow.id,\\n            flow_user_id=flow.user_id,\\n            workspace_id=getattr(flow, \\\"workspace_id\\\", None),\\n            folder_id=getattr(flow, \\\"folder_id\\\", None),\\n        )\\n    except HTTPException as exc:\\n        if flow_action == FlowAction.EXECUTE:\\n            resolved = await deny_to_404_unless_readable(\\n                exc,\\n                lambda: ensure_flow_permission(\\n                    current_user,\\n                    FlowAction.READ,\\n                    flow_id=flow.id,\\n                    flow_user_id=flow.user_id,\\n                    workspace_id=getattr(flow, \\\"workspace_id\\\", None),\\n                    folder_id=getattr(flow, \\\"folder_id\\\", None),\\n                ),\\n                denied_detail=FLOW_EXECUTE_DENIED_DETAIL,\\n            )\\n            if resolved.status_code == status.HTTP_403_FORBIDDEN:\\n                raise HTTPException(\\n                    status_code=status.HTTP_403_FORBIDDEN,\\n                    detail={\\n                        \\\"error\\\": \\\"Permission denied\\\",\\n                        \\\"code\\\": \\\"FLOW_EXECUTE_FORBIDDEN\\\",\\n                        \\\"message\\\": FLOW_EXECUTE_DENIED_DETAIL,\\n                        \\\"flow_id\\\": echo_id,\\n                    },\\n                ) from exc\\n        privacy = _flow_not_found_privacy_exception(exc, echo_id)\\n        # Preserve the legacy contract: any 404 on this path surfaces as the\\n        # structured FLOW_NOT_FOUND body, not the privacy-reframe's string detail.\\n        if privacy.status_code == status.HTTP_404_NOT_FOUND:\\n            raise _flow_not_found_http_exception(echo_id) from exc\\n        raise privacy from exc\\n    # ensure_flow_permission's audit write + owner-override lookup touch the DB, so a\\n    # transient lock raises a non-HTTPException. Map it the same way the fetch path does\\n    # (503 DATABASE_ERROR, retryable) instead of leaking a bare 500.\\n    except OperationalError as e:\\n        await logger.aexception(\\\"Database error enforcing flow permission for workflow execution\\\")\\n        raise HTTPException(\\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n            detail={\\n                \\\"error\\\": \\\"Service unavailable, Please try again.\\\",\\n                \\\"code\\\": \\\"DATABASE_ERROR\\\",\\n                \\\"message\\\": \\\"Failed to enforce flow permission. Please try again.\\\",\\n                \\\"flow_id\\\": echo_id,\\n            },\\n        ) from e\\n    except Exception as err:\\n        await logger.aexception(\\\"Unexpected error during workflow execution\\\")\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail={\\n                \\\"error\\\": \\\"Internal server error\\\",\\n                \\\"code\\\": \\\"INTERNAL_SERVER_ERROR\\\",\\n                \\\"message\\\": \\\"An unexpected error occurred.\\\",\\n                \\\"flow_id\\\": echo_id,\\n            },\\n        ) from err\\n\\n    # Resolve the graph-override verdict here, where we can await the policy\\n    # plugin. The sync gates below run in all three execution modes and read\\n    # the resolved value; without this they fall back to owner-only.\\n    if flow_action == FlowAction.EXECUTE:\\n        await resolve_flow_data_override(current_user, flow)\\n\\n\\ndef _apply_execution_gates(parsed, flow, current_user: UserRead):\\n    \\\"\\\"\\\"Run request gates and return any server-sanitized execution payload.\\\"\\\"\\\"\\n    expose_error_details = caller_owns_flow(flow, current_user)\\n    _reject_unsupported_sync_fields(parsed)\\n    _reject_sync_only_fields(parsed)\\n    # An execute-only caller keeps running: their override is dropped and the\\n    # stored graph runs, instead of the flow reading as non-existent (LE-1905).\\n    parsed = _apply_flow_data_override_policy(parsed, flow, current_user)\\n    return _validate_flow_data_for_execution(\\n        parsed,\\n        flow,\\n        current_user,\\n        expose_error_details=expose_error_details,\\n    )\\n\\n\\nasync def run_sync_with_mapping(\\n    parsed,\\n    flow,\\n    current_user: UserRead,\\n    *,\\n    http_request: Request,\\n    background_tasks: BackgroundTasks,\\n) -> WorkflowExecutionResponse:\\n    \\\"\\\"\\\"Inline sync run with the langflow timeout/validation error mapping.\\\"\\\"\\\"\\n    parsed = _apply_execution_gates(parsed, flow, current_user)\\n    job_id = uuid4()\\n    try:\\n        return await execute_sync_workflow_with_timeout(\\n            parsed=parsed,\\n            flow=flow,\\n            job_id=job_id,\\n            current_user=current_user,\\n            background_tasks=background_tasks,\\n            http_request=http_request,\\n        )\\n    except WorkflowTimeoutError:\\n        timeout_seconds = _resolve_execution_timeout()\\n        raise HTTPException(\\n            status_code=status.HTTP_408_REQUEST_TIMEOUT,\\n            detail={\\n                \\\"error\\\": \\\"Execution timeout\\\",\\n                \\\"code\\\": \\\"EXECUTION_TIMEOUT\\\",\\n                \\\"message\\\": f\\\"Workflow execution exceeded {timeout_seconds} seconds\\\",\\n                \\\"job_id\\\": str(job_id),\\n                \\\"flow_id\\\": str(parsed.flow_id),\\n                \\\"timeout_seconds\\\": timeout_seconds,\\n            },\\n        ) from None\\n    except TweakRefusedError:\\n        raise\\n    except (PydanticValidationError, WorkflowValidationError) as e:\\n        raise HTTPException(\\n            status_code=status.HTTP_400_BAD_REQUEST,\\n            detail={\\n                \\\"error\\\": \\\"Workflow validation error\\\",\\n                \\\"code\\\": \\\"INVALID_FLOW_DATA\\\",\\n                \\\"message\\\": str(e),\\n                \\\"flow_id\\\": parsed.flow_id,\\n            },\\n        ) from e\\n    except HTTPException:\\n        raise\\n    except OperationalError as e:\\n        await logger.aexception(\\\"Database error during workflow execution\\\")\\n        raise HTTPException(\\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n            detail={\\n                \\\"error\\\": \\\"Service unavailable, Please try again.\\\",\\n                \\\"code\\\": \\\"DATABASE_ERROR\\\",\\n                \\\"message\\\": \\\"Failed to fetch flow. Please try again.\\\",\\n                \\\"flow_id\\\": parsed.flow_id,\\n            },\\n        ) from e\\n    except Exception as err:\\n        await logger.aexception(\\\"Unexpected error during workflow execution\\\")\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail={\\n                \\\"error\\\": \\\"Internal server error\\\",\\n                \\\"code\\\": \\\"INTERNAL_SERVER_ERROR\\\",\\n                \\\"message\\\": \\\"An unexpected error occurred.\\\",\\n                \\\"flow_id\\\": parsed.flow_id,\\n            },\\n        ) from err\\n\\n\\ndef build_stream_response(\\n    parsed,\\n    flow,\\n    current_user: UserRead,\\n    *,\\n    stream_protocol: str,\\n    background_tasks: BackgroundTasks,\\n) -> StreamingResponse:\\n    \\\"\\\"\\\"Live-stream a run via the v1 build-vertex loop (agui side-channel + persistence).\\n\\n    The langflow stream path is NOT lfx's leaner ``stream_workflow_frames``: it\\n    drives ``generate_flow_events`` so per-vertex events, the agui ``CUSTOM``\\n    side-channel, and vertex-build persistence all survive. Validation gates run\\n    before the response is constructed so a bad request fails before streaming.\\n    \\\"\\\"\\\"\\n    parsed = _apply_execution_gates(parsed, flow, current_user)\\n    run_id = str(uuid4())\\n    adapter = get_stream_adapter(\\n        stream_protocol,\\n        StreamAdapterContext(\\n            run_id=run_id,\\n            thread_id=parsed.session_id or str(flow.id),\\n        ),\\n    )\\n    return _execute_streaming_workflow(\\n        adapter=adapter,\\n        run_id=run_id,\\n        parsed=parsed,\\n        flow=flow,\\n        current_user=current_user,\\n        background_tasks=background_tasks,\\n    )\\n\\n\\nasync def submit_background_with_mapping(\\n    parsed,\\n    flow,\\n    current_user: UserRead,\\n    *,\\n    stream_protocol: str,\\n) -> WorkflowJobResponse:\\n    \\\"\\\"\\\"Queue a durable background run with the langflow service error mapping.\\\"\\\"\\\"\\n    parsed = _apply_execution_gates(parsed, flow, current_user)\\n    try:\\n        return await execute_workflow_background(\\n            parsed=parsed,\\n            flow=flow,\\n            job_id=uuid4(),\\n            current_user=current_user,\\n            http_request=None,\\n            stream_protocol=stream_protocol,\\n            idempotency_key=getattr(parsed, \\\"idempotency_key\\\", None),\\n        )\\n    except InvalidRequestOverridesError as err:\\n        raise HTTPException(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            detail={\\n                \\\"error\\\": \\\"Invalid request overrides\\\",\\n                \\\"code\\\": \\\"INVALID_REQUEST_OVERRIDES\\\",\\n                \\\"message\\\": \\\"globals and tweaks must contain JSON-compatible values.\\\",\\n                \\\"field\\\": err.field,\\n                \\\"flow_id\\\": parsed.flow_id,\\n            },\\n        ) from err\\n    except RequestOverridesUnavailableError as err:\\n        raise HTTPException(\\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n            detail={\\n                \\\"error\\\": \\\"Service unavailable\\\",\\n                \\\"code\\\": \\\"REQUEST_OVERRIDES_UNAVAILABLE\\\",\\n                \\\"message\\\": \\\"Background request overrides are temporarily unavailable. Please try again.\\\",\\n                \\\"flow_id\\\": parsed.flow_id,\\n            },\\n        ) from err\\n    except WorkflowServiceUnavailableError as err:\\n        raise HTTPException(\\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n            detail={\\n                \\\"error\\\": \\\"Service unavailable\\\",\\n                \\\"code\\\": \\\"QUEUE_SERVICE_UNAVAILABLE\\\",\\n                \\\"message\\\": str(err),\\n                \\\"flow_id\\\": parsed.flow_id,\\n            },\\n        ) from err\\n    except (WorkflowResourceError, WorkflowQueueFullError, MemoryError) as err:\\n        raise HTTPException(\\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n            detail={\\n                \\\"error\\\": \\\"Service busy\\\",\\n                \\\"code\\\": \\\"SERVICE_BUSY\\\",\\n                \\\"message\\\": \\\"The service is currently unable to handle the request due to resource limits.\\\",\\n                \\\"flow_id\\\": parsed.flow_id,\\n            },\\n        ) from err\\n    except HTTPException:\\n        raise\\n    except OperationalError as e:\\n        await logger.aexception(\\\"Database error during workflow execution\\\")\\n        raise HTTPException(\\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n            detail={\\n                \\\"error\\\": \\\"Service unavailable, Please try again.\\\",\\n                \\\"code\\\": \\\"DATABASE_ERROR\\\",\\n                \\\"message\\\": \\\"Failed to fetch flow. Please try again.\\\",\\n                \\\"flow_id\\\": parsed.flow_id,\\n            },\\n        ) from e\\n    except Exception as err:\\n        await logger.aexception(\\\"Unexpected error during workflow execution\\\")\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail={\\n                \\\"error\\\": \\\"Internal server error\\\",\\n                \\\"code\\\": \\\"INTERNAL_SERVER_ERROR\\\",\\n                \\\"message\\\": \\\"An unexpected error occurred.\\\",\\n                \\\"flow_id\\\": parsed.flow_id,\\n            },\\n        ) from err\\n\\n\\ndef _unknown_protocol_http_exception(exc: UnknownStreamProtocolError) -> HTTPException:\\n    \\\"\\\"\\\"Build the 422 response for an unknown ``stream_protocol``.\\n\\n    Used by the public workflow router (``workflow_public.py``) so its error body\\n    matches the shared lfx router's: ``available`` lists the registered protocol\\n    names so clients can self-correct.\\n    \\\"\\\"\\\"\\n    return HTTPException(\\n        status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n        detail={\\n            \\\"error\\\": \\\"Unknown stream_protocol\\\",\\n            \\\"code\\\": \\\"UNKNOWN_STREAM_PROTOCOL\\\",\\n            \\\"message\\\": f\\\"Unknown stream_protocol {exc.name!r}.\\\",\\n            \\\"available\\\": exc.available,\\n        },\\n    )\\n\\n\\ndef _end_user_matches(request_end_user_id: str | None, job_metadata: object) -> bool:\\n    \\\"\\\"\\\"The pure serving-plane end-user ownership rule, shared by every jobs endpoint.\\n\\n    Given a request's resolved end-user id and a job's ``job_metadata``, decide whether they name\\n    the same end user (superuser / feature gating is the caller's job). Used by the single-job guard\\n    (``_caller_owns_job_end_user`` for status/stop/resume) AND the enumerating pending list, so the\\n    isolation rule lives in exactly one place:\\n\\n    * ``job_metadata`` is coerced to ``{}`` unless it is a real dict \u2014 a security guard must never\\n      decide from a malformed/legacy value (a JSON string, list, or test mock).\\n    * No request end user (feature off / anonymous): matches ONLY a job that also has none.\\n    * Both present: the derived owner ids must be equal, so a raw-string vs UUID-form gateway id\\n      compares canonically (D6), exactly as message ownership keys it.\\n    \\\"\\\"\\\"\\n    metadata = job_metadata if isinstance(job_metadata, dict) else {}\\n    job_end_user = metadata.get(\\\"end_user_id\\\")\\n    if request_end_user_id is None:\\n        return job_end_user is None\\n    if job_end_user is None:\\n        return False\\n    return derive_message_owner_uuid(request_end_user_id) == derive_message_owner_uuid(job_end_user)\\n\\n\\ndef _caller_owns_job_end_user(job: Job, http_request: Request, current_user: UserRead) -> bool:\\n    \\\"\\\"\\\"Whether the caller may act on ``job`` under serving-plane end-user isolation.\\n\\n    On the serving plane every end user shares the one service account (SID), so SID-level\\n    ownership (already applied by ``get_job_by_job_id(user_id=SID)``) cannot tell two end\\n    users apart. This layers the end-user check on top: the request's trusted end-user id\\n    (the gateway header) must resolve to the same owner the job was created under\\n    (``job_metadata['end_user_id']``). A mismatch means it is another end user's job.\\n\\n    Because ``job.user_id`` stays the SID (so re-enqueue/resume can still fetch the SID-owned\\n    flow \u2014 F8), the end-user identity lives only in ``job_metadata``; this is the sole place\\n    it gates access. Decisions:\\n\\n    * Superuser bypass applies ONLY when the serving feature is off. On the serving plane the\\n      shared service account (SID) is itself a superuser, so an unconditional bypass would let\\n      any end user (all riding that one SID) read/stop/resume any other's run \u2014 defeating the\\n      whole isolation layer for the exact deployment it exists for. When serving is on the\\n      bypass is suppressed and even the SID is scoped to the request's end user.\\n    * Feature off / anonymous request (``resolve_serving_end_user_id`` -> None): there is no\\n      end-user scope to enforce, so a job created without an end user passes and one created\\n      under an end user does not (an anonymous caller must not reach an identified run).\\n    * Identified request: the derived request owner must equal the derived job owner. Both\\n      sides derive through :func:`derive_message_owner_uuid` so the raw-string vs UUID-form\\n      gateway id compares canonically, exactly as message ownership keys it.\\n    \\\"\\\"\\\"\\n    if current_user.is_superuser and not serving_end_user_enabled():\\n        return True\\n    return _end_user_matches(resolve_serving_end_user_id(http_request=http_request), job.job_metadata)\\n\\n\\ndef _parse_persisted_workflow_request(request: dict) -> ParsedWorkflowRun:\\n    \\\"\\\"\\\"Re-parse a persisted background/resume request into a ``ParsedWorkflowRun``.\\n\\n    ``persist_messages`` and ``end_user_id`` are internal serving-plane decisions\\n    (anonymous runs are ephemeral; identified runs carry the end user), not client\\n    wire fields \u2014 ``WorkflowRunRequest`` forbids extras, so they are popped before\\n    constructing the request and re-applied to the parsed run. Without this, the\\n    worker re-parse would reset ``persist_messages`` to the ``True`` default (an\\n    anonymous background/resume run would persist memory it must not) and drop\\n    ``end_user_id`` (an identified run would stamp memory to the SID, not the end\\n    user). Legacy rows that predate the fields fall back to persist=True /\\n    end_user_id=None, matching prior behavior.\\n    \\\"\\\"\\\"\\n    internal = {\\\"persist_messages\\\", \\\"end_user_id\\\", \\\"component_substitution_warning\\\"}\\n    persist_messages = request.get(\\\"persist_messages\\\", True)\\n    end_user_id = request.get(\\\"end_user_id\\\")\\n    request_fields = {k: v for k, v in request.items() if k not in internal}\\n    return replace(\\n        parse_workflow_run_request(WorkflowRunRequest(**request_fields)),\\n        persist_messages=persist_messages,\\n        end_user_id=end_user_id,\\n        component_substitution_warning=request.get(\\\"component_substitution_warning\\\"),\\n    )\\n\\n\\ndef _default_frame_source_factory(*, request, flow_id, user, adapter, **_extra):\\n    \\\"\\\"\\\"Bind the v1 build loop (``_stream_event_frames``) as the runner's source.\\n\\n    Returns a zero-extra-kwargs async-generator callable so the runner can call\\n    it with ``**source_kwargs``. The flow row is re-fetched lazily inside the\\n    closure so ``submit()`` stays cheap and the build happens on the worker.\\n\\n    The memory-base ``on_flow_output`` hook is fired on a clean run (no terminal\\n    error event) so background mode keeps the auto-capture wiring sync mode and\\n    the v1 build pipeline have; without it every background run would silently\\n    miss it.\\n    \\\"\\\"\\\"\\n    parsed = _parse_persisted_workflow_request(request)\\n    terminal_error_type = adapter.terminal_error_type\\n\\n    async def _source(*, job_id=None, resume=None, **_kwargs):\\n        flow = await resolve_flow_for_execution(str(flow_id), user)\\n        fresh_background_tasks = BackgroundTasks()\\n        errored = False\\n        try:\\n            async for frame, event_type in _stream_event_frames(\\n                adapter=adapter,\\n                flow_id=flow.id,\\n                flow_name=flow.name,\\n                background_tasks=fresh_background_tasks,\\n                parsed=parsed,\\n                current_user=user,\\n                provider_policy_flow=flow,\\n                source_flow_owner_id=flow.user_id,\\n                expose_error_details=caller_owns_flow(flow, user),\\n                job_id=job_id,\\n                resume=resume,\\n                # Key the persisted vertex builds by the durable job_id so a completed run's GET\\n                # status can reconstruct its outputs (and recover the session_id it ran under)\\n                # instead of falling back to the leaner Job.result rebuild.\\n                run_id=str(job_id) if job_id else None,\\n                # The durable runner already owns this run's WORKFLOW job row (keyed by the durable\\n                # job_id) and fires the memory-base hook below with that id, so the build pipeline\\n                # must not mint its own run_id-keyed WORKFLOW row + hook (it would double both).\\n                track_job_status=False,\\n                # This factory is the runner the v2 background route actually reaches, so the label\\n                # belongs here; without it a background run is indistinguishable from a live stream.\\n                protocol=\\\"v2.background\\\",\\n                # Emit the off-wire terminal-output capture the runner records into\\n                # ``Job.result`` \u2014 protocol-neutral, so agui-protocol runs get a\\n                # populated GET-status result too (not just langflow).\\n                emit_output_capture=True,\\n                # No client is waiting on a background run, so the sync HTTP ceiling is the wrong\\n                # budget for it: nesting it inside the runner's asyncio.wait_for capped every\\n                # background job at workflow_execution_timeout and made the documented\\n                # background_job_timeout=None (\\\"no timeout\\\") unreachable. JobRunner owns it.\\n                execution_timeout=None,\\n            ):\\n                if terminal_error_type is not None and event_type == terminal_error_type:\\n                    errored = True\\n                yield frame, event_type\\n        finally:\\n            # ``generate_flow_events`` queues telemetry / tracing teardown on\\n            # this ``BackgroundTasks``; the background path has no response to\\n            # carry them, so drain explicitly. Suppressed so one failing\\n            # callback cannot derail the run.\\n            with contextlib.suppress(Exception):\\n                await fresh_background_tasks()\\n            if not errored and caller_owns_flow(flow, user):\\n                try:\\n                    await get_task_service().fire_and_forget_task(\\n                        get_memory_base_service().on_flow_output,\\n                        flow_id=flow.id,\\n                        session_id=parsed.session_id or str(flow.id),\\n                        job_id=job_id,\\n                    )\\n                except (RuntimeError, ValueError, OSError):\\n                    await logger.awarning(\\\"Memory base hook scheduling failed for flow %s\\\", flow.id, exc_info=True)\\n\\n    return _source\\n\\n\\nasync def execute_workflow_background(\\n    parsed: ParsedWorkflowRun,\\n    flow: FlowRead,\\n    job_id: JobId,  # noqa: ARG001\\n    current_user: UserRead,\\n    http_request: Request,  # noqa: ARG001\\n    stream_protocol: str,\\n    idempotency_key: str | None = None,\\n) -> WorkflowJobResponse:\\n    \\\"\\\"\\\"Queue a background run through the BackgroundExecutionService facade.\\n\\n    The facade owns job-row creation, durable event persistence, the live bus,\\n    and terminal-state finalization. We pass the original request fields so the\\n    runner re-parses them on the worker (the build happens off the request\\n    path) and replays durable milestones from ``job_events`` on re-attach.\\n\\n    An optional ``idempotency_key`` dedupes submits: a retried POST with the\\n    same key returns the existing job_id rather than queuing duplicate work.\\n    \\\"\\\"\\\"\\n    try:\\n        service = get_background_execution_service()\\n        if service._frame_source_factory is None:  # noqa: SLF001\\n            service._frame_source_factory = _default_frame_source_factory  # noqa: SLF001\\n        request_dict = {\\n            \\\"flow_id\\\": str(flow.id),\\n            \\\"mode\\\": \\\"background\\\",\\n            \\\"stream_protocol\\\": stream_protocol,\\n            \\\"input_value\\\": parsed.input_value,\\n            \\\"session_id\\\": parsed.session_id,\\n            \\\"tweaks\\\": parsed.tweaks,\\n            \\\"globals\\\": parsed.globals,\\n            \\\"output_ids\\\": parsed.output_ids,\\n            \\\"data\\\": parsed.data,\\n            \\\"files\\\": parsed.files,\\n            \\\"start_component_id\\\": parsed.start_component_id,\\n            \\\"stop_component_id\\\": parsed.stop_component_id,\\n            \\\"idempotency_key\\\": idempotency_key,\\n            # Serving-plane ephemeral decision must survive the worker re-parse so an\\n            # anonymous background/resume run does not persist memory (see the pop in\\n            # _default_frame_source_factory).\\n            \\\"persist_messages\\\": parsed.persist_messages,\\n            # The end-user identity is likewise an internal decision, not a wire field:\\n            # it must survive the round-trip so an identified background/resume run\\n            # stamps memory to the end user on the worker, not the SID.\\n            \\\"end_user_id\\\": parsed.end_user_id,\\n            # Sanitized code no longer reveals the substitution when the worker rebuilds it.\\n            \\\"component_substitution_warning\\\": parsed.component_substitution_warning,\\n        }\\n        job_id_new = await service.submit(flow_id=flow.id, request=request_dict, user=current_user)\\n        return WorkflowJobResponse(job_id=str(job_id_new), flow_id=parsed.flow_id, status=JobStatus.QUEUED)\\n\\n    except (WorkflowResourceError, WorkflowServiceUnavailableError, WorkflowQueueFullError):\\n        raise\\n    except MemoryError as exc:\\n        raise WorkflowResourceError from exc\\n    except DuplicateJobError as exc:\\n        # Defense-in-depth for the residual create/lookup race: a still-active\\n        # job already exists for this user's idempotency_key. Map to a 409 with a\\n        # generic body so the key is not echoed back (no existence leak) instead\\n        # of bubbling to the outer 500 handler.\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail={\\n                \\\"error\\\": \\\"Duplicate request\\\",\\n                \\\"code\\\": \\\"DUPLICATE_REQUEST\\\",\\n                \\\"message\\\": \\\"A job with this idempotency_key is already in progress.\\\",\\n                \\\"flow_id\\\": parsed.flow_id,\\n            },\\n        ) from exc\\n\\n\\n@router.get(\\n    \\\"\\\",\\n    response_model=None,\\n    response_model_exclude_none=True,\\n    responses=WORKFLOW_STATUS_RESPONSES,\\n    summary=\\\"Get Workflow Status\\\",\\n    description=\\\"Get status of workflow job by job ID\\\",\\n)\\nasync def get_workflow_status(\\n    http_request: Request,\\n    current_user: Annotated[UserRead, Depends(get_current_user_for_workflow)],\\n    job_id: Annotated[JobId | None, Query(description=\\\"Job ID to query\\\")] = None,\\n    session: Annotated[object, Depends(injectable_session_scope_readonly)] = None,\\n) -> WorkflowExecutionResponse | WorkflowJobResponse:\\n    \\\"\\\"\\\"Get workflow job status and results.\\n\\n    Args:\\n        http_request: The FastAPI request, for serving-plane end-user isolation.\\n        current_user: Authenticated user (session cookie or API key)\\n        job_id: Optional job ID to query specific job\\n        session: Database session for querying vertex builds\\n\\n    Returns:\\n        WorkflowExecutionResponse or reconstructed results\\n\\n    Raises:\\n        HTTPException:\\n            - 400: Job ID not provided\\n            - 403: Developer API disabled or unauthorized\\n            - 404: Job not found\\n            - 408: Execution timeout\\n            - 500: Internal server error or Job failure\\n    \\\"\\\"\\\"\\n    if not job_id:\\n        raise HTTPException(\\n            status_code=status.HTTP_400_BAD_REQUEST,\\n            detail={\\n                \\\"error\\\": \\\"Missing required parameter\\\",\\n                \\\"code\\\": \\\"MISSING_PARAMETER\\\",\\n                \\\"message\\\": \\\"Job ID must be provided\\\",\\n            },\\n        )\\n\\n    job_service = get_job_service()\\n    try:\\n        job = await job_service.get_job_by_job_id(job_id=job_id, user_id=current_user.id)\\n    except Exception as exc:\\n        await logger.aexception(\\\"Database error retrieving workflow job %s\\\", job_id)\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail={\\n                \\\"error\\\": \\\"Internal server error\\\",\\n                \\\"code\\\": \\\"INTERNAL_SERVER_ERROR\\\",\\n                \\\"message\\\": \\\"Failed to retrieve job. Please try again.\\\",\\n            },\\n        ) from exc\\n\\n    if not job:\\n        raise HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail={\\n                \\\"error\\\": \\\"Workflow job not found\\\",\\n                \\\"code\\\": \\\"JOB_NOT_FOUND\\\",\\n                \\\"message\\\": f\\\"Workflow job {job_id} not found\\\",\\n                \\\"job_id\\\": str(job_id),\\n            },\\n        )\\n\\n    # Verify this is a workflow job\\n    if job.type != JobType.WORKFLOW:\\n        raise HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail={\\n                \\\"error\\\": \\\"Workflow job not found\\\",\\n                \\\"code\\\": \\\"JOB_NOT_FOUND\\\",\\n                \\\"message\\\": f\\\"Job {job_id} is not a workflow job (type: {job.type})\\\",\\n                \\\"job_id\\\": str(job_id),\\n            },\\n        )\\n\\n    # Serving-plane end-user isolation: a different end user (sharing the SID) must not read\\n    # this run. 404 (not 403) so the job's existence is not leaked. See F8.\\n    if not _caller_owns_job_end_user(job, http_request, current_user):\\n        raise HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail={\\n                \\\"error\\\": \\\"Workflow job not found\\\",\\n                \\\"code\\\": \\\"JOB_NOT_FOUND\\\",\\n                \\\"message\\\": f\\\"Workflow job {job_id} not found\\\",\\n                \\\"job_id\\\": str(job_id),\\n            },\\n        )\\n\\n    # Store context for exception handling scope\\n    flow_id_str = str(job.flow_id)\\n    job_id_str = str(job_id)\\n    try:\\n        # If job is completed, reconstruct full workflow response from vertex_builds\\n        if job.status == JobStatus.COMPLETED:\\n            # Share-aware fetch + RBAC: enforce flow:read so an API key with\\n            # cross-user fetch cannot read another user's job output.\\n            flow = await get_flow_by_id_or_endpoint_name(\\n                flow_id_str,\\n                current_user.id,\\n                widen_for_shares=True,\\n            )\\n            await ensure_flow_permission(\\n                current_user,\\n                FlowAction.READ,\\n                flow_id=flow.id,\\n                flow_user_id=flow.user_id,\\n                workspace_id=getattr(flow, \\\"workspace_id\\\", None),\\n                folder_id=getattr(flow, \\\"folder_id\\\", None),\\n            )\\n\\n            # The session the run executed under, resolved exactly as the runner's\\n            # frame source did (``parsed.session_id or str(flow.id)``): the submit\\n            # request is persisted on ``job_metadata[\\\"request\\\"]``, so a completed\\n            # background GET echoes the same chat/memory thread sync returns. The\\n            # terminal output's ``content`` is a rendered string, so it can't be\\n            # searched structurally \u2014 the persisted request is the source of truth.\\n            persisted_request = (job.job_metadata or {}).get(\\\"request\\\") or {}\\n            effective_session_id = persisted_request.get(\\\"session_id\\\") or flow_id_str\\n            warning = (job.job_metadata or {}).get(\\\"component_substitution_warning\\\") or persisted_request.get(\\n                \\\"component_substitution_warning\\\"\\n            )\\n            warnings = [warning] if isinstance(warning, str) and warning else []\\n\\n            # Default GET-status path: rebuild from the protocol-neutral terminal\\n            # captures the runner stored in ``Job.result``. This needs no\\n            # ``vertex_build`` rows, so it works with vertex-build storage off\\n            # (headless) and skips graph reconstruction.\\n            result = job.result if isinstance(job.result, dict) else {}\\n            output_events = result.get(\\\"outputs\\\") or []\\n            partial_stored_response: WorkflowExecutionResponse | None = None\\n            if isinstance(output_events, list) and output_events:\\n                try:\\n                    return workflow_response_from_output_events(\\n                        output_events,\\n                        flow_id=flow_id_str,\\n                        job_id=job_id_str,\\n                        session_id=effective_session_id,\\n                        fail_on_rejected=True,\\n                    ).model_copy(update={\\\"warnings\\\": warnings})\\n                except ValueError:\\n                    # Preserve every decodable capture in case the legacy\\n                    # vertex-build fallback is also unavailable.\\n                    partial_stored_response = workflow_response_from_output_events(\\n                        output_events,\\n                        flow_id=flow_id_str,\\n                        job_id=job_id_str,\\n                        session_id=effective_session_id,\\n                    ).model_copy(update={\\\"warnings\\\": warnings})\\n\\n            # Fallback: ``Job.result`` carried no outputs, has an invalid shape,\\n            # contains rejected/version-skewed entries, or predates capture.\\n            # Reconstruct from ``vertex_build`` rows keyed by job_id when present.\\n            try:\\n                reconstructed = await reconstruct_workflow_response_from_job_id(\\n                    session=session,\\n                    flow=flow,\\n                    job_id=job_id_str,\\n                    user_id=str(current_user.id),\\n                    is_superuser=bool(getattr(current_user, \\\"is_superuser\\\", False)),\\n                )\\n            except ValueError:\\n                if partial_stored_response is not None:\\n                    return partial_stored_response\\n                return workflow_response_from_output_events(\\n                    [],\\n                    flow_id=flow_id_str,\\n                    job_id=job_id_str,\\n                    session_id=effective_session_id,\\n                ).model_copy(update={\\\"warnings\\\": warnings})\\n            else:\\n                if reconstructed.session_id is None:\\n                    reconstructed = reconstructed.model_copy(update={\\\"session_id\\\": effective_session_id})\\n                return reconstructed.model_copy(update={\\\"warnings\\\": warnings})\\n\\n        if job.status == JobStatus.FAILED:\\n            # Surface the durable error JSON the runner persisted, additively.\\n            # The error column is nullable (a crash before the runner could write\\n            # one leaves it None); the static detail still applies in that case.\\n            raise HTTPException(\\n                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n                detail={\\n                    \\\"error\\\": \\\"Job failed\\\",\\n                    \\\"code\\\": \\\"JOB_FAILED\\\",\\n                    \\\"message\\\": f\\\"Job {job_id_str} has failed execution.\\\",\\n                    \\\"job_id\\\": job_id_str,\\n                    \\\"error_detail\\\": job.error,\\n                },\\n            )\\n\\n        if job.status == JobStatus.TIMED_OUT:\\n            raise HTTPException(\\n                status_code=status.HTTP_408_REQUEST_TIMEOUT,\\n                detail={\\n                    \\\"error\\\": \\\"Execution timeout\\\",\\n                    \\\"code\\\": \\\"EXECUTION_TIMEOUT\\\",\\n                    \\\"message\\\": \\\"Workflow execution timed out\\\",\\n                    \\\"job_id\\\": job_id_str,\\n                    \\\"flow_id\\\": flow_id_str,\\n                },\\n            )\\n\\n        # Default response for active statuses (QUEUED, IN_PROGRESS, etc.)\\n        return WorkflowJobResponse(\\n            flow_id=flow_id_str,\\n            job_id=job_id_str,\\n            status=job.status,\\n        )\\n\\n    except HTTPException:\\n        raise\\n    except WorkflowTimeoutError as err:\\n        timeout_seconds = _resolve_execution_timeout()\\n        raise HTTPException(\\n            status_code=status.HTTP_408_REQUEST_TIMEOUT,\\n            detail={\\n                \\\"error\\\": \\\"Execution timeout\\\",\\n                \\\"code\\\": \\\"EXECUTION_TIMEOUT\\\",\\n                \\\"message\\\": f\\\"Workflow execution exceeded {timeout_seconds} seconds\\\",\\n                \\\"job_id\\\": job_id_str,\\n                \\\"flow_id\\\": flow_id_str,\\n                \\\"timeout_seconds\\\": timeout_seconds,\\n            },\\n        ) from err\\n    except Exception as exc:\\n        await logger.aexception(\\\"Unexpected error processing workflow job status for %s\\\", job_id_str)\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail={\\n                \\\"error\\\": \\\"Internal server error\\\",\\n                \\\"code\\\": \\\"INTERNAL_SERVER_ERROR\\\",\\n                \\\"message\\\": \\\"Failed to process job status.\\\",\\n            },\\n        ) from exc\\n\\n\\n@router.post(\\n    \\\"/stop\\\",\\n    summary=\\\"Stop Workflow\\\",\\n    description=\\\"Stop a running background workflow execution\\\",\\n)\\nasync def stop_workflow(\\n    request: WorkflowStopRequest,\\n    http_request: Request,\\n    current_user: Annotated[UserRead, Depends(get_current_user_for_workflow)],\\n) -> WorkflowStopResponse:\\n    \\\"\\\"\\\"Stop a running background workflow execution by job_id.\\n\\n    Sync and live-stream runs execute inside their caller's request and cannot be\\n    interrupted by the durable background executor. Those modes are rejected\\n    instead of reporting a cancellation that did not happen.\\n\\n    Args:\\n        request: Stop request containing job_id and optional force flag\\n        http_request: The FastAPI request, for serving-plane end-user isolation.\\n        current_user: Authenticated user (session cookie or API key)\\n\\n    Returns:\\n        WorkflowStopResponse: Confirmation of stop request with final job status\\n\\n    Raises:\\n        HTTPException:\\n            - 403: Developer API disabled or unauthorized\\n            - 404: Job ID not found\\n            - 409: Job is not a cancellable background run\\n            - 500: Internal server error\\n    \\\"\\\"\\\"\\n    job_id = request.job_id\\n    job_service = get_job_service()\\n    task_service = get_task_service()\\n\\n    try:\\n        # 1. Fetch Job\\n        job = await job_service.get_job_by_job_id(job_id, user_id=current_user.id)\\n    except Exception as exc:\\n        await logger.aexception(\\\"Database error retrieving workflow job %s for stop\\\", job_id)\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail={\\n                \\\"error\\\": \\\"Internal server error\\\",\\n                \\\"code\\\": \\\"INTERNAL_SERVER_ERROR\\\",\\n                \\\"message\\\": \\\"Failed to retrieve job status. Please try again.\\\",\\n            },\\n        ) from exc\\n\\n    if not job:\\n        raise HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail={\\n                \\\"error\\\": \\\"Job not found\\\",\\n                \\\"code\\\": \\\"JOB_NOT_FOUND\\\",\\n                \\\"message\\\": f\\\"Job {job_id} not found\\\",\\n                \\\"job_id\\\": str(job_id),\\n            },\\n        )\\n\\n    # Verify this is a workflow job\\n    if job.type != JobType.WORKFLOW:\\n        raise HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail={\\n                \\\"error\\\": \\\"Job not found\\\",\\n                \\\"code\\\": \\\"JOB_NOT_FOUND\\\",\\n                \\\"message\\\": f\\\"Job {job_id} is not a workflow job (type: {job.type})\\\",\\n                \\\"job_id\\\": str(job_id),\\n            },\\n        )\\n\\n    # Serving-plane end-user isolation: a different end user (sharing the SID) must not stop\\n    # this run. 404 (not 403) so the job's existence is not leaked. See F8.\\n    if not _caller_owns_job_end_user(job, http_request, current_user):\\n        raise HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail={\\n                \\\"error\\\": \\\"Job not found\\\",\\n                \\\"code\\\": \\\"JOB_NOT_FOUND\\\",\\n                \\\"message\\\": f\\\"Job {job_id} not found\\\",\\n                \\\"job_id\\\": str(job_id),\\n            },\\n        )\\n\\n    job_mode = _workflow_job_mode(job)\\n    if job_mode != \\\"background\\\":\\n        display_mode = job_mode or \\\"unknown\\\"\\n        await logger.ainfo(\\\"Rejected stop for workflow job %s in non-cancellable mode %s\\\", job_id, display_mode)\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail={\\n                \\\"error\\\": \\\"Job cannot be stopped\\\",\\n                \\\"code\\\": \\\"JOB_NOT_CANCELLABLE\\\",\\n                \\\"message\\\": \\\"Only background workflow jobs can be stopped.\\\",\\n                \\\"job_id\\\": str(job_id),\\n                \\\"mode\\\": display_mode,\\n            },\\n        )\\n\\n    if job.status == JobStatus.CANCELLED:\\n        return WorkflowStopResponse(job_id=str(job_id), message=f\\\"Job {job_id} is already cancelled.\\\")\\n    # A late stop on a job that already finished must not rewrite its terminal\\n    # status: flipping a COMPLETED/FAILED/TIMED_OUT row to CANCELLED would strand\\n    # the result/error blob the run already wrote. Report the existing state.\\n    if job.status in _TERMINAL_JOB_STATUSES:\\n        return WorkflowStopResponse(job_id=str(job_id), message=f\\\"Job {job_id} already finished ({job.status.value}).\\\")\\n\\n    try:\\n        revoked = await task_service.revoke_task(job_id)\\n        # Write the durable STOP signal + cancel the in-flight executor task\\n        # BEFORE flipping the row to CANCELLED. The signal is the marker the\\n        # runner's terminal reconcile keys off, so persisting it first means an\\n        # in-flight runner racing to a terminal state reliably observes the stop\\n        # and finalizes CANCELLED rather than overwriting it with COMPLETED/FAILED.\\n        # Best-effort: a backend that cannot take the signal must not block the\\n        # cancel, but swallowing it silently would hide the one failure that lets\\n        # a run keep going after we report CANCELLED. Log, do not suppress quietly.\\n        try:\\n            await get_background_execution_service().stop_job(job_id, current_user)\\n        except Exception:  # noqa: BLE001\\n            await logger.aexception(\\\"Failed to signal stop for workflow job %s; cancelling row anyway\\\", job_id)\\n        await job_service.update_job_status(job_id, JobStatus.CANCELLED)\\n\\n        message = f\\\"Job {job_id} cancelled successfully.\\\" if revoked else f\\\"Job {job_id} is already cancelled.\\\"\\n        return WorkflowStopResponse(job_id=str(job_id), message=message)\\n    except asyncio.CancelledError as exc:\\n        # Handle system-initiated cancellations that were re-raised\\n        # The job status has already been updated to FAILED in jobs/service.py\\n        message_code = exc.args[0] if exc.args else \\\"UNKNOWN\\\"\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail={\\n                \\\"error\\\": \\\"Task cancellation error\\\",\\n                \\\"code\\\": message_code,\\n                \\\"message\\\": f\\\"Job {job_id} was cancelled unexpectedly by the system\\\",\\n                \\\"job_id\\\": str(job_id),\\n            },\\n        ) from exc\\n    except HTTPException:\\n        raise\\n    except Exception as exc:\\n        await logger.aexception(\\\"Unexpected error stopping workflow job %s\\\", job_id)\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail={\\n                \\\"error\\\": \\\"Internal server error\\\",\\n                \\\"code\\\": \\\"INTERNAL_SERVER_ERROR\\\",\\n                \\\"message\\\": f\\\"Failed to stop job {job_id}.\\\",\\n            },\\n        ) from exc\\n\\n\\n@router.get(\\n    \\\"/pending\\\",\\n    summary=\\\"List pending human-input requests\\\",\\n    description=\\\"Suspended HITL jobs for a flow plus their pending request, for the Traces overlay.\\\",\\n)\\nasync def list_pending_workflows(\\n    http_request: Request,\\n    current_user: Annotated[UserRead, Depends(get_current_user_for_workflow)],\\n    flow_id: Annotated[UUID, Query(description=\\\"Flow ID to list pending HITL requests for\\\")],\\n) -> list[dict]:\\n    from langflow.api.v2.hitl import list_pending_human_requests\\n\\n    # Serving-plane end-user isolation: this endpoint ENUMERATES suspended runs by flow_id (no job\\n    # id needed), and each row exposes the merged session_id + the HITL prompt \u2014 so a scope check is\\n    # even more load-bearing here than on status/stop/resume. Filter to the caller's own end user.\\n    # The superuser \\\"see all\\\" bypass applies only when serving is off; on the serving plane the SID\\n    # is a superuser, so an unconditional bypass would leak every end user's suspended run to every\\n    # other. Feature off / anonymous -> only end-user-less jobs, unchanged. See F8 / B1.\\n    return await list_pending_human_requests(\\n        flow_id,\\n        current_user.id,\\n        request_end_user_id=resolve_serving_end_user_id(http_request=http_request),\\n        include_all_end_users=current_user.is_superuser and not serving_end_user_enabled(),\\n    )\\n\\n\\n@router.post(\\n    \\\"/{job_id}/resume\\\",\\n    summary=\\\"Resume Workflow\\\",\\n    description=\\\"Resume a suspended (human-in-the-loop) workflow with a decision.\\\",\\n)\\nasync def resume_workflow(\\n    job_id: str,\\n    request: WorkflowResumeRequest,\\n    http_request: Request,\\n    current_user: Annotated[UserRead, Depends(get_current_user_for_workflow)],\\n) -> WorkflowResumeResponse:\\n    \\\"\\\"\\\"Resume a SUSPENDED workflow run with a human decision.\\n\\n    Owner-or-superuser; a non-owner non-superuser (or unknown/non-workflow job)\\n    maps to 404 to avoid leaking other users' runs. A stale/duplicate request_id\\n    or a non-suspended job maps to 409 (single-use enforced behind ``resume_job``).\\n    Resuming executes the remainder of the flow, so flow:execute is re-enforced \u2014\\n    access revoked while the run was suspended must not let the decision through.\\n    \\\"\\\"\\\"\\n\\n    def _not_found() -> HTTPException:\\n        return HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail={\\\"error\\\": \\\"Workflow job not found\\\", \\\"code\\\": \\\"JOB_NOT_FOUND\\\", \\\"job_id\\\": job_id},\\n        )\\n\\n    try:\\n        parsed_job_id = UUID(job_id)\\n    except ValueError as exc:\\n        raise _not_found() from exc\\n\\n    job = await get_job_service().get_job_by_job_id(parsed_job_id)\\n    is_owner = job is not None and job.user_id is not None and job.user_id == current_user.id\\n    if job is None or job.type != JobType.WORKFLOW or not (is_owner or current_user.is_superuser):\\n        raise _not_found()\\n    # Serving-plane end-user isolation: a different end user (sharing the SID) must not resume\\n    # another's suspended run. Layered on the SID owner/superuser check above. See F8.\\n    if not _caller_owns_job_end_user(job, http_request, current_user):\\n        raise _not_found()\\n\\n    from langflow.api.v2.hitl import ensure_resume_execute_permission, is_decision_allowed, mark_card_answered\\n\\n    await ensure_resume_execute_permission(current_user, job.flow_id)\\n\\n    if not await is_decision_allowed(parsed_job_id, request.decision or {}):\\n        raise HTTPException(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            detail={\\n                \\\"error\\\": \\\"Invalid decision\\\",\\n                \\\"code\\\": \\\"INVALID_DECISION\\\",\\n                \\\"message\\\": \\\"decision.action_id is not one of the pending request's allowed_decisions.\\\",\\n                \\\"job_id\\\": job_id,\\n            },\\n        )\\n\\n    service = get_background_execution_service()\\n    if service._frame_source_factory is None:  # noqa: SLF001\\n        service._frame_source_factory = _default_frame_source_factory  # noqa: SLF001\\n    # Snapshot the card id before the continuation runs: it may reach another pause and\\n    # overwrite job metadata, and this decision must never stamp that later card.\\n    card_message_id = (job.job_metadata or {}).get(\\\"card_message_id\\\")\\n    try:\\n        accepted = await service.resume_job(\\n            parsed_job_id,\\n            current_user,\\n            request_id=request.request_id,\\n            decision=request.decision or {},\\n        )\\n    except RequestOverridesUnavailableError as err:\\n        raise HTTPException(\\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n            detail={\\n                \\\"error\\\": \\\"Service unavailable\\\",\\n                \\\"code\\\": \\\"REQUEST_OVERRIDES_UNAVAILABLE\\\",\\n                \\\"message\\\": \\\"Background request overrides are temporarily unavailable. Please try again.\\\",\\n                \\\"job_id\\\": job_id,\\n            },\\n        ) from err\\n    if not accepted:\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail={\\n                \\\"error\\\": \\\"Job is not resumable\\\",\\n                \\\"code\\\": \\\"NOT_RESUMABLE\\\",\\n                \\\"message\\\": \\\"Job is not suspended, already resumed, or the request_id is stale.\\\",\\n                \\\"job_id\\\": job_id,\\n            },\\n        )\\n    await mark_card_answered(parsed_job_id, request.request_id, request.decision or {}, card_message_id=card_message_id)\\n    return WorkflowResumeResponse(job_id=job_id, status=\\\"resuming\\\", message=\\\"Resume accepted\\\")\\n\\n\\n@router.get(\\n    \\\"/{job_id}/events\\\",\\n    response_model=None,\\n    summary=\\\"Re-attach to a background run\\\",\\n    description=\\\"Replay durable events for a background run from Last-Event-ID and tail until it ends.\\\",\\n)\\nasync def reattach_workflow_events(\\n    job_id: str,\\n    http_request: Request,\\n    current_user: Annotated[UserRead, Depends(get_current_user_for_workflow)],\\n) -> EventSourceResponse:\\n    \\\"\\\"\\\"Re-attach to a background run.\\n\\n    Replays durable milestones from the ``job_events`` log (after\\n    ``Last-Event-ID``) then tails the live bus until the run ends.\\n\\n    Ownership is enforced by the facade; a cross-user or unknown job maps to a\\n    404 to avoid leaking the existence of other users' runs. The pre-check runs\\n    before streaming starts so the error body is a clean JSON 404 rather than a\\n    half-open SSE stream.\\n    \\\"\\\"\\\"\\n    service = get_background_execution_service()\\n    last_event_id = http_request.headers.get(\\\"Last-Event-ID\\\")\\n\\n    def _not_found() -> HTTPException:\\n        return HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail={\\n                \\\"error\\\": \\\"Background run not found\\\",\\n                \\\"code\\\": \\\"JOB_NOT_FOUND\\\",\\n                \\\"message\\\": f\\\"No background run for job {job_id}.\\\",\\n                \\\"job_id\\\": job_id,\\n            },\\n        )\\n\\n    try:\\n        # Pre-validate ownership/existence so a deny surfaces as a 404 before\\n        # the SSE stream opens. ``events`` re-validates as defense-in-depth.\\n        await service.status(UUID(job_id), current_user)\\n        job = await get_job_service().get_job_by_job_id(UUID(job_id), user_id=current_user.id)\\n    except (PermissionError, ValueError) as exc:\\n        raise _not_found() from exc\\n\\n    # Serving-plane end-user isolation: a different end user (sharing the SID) must not reattach\\n    # to another's live event stream \u2014 the same rule the status/stop/resume paths enforce. See F8.\\n    if job is None or not _caller_owns_job_end_user(job, http_request, current_user):\\n        raise _not_found()\\n\\n    return EventSourceResponse(\\n        service.events(UUID(job_id), last_event_id=last_event_id, user=current_user),\\n        headers={\\\"Cache-Control\\\": \\\"no-cache\\\", \\\"X-Accel-Buffering\\\": \\\"no\\\"},\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v2/workflow_background.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"746ceb7cf089d6bb26085d291483376a3e40a4bb9cb5a277df863c5d23067471\",\"content\":\"\\\"\\\"\\\"Background (durable, re-attachable) execution for V2 workflows.\\n\\nA background run is driven by ``_stream_event_frames`` (from\\n``workflow_execution``) and its protocol-native SSE frames are buffered in a\\nprocess-local ``_BackgroundRun`` so a disconnected client can re-attach and\\nreplay. ``_BACKGROUND_RUNS`` is the bounded registry keyed by job_id; the job\\nrow in the database lets ``GET /workflows`` and ``POST /workflows/stop`` keep\\nworking across re-attaches.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nfrom collections.abc import AsyncIterator, Callable, Iterable\\nfrom uuid import UUID\\n\\nfrom fastapi import BackgroundTasks, Request\\nfrom fastapi.sse import format_sse_event\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.workflow import JobId, JobStatus, WorkflowJobResponse\\nfrom lfx.workflow.adapters import (\\n    StreamAdapterContext,\\n    StreamEvent,\\n    UnknownStreamProtocolError,\\n    get_stream_adapter,\\n)\\nfrom lfx.workflow.converters import ParsedWorkflowRun\\n\\nfrom langflow.api.utils.execution_errors import caller_owns_flow\\nfrom langflow.api.v2.workflow_execution import _stream_event_frames\\nfrom langflow.exceptions.api import (\\n    WorkflowQueueFullError,\\n    WorkflowResourceError,\\n    WorkflowServiceUnavailableError,\\n)\\nfrom langflow.services.database.models.flow.model import FlowRead\\nfrom langflow.services.database.models.user.model import UserRead\\nfrom langflow.services.deps import get_job_service, get_queue_service\\n\\n\\nasync def _cancel_workflow_queue_job(job_id: str) -> bool:\\n    \\\"\\\"\\\"Lazily call the shared build cancellation path to avoid import cycles.\\\"\\\"\\\"\\n    from langflow.api.build import cancel_flow_build\\n    from langflow.services.job_queue.service import JobQueueNotFoundError\\n\\n    try:\\n        return await cancel_flow_build(job_id=job_id, queue_service=get_queue_service())\\n    except JobQueueNotFoundError:\\n        return False\\n\\n\\n_CancelEventsFactory = Callable[[str], Iterable[StreamEvent]]\\n\\n\\nclass _BackgroundRun:\\n    \\\"\\\"\\\"In-memory buffer of a background run's protocol-native SSE frames for re-attach.\\n\\n    The buffer lives in the process; restarts drop it. Multiple readers can\\n    re-attach concurrently and tail until the run ends. The frames are\\n    already serialized in the protocol the original POST requested via\\n    ``stream_protocol``; re-attach replays them as-is. Mixing protocols\\n    across a single run is not supported.\\n\\n    Per-run frame count is bounded by ``_MAX_FRAMES_PER_BACKGROUND_RUN`` so a\\n    long verbose run (token-by-token streams, repeated tool calls) cannot\\n    exhaust process memory while ``_MAX_BACKGROUND_RUNS`` only caps the\\n    number of buffers. When the cap is reached the oldest frames are\\n    evicted; re-attach with ``Last-Event-ID`` past that point will start\\n    from the new buffer head (replay loss is preferred over OOM).\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, user_id: str, stream_protocol: str = \\\"agui\\\") -> None:\\n        self.user_id = user_id\\n        self.stream_protocol = stream_protocol\\n        self._cancel_events: _CancelEventsFactory | None = None\\n        self.frames: list[bytes] = []\\n        # Index of the first frame still in ``frames`` (monotonic across the\\n        # life of the buffer). Once eviction starts, ``frames[i]`` corresponds\\n        # to logical event id ``base_index + i``.\\n        self.base_index = 0\\n        self.done = False\\n        self._cond = asyncio.Condition()\\n\\n    def set_cancel_events(self, cancel_events: _CancelEventsFactory) -> None:\\n        self._cancel_events = cancel_events\\n\\n    @property\\n    def has_cancel_events(self) -> bool:\\n        return self._cancel_events is not None\\n\\n    def _append_locked(self, frame: bytes) -> None:\\n        self.frames.append(frame)\\n        overflow = len(self.frames) - _MAX_FRAMES_PER_BACKGROUND_RUN\\n        if overflow > 0:\\n            del self.frames[:overflow]\\n            self.base_index += overflow\\n\\n    async def append(self, frame: bytes) -> None:\\n        async with self._cond:\\n            self._append_locked(frame)\\n            self._cond.notify_all()\\n\\n    async def finish(self) -> None:\\n        async with self._cond:\\n            self.done = True\\n            self._cond.notify_all()\\n\\n    async def finish_cancelled(self, reason: str) -> None:\\n        \\\"\\\"\\\"Append cancellation terminal events and finish replay exactly once.\\\"\\\"\\\"\\n        async with self._cond:\\n            if self.done:\\n                return\\n            events: list[StreamEvent] = []\\n            if self._cancel_events is not None:\\n                with contextlib.suppress(Exception):\\n                    events = list(self._cancel_events(reason))\\n            for event in events:\\n                seq = self.base_index + len(self.frames)\\n                self._append_locked(format_sse_event(data_str=event.data_json, id=str(seq)))\\n            self.done = True\\n            self._cond.notify_all()\\n\\n    async def replay(self, start_index: int) -> AsyncIterator[bytes]:\\n        \\\"\\\"\\\"Yield buffered frames from ``start_index`` and tail until done.\\n\\n        ``start_index`` is in logical event-id space (matches what was emitted\\n        on ``id:`` lines). If the caller's ``Last-Event-ID`` points before the\\n        buffer's current head (frames evicted under memory pressure), we\\n        replay from the head and the caller observes a gap.\\n        \\\"\\\"\\\"\\n        idx = max(start_index, 0)\\n        while True:\\n            async with self._cond:\\n                head = self.base_index\\n                tail = head + len(self.frames)\\n                idx = max(idx, head)\\n                while idx >= tail and not self.done:\\n                    await self._cond.wait()\\n                    head = self.base_index\\n                    tail = head + len(self.frames)\\n                    idx = max(idx, head)\\n                snapshot = self.frames[idx - head :]\\n                finished = self.done\\n            for frame in snapshot:\\n                yield frame\\n            idx += len(snapshot)\\n            if finished and idx >= self.base_index + len(self.frames):\\n                return\\n\\n\\n# Process-local registry of background runs keyed by job_id, bounded by\\n# ``_MAX_BACKGROUND_RUNS`` (oldest evicted first). Re-attach reads this.\\n_MAX_BACKGROUND_RUNS = 100\\n# Per-run frame ceiling. Caps memory for a single long/verbose run so a\\n# token-streaming flow can't exhaust the process. 10k frames covers minutes\\n# of dense token streams with room to spare; beyond that we evict oldest.\\n_MAX_FRAMES_PER_BACKGROUND_RUN = 10_000\\n_BACKGROUND_RUNS: dict[str, _BackgroundRun] = {}\\n_WORKFLOW_CANCELLED_MESSAGE = \\\"Workflow run cancelled.\\\"\\n\\n\\nasync def _finalize_job_status(job_uuid: UUID, terminal_status: JobStatus) -> None:\\n    \\\"\\\"\\\"Update job status to a terminal value, but never overwrite CANCELLED or SUSPENDED.\\n\\n    ``stop_workflow`` sets the job to CANCELLED. The buffer task runs in\\n    parallel and reaches its ``finally`` block shortly after; if it\\n    unconditionally wrote COMPLETED/FAILED it would race with the cancellation\\n    and silently overwrite the user's stop intent. SUSPENDED is guarded for the\\n    same reason plus defense-in-depth: HITL suspend runs on the durable substrate\\n    (which skips finalization while ``paused``), so a suspended job should never\\n    reach this AGUI path \u2014 but if one ever did, finalizing it would clobber the\\n    resumable state. Re-read the row first and skip the update for either.\\n    \\\"\\\"\\\"\\n    job_service = get_job_service()\\n    try:\\n        job = await job_service.get_job_by_job_id(job_id=job_uuid)\\n    except Exception:  # noqa: BLE001\\n        job = None\\n    if job is not None and job.status in {JobStatus.CANCELLED, JobStatus.SUSPENDED}:\\n        return\\n    with contextlib.suppress(Exception):\\n        await job_service.update_job_status(\\n            job_uuid,\\n            terminal_status,\\n            finished_timestamp=True,\\n        )\\n\\n\\nasync def _clear_background_run(job_id: str) -> None:\\n    \\\"\\\"\\\"Pop the background run registry entry and wake any re-attach waiters.\\n\\n    Used for true cleanup paths that should discard replay state, such as\\n    failed scheduling or test teardown. Cancellation normally finishes through\\n    the owning buffer task so it can append protocol-native terminal events\\n    before replay is marked done.\\n    \\\"\\\"\\\"\\n    bg_run = _BACKGROUND_RUNS.pop(job_id, None)\\n    if bg_run is not None:\\n        await bg_run.finish()\\n\\n\\nasync def _finish_cancelled_background_run(job_id: str) -> None:\\n    \\\"\\\"\\\"Finish a stopped local run when no owner task is available to do it.\\\"\\\"\\\"\\n    bg_run = _BACKGROUND_RUNS.get(job_id)\\n    if bg_run is None or bg_run.done:\\n        return\\n    if not bg_run.has_cancel_events:\\n        with contextlib.suppress(UnknownStreamProtocolError):\\n            adapter = get_stream_adapter(\\n                bg_run.stream_protocol,\\n                StreamAdapterContext(run_id=job_id, thread_id=job_id),\\n            )\\n            bg_run.set_cancel_events(adapter.cancel_events)\\n    await bg_run.finish_cancelled(_WORKFLOW_CANCELLED_MESSAGE)\\n\\n\\nasync def _register_background_run(job_id: str, bg_run: _BackgroundRun) -> None:\\n    \\\"\\\"\\\"Register a background run, evicting a completed entry when full.\\n\\n    Prefer evicting the oldest *completed* run so a long-running job's\\n    re-attach handle survives. If every slot is still active, evict the\\n    oldest one anyway to keep the registry bounded, cancel its still-running\\n    buffer writer so it stops appending into a run no reader can find, and log\\n    a warning.\\n    \\\"\\\"\\\"\\n    if len(_BACKGROUND_RUNS) >= _MAX_BACKGROUND_RUNS:\\n        evict_key = next(\\n            (key for key, run in _BACKGROUND_RUNS.items() if run.done),\\n            None,\\n        )\\n        evicted_running = False\\n        if evict_key is None:\\n            evict_key = next(iter(_BACKGROUND_RUNS))\\n            evicted_running = True\\n            logger.warning(\\n                \\\"Background run registry full with no completed entries; \\\"\\n                \\\"evicting still-running job %s to make room for %s\\\",\\n                evict_key,\\n                job_id,\\n            )\\n        _BACKGROUND_RUNS.pop(evict_key, None)\\n        if evicted_running:\\n            # Stop the orphaned buffer writer: without its registry entry no\\n            # reader can find it, but the coroutine keeps appending frames.\\n            # cancel_flow_build raises CancelledError into the build loop, which\\n            # runs the buffer's finally/finish_cancelled path.\\n            with contextlib.suppress(Exception):\\n                await _cancel_workflow_queue_job(evict_key)\\n    _BACKGROUND_RUNS[job_id] = bg_run\\n\\n\\nasync def _buffer_background_run(\\n    *,\\n    bg_run: _BackgroundRun,\\n    flow: FlowRead,\\n    parsed: ParsedWorkflowRun,\\n    job_id: str,\\n    current_user: UserRead,\\n    stream_protocol: str,\\n) -> None:\\n    \\\"\\\"\\\"Run a background flow, buffer its frames, and finalize job status.\\n\\n    The adapter is resolved from ``stream_protocol`` so re-attach replays\\n    frames in the protocol the caller requested. Validation of\\n    ``stream_protocol`` happens at the route handler; this function still\\n    guards against ``UnknownStreamProtocolError`` because it runs as a\\n    fire-and-forget background coroutine. If adapter registration breaks\\n    between the route's check and this call (e.g. a registry mutation), we\\n    flip the job to FAILED and exit cleanly rather than dying silently and\\n    leaving the job stuck at QUEUED.\\n\\n    The buffer's terminal-status detection keys off\\n    ``adapter.terminal_error_type``.\\n    \\\"\\\"\\\"\\n    try:\\n        adapter = get_stream_adapter(\\n            stream_protocol,\\n            StreamAdapterContext(\\n                run_id=parsed.run_id or job_id,\\n                thread_id=parsed.session_id or str(flow.id),\\n            ),\\n        )\\n    except UnknownStreamProtocolError:\\n        # Fire-and-forget coroutine: do not raise, the route already returned.\\n        await bg_run.finish()\\n        job_uuid = UUID(job_id) if isinstance(job_id, str) else job_id\\n        await _finalize_job_status(job_uuid, JobStatus.FAILED)\\n        return\\n\\n    bg_run.set_cancel_events(adapter.cancel_events)\\n    terminal_error_type = adapter.terminal_error_type\\n    fresh_background_tasks = BackgroundTasks()\\n    errored = False\\n    cancelled = False\\n    job_uuid = UUID(job_id) if isinstance(job_id, str) else job_id\\n    try:\\n        with contextlib.suppress(Exception):\\n            await get_job_service().update_job_status(job_uuid, JobStatus.IN_PROGRESS)\\n        async for frame, event_type in _stream_event_frames(\\n            adapter=adapter,\\n            flow_id=flow.id,\\n            flow_name=flow.name,\\n            background_tasks=fresh_background_tasks,\\n            parsed=parsed,\\n            current_user=current_user,\\n            provider_policy_flow=flow,\\n            source_flow_owner_id=flow.user_id,\\n            expose_error_details=caller_owns_flow(flow, current_user),\\n            # Build under the job id so the run's vertex builds are persisted\\n            # keyed by job_id and GET-status reconstruction can find them.\\n            run_id=job_id,\\n            # Also as job_id: run_id keys the persisted vertex builds, job_id is what the\\n            # trace carrier is looked up by. Passing only the first reads no carrier, so this\\n            # path would quietly produce unlinked runs.\\n            job_id=job_uuid,\\n            track_job_status=False,\\n            # Distinct from the live v2 stream: same driver, but nobody is holding the connection,\\n            # so an operator reading latency needs to tell the two apart.\\n            protocol=\\\"v2.background\\\",\\n        ):\\n            if terminal_error_type is not None and event_type == terminal_error_type:\\n                errored = True\\n            await bg_run.append(frame)\\n    except asyncio.CancelledError:\\n        cancelled = True\\n        await bg_run.finish_cancelled(_WORKFLOW_CANCELLED_MESSAGE)\\n        raise\\n    finally:\\n        if not cancelled:\\n            await bg_run.finish()\\n        # ``generate_flow_events`` queues telemetry, tracing teardown, and\\n        # other callbacks on this ``BackgroundTasks`` instance. In FastAPI's\\n        # request lifecycle those run after the response is sent; the\\n        # background path has no response carrying them, so drain the queue\\n        # explicitly. Suppressed so a single failing telemetry callback does\\n        # not derail job-status finalization.\\n        with contextlib.suppress(Exception):\\n            await fresh_background_tasks()\\n        if not cancelled:\\n            # ``update_job_status`` queries the Job table by its UUID primary key;\\n            # passing the raw string would silently miss every row.\\n            await _finalize_job_status(job_uuid, JobStatus.FAILED if errored else JobStatus.COMPLETED)\\n\\n\\nasync def execute_workflow_background(\\n    parsed: ParsedWorkflowRun,\\n    flow: FlowRead,\\n    job_id: JobId,\\n    current_user: UserRead,\\n    http_request: Request,  # noqa: ARG001\\n    stream_protocol: str,\\n) -> WorkflowJobResponse:\\n    \\\"\\\"\\\"Run a workflow in the background, buffering protocol-native events for re-attach.\\n\\n    A job row is created so ``GET /workflows`` and ``POST /workflows/stop`` keep\\n    working. The buffer task is scheduled through the queue service under\\n    ``job_id`` so ``/stop`` can revoke it. Graph construction happens inside\\n    the v1 build-vertex loop driven by ``_stream_event_frames`` with the\\n    adapter selected by ``stream_protocol``; re-attach replays the frames in\\n    that same protocol's wire shape.\\n    \\\"\\\"\\\"\\n    try:\\n        flow_id_str = str(flow.id)\\n        job_id_str = str(job_id)\\n\\n        await get_job_service().create_job(\\n            job_id=job_id,\\n            flow_id=flow_id_str,\\n            user_id=current_user.id,\\n        )\\n\\n        bg_run = _BackgroundRun(user_id=str(current_user.id), stream_protocol=stream_protocol)\\n        await _register_background_run(job_id_str, bg_run)\\n\\n        try:\\n            queue_service = get_queue_service()\\n            queue_service.create_queue(job_id_str)\\n            queue_service.start_job(\\n                job_id_str,\\n                _buffer_background_run(\\n                    bg_run=bg_run,\\n                    flow=flow,\\n                    parsed=parsed,\\n                    job_id=job_id_str,\\n                    current_user=current_user,\\n                    stream_protocol=stream_protocol,\\n                ),\\n            )\\n        except BaseException:\\n            # If queue creation or scheduling fails after the bg_run is\\n            # registered, the buffer would stay live with ``done=False`` and\\n            # any re-attach client would block on ``_cond.wait()`` forever\\n            # (the task that would call ``finish()`` was never scheduled).\\n            # Clear the registry, mark the job FAILED, then re-raise.\\n            await _clear_background_run(job_id_str)\\n            await _finalize_job_status(job_id, JobStatus.FAILED)\\n            raise\\n        return WorkflowJobResponse(job_id=job_id_str, flow_id=parsed.flow_id, status=JobStatus.QUEUED)\\n\\n    except (WorkflowResourceError, WorkflowServiceUnavailableError, WorkflowQueueFullError):\\n        raise\\n    except MemoryError as exc:\\n        raise WorkflowResourceError from exc\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v2/workflow_execution.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1a6c9f4b3d05c806d7599a3afe7185206e417dfae4134bf1bae9299652a11d5d\",\"content\":\"\\\"\\\"\\\"Synchronous and streaming execution for V2 workflows.\\n\\nThis module owns the run-driving machinery shared by every execution mode:\\n\\n    - ``execute_sync_workflow`` / ``execute_sync_workflow_with_timeout``: the\\n      inline sync path that returns a complete ``WorkflowExecutionResponse``.\\n    - ``_stream_event_frames``: the single chokepoint that drives the v1\\n      build-vertex loop and dispatches its events through a ``StreamAdapter``.\\n      The streaming route, the public endpoint, and the background buffer all\\n      consume it.\\n    - ``_execute_streaming_workflow``: wraps ``_stream_event_frames`` in an SSE\\n      response for live streaming.\\n\\nConfiguration:\\n    EXECUTION_TIMEOUT: Maximum execution time for synchronous workflows (300 seconds).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nimport json\\nimport time\\nfrom collections.abc import AsyncIterator\\nfrom copy import deepcopy\\nfrom typing import Final\\nfrom uuid import UUID, uuid4\\n\\nfrom ag_ui.core import CustomEvent\\nfrom fastapi import BackgroundTasks, Request\\nfrom fastapi.responses import EventSourceResponse\\nfrom fastapi.sse import format_sse_event\\nfrom lfx.events.event_manager import create_default_event_manager\\nfrom lfx.exceptions.tweaks import TweakRefusedError\\nfrom lfx.graph.checkpoint.store import CheckpointStore\\nfrom lfx.graph.exceptions import GraphPausedException\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import execution_protocol, extract_trace_link, queued_trace_link, tracing_is_available\\nfrom lfx.schema.schema import InputValueRequest\\nfrom lfx.schema.workflow import JobStatus, WorkflowExecutionResponse\\nfrom lfx.workflow.adapters import StreamAdapter, StreamEvent\\nfrom lfx.workflow.adapters.langflow import WORKFLOW_OUTPUT_CAPTURE_EVENT, build_terminal_output_event\\nfrom lfx.workflow.converters import ParsedWorkflowRun, create_error_response, run_response_to_workflow_response\\n\\nfrom langflow.api.utils import extract_global_variables_from_headers\\nfrom langflow.api.utils.execution_errors import caller_owns_flow, error_for_client\\nfrom langflow.api.v1.schemas import FlowDataRequest, RunResponse\\nfrom langflow.api.v2.workflow_validation import _validate_output_ids\\nfrom langflow.api.warm_graph import warm_deepcopy\\nfrom langflow.exceptions.api import WorkflowTimeoutError, WorkflowValidationError\\nfrom langflow.processing.process import process_tweaks, run_graph_internal\\nfrom langflow.services.database.models.flow.model import FlowRead\\nfrom langflow.services.database.models.user.model import UserRead\\nfrom langflow.services.deps import get_job_service, get_memory_base_service, get_settings_service, get_task_service\\nfrom langflow.services.model_provider_policy_scope import scoped_model_provider_policy_for_flow\\nfrom langflow.services.warm_registry.service import flow_version\\n\\n# Configuration constants\\nEXECUTION_TIMEOUT = 300  # 5 minutes default timeout for sync execution, used as a fallback\\n\\n\\ndef _resolve_execution_timeout() -> int:\\n    \\\"\\\"\\\"Wall-clock ceiling for a single workflow run, from settings.\\n\\n    Falls back to ``EXECUTION_TIMEOUT`` if the settings service is unavailable\\n    (e.g. a fire-and-forget background coroutine running during teardown).\\n    \\\"\\\"\\\"\\n    try:\\n        return get_settings_service().settings.workflow_execution_timeout\\n    except Exception:  # noqa: BLE001\\n        return EXECUTION_TIMEOUT\\n\\n\\n# Inline stream queue between the build loop and the SSE consumer. Bounded\\n# so a slow consumer applies backpressure to the build loop instead of\\n# letting frames accumulate without bound when the network is slow.\\n_EVENT_QUEUE_MAX_SIZE = 256\\n\\n\\nclass _CeilingFromSettings:\\n    \\\"\\\"\\\"Sentinel type for ``_stream_event_frames(execution_timeout=...)``.\\n\\n    Its own class rather than a bare ``object()`` so the parameter carries a real\\n    static type and an ``isinstance`` check narrows the remaining value to\\n    ``float | None`` for ``asyncio.wait_for``. Distinct from ``None`` so a caller\\n    can ask for \\\"unbounded\\\" without it collapsing into \\\"use the default\\\".\\n    \\\"\\\"\\\"\\n\\n\\n_CEILING_FROM_SETTINGS: Final = _CeilingFromSettings()\\n\\n\\nasync def generate_flow_events(*args, **kwargs) -> None:\\n    \\\"\\\"\\\"Lazily call the v1 build stream to avoid import cycles during router setup.\\\"\\\"\\\"\\n    from langflow.api.build import generate_flow_events as _generate_flow_events\\n\\n    await _generate_flow_events(*args, **kwargs)\\n\\n\\ndef _resolve_request_variables(body_globals: dict[str, str], http_request: Request | None) -> dict[str, str]:\\n    \\\"\\\"\\\"Merge request-level global variables for a v2 workflow execution.\\n\\n    v2 workflows take globals from the JSON request body (``globals``). The\\n    ``X-LANGFLOW-GLOBAL-VAR-*`` headers remain a supported transport (the\\n    OpenAI-compatible Responses API passes globals that way); body globals win\\n    on conflict.\\n    \\\"\\\"\\\"\\n    header_globals: dict[str, str] = {}\\n    if http_request is not None:\\n        header_globals = extract_global_variables_from_headers(http_request.headers)\\n    return {**header_globals, **dict(body_globals or {})}\\n\\n\\ndef _build_run_inputs(parsed: ParsedWorkflowRun) -> list[InputValueRequest] | None:\\n    \\\"\\\"\\\"Build the graph input list from the AG-UI chat message, if any.\\n\\n    The last user message becomes a single chat input; an empty message means\\n    the flow runs with no chat input (parameters arrive via tweaks instead).\\n    \\\"\\\"\\\"\\n    if not parsed.input_value:\\n        return None\\n    return [InputValueRequest(components=[], input_value=parsed.input_value, type=\\\"chat\\\")]\\n\\n\\ndef _single_input_value_request(parsed: ParsedWorkflowRun) -> InputValueRequest | None:\\n    \\\"\\\"\\\"Build the single chat InputValueRequest the v1 build loop accepts.\\n\\n    The v1 build path (``generate_flow_events``) takes a single\\n    ``InputValueRequest``; when it receives ``None`` it falls back to\\n    ``InputValueRequest(session=str(flow_id))``, which would wipe out the\\n    caller's session id. We always return one with the parsed session so\\n    component messages stay scoped to the user's active session, even when\\n    there is no chat input (e.g. the playground \\\"Run Flow\\\" button).\\n    \\\"\\\"\\\"\\n    if not parsed.session_id and not parsed.input_value:\\n        return None\\n    return InputValueRequest(\\n        components=[],\\n        input_value=parsed.input_value or \\\"\\\",\\n        type=\\\"chat\\\",\\n        session=parsed.session_id,\\n    )\\n\\n\\n_QueueItem = tuple[str | None, bytes | None, float]\\n\\n\\nclass _WorkflowEventQueue:\\n    \\\"\\\"\\\"Bounded EventManager handoff that fails explicitly instead of dropping events.\\\"\\\"\\\"\\n\\n    def __init__(self, maxsize: int) -> None:\\n        self._queue: asyncio.Queue[_QueueItem] = asyncio.Queue(maxsize=maxsize)\\n        self._overflowed = False\\n        self._loop = asyncio.get_running_loop()\\n        self._overflow_task: asyncio.Task[None] | None = None\\n\\n    @property\\n    def maxsize(self) -> int:\\n        return self._queue.maxsize\\n\\n    async def get(self) -> _QueueItem:\\n        return await self._queue.get()\\n\\n    async def put(self, item: _QueueItem) -> None:\\n        if self._overflowed:\\n            return\\n        await self._queue.put(item)\\n\\n    def put_nowait(self, item: _QueueItem) -> None:\\n        if self._overflowed:\\n            return\\n        try:\\n            self._queue.put_nowait(item)\\n        except asyncio.QueueFull:\\n            self._overflowed = True\\n            self._overflow_task = self._loop.create_task(self._emit_overflow_error())\\n\\n    async def _emit_overflow_error(self) -> None:\\n        payload = {\\n            \\\"event\\\": \\\"error\\\",\\n            \\\"data\\\": {\\n                \\\"error\\\": \\\"Workflow event stream exceeded buffering capacity; client is consuming events too slowly.\\\"\\n            },\\n        }\\n        await self._queue.put((f\\\"error-{uuid4()}\\\", json.dumps(payload).encode(\\\"utf-8\\\"), time.time()))\\n        await self._queue.put((None, None, time.time()))\\n\\n    async def aclose(self) -> None:\\n        if self._overflow_task is not None and not self._overflow_task.done():\\n            self._overflow_task.cancel()\\n            with contextlib.suppress(asyncio.CancelledError):\\n                await self._overflow_task\\n\\n\\nasync def _queued_trace_link_for(job_id: UUID | None):\\n    \\\"\\\"\\\"Return a link to the request that enqueued *job_id*, or None.\\n\\n    None for a synchronous run, which has no job row, and for a job enqueued while nothing was\\n    tracing. Never raises: a run must not fail because its telemetry could not be looked up.\\n    \\\"\\\"\\\"\\n    if job_id is None:\\n        return None\\n    if not tracing_is_available():\\n        # The row would be read, parsed, and thrown away. A deployment without the telemetry\\n        # extra should not pay a SELECT per run and per resume for a link nothing can render.\\n        return None\\n    try:\\n        job = await get_job_service().get_job_by_job_id(job_id)\\n    except Exception:  # noqa: BLE001\\n        await logger.adebug(\\\"could not read the job row for its trace carrier\\\", exc_info=True)\\n        return None\\n    return extract_trace_link(job.job_metadata if job else None)\\n\\n\\nasync def _stream_event_frames(\\n    *,\\n    adapter: StreamAdapter,\\n    flow_id: UUID,\\n    flow_name: str | None,\\n    background_tasks: BackgroundTasks,\\n    parsed: ParsedWorkflowRun,\\n    current_user: UserRead,\\n    provider_policy_flow: FlowRead | None = None,\\n    source_flow_id: UUID | None = None,\\n    source_flow_owner_id: UUID | None = None,\\n    run_id: str | None = None,\\n    job_id: UUID | None = None,\\n    resume: dict | None = None,\\n    track_job_status: bool = True,\\n    # Required, not defaulted: a default is how an unwired caller gets a confidently wrong\\n    # label, which is the one thing the absent-rather-than-\\\"unknown\\\" rule exists to prevent.\\n    protocol: str,\\n    emit_output_capture: bool = False,\\n    expose_error_details: bool = False,\\n    execution_timeout: float | None | _CeilingFromSettings = _CEILING_FROM_SETTINGS,\\n) -> AsyncIterator[tuple[bytes, str]]:\\n    \\\"\\\"\\\"Run a flow via the v1 build-vertex loop, dispatch its events through ``adapter``.\\n\\n    Yields ``(sse_frame_bytes, event_type_str)`` pairs. The consumer\\n    (streaming endpoint, background buffer) frames are pre-formatted with a\\n    monotonic ``id:`` for ``Last-Event-ID`` resume. The ``event_type_str`` is\\n    the adapter's protocol-native type so the buffer task can finalize a\\n    background job's status structurally (no substring matching).\\n\\n    A failure during the run becomes a terminal protocol event (e.g.\\n    ``RUN_ERROR`` for AG-UI, ``error`` for langflow) routed through the\\n    adapter; closing the consumer cancels the run.\\n\\n    When the adapter is AG-UI, side-channel ``CustomEvent`` frames carry\\n    the raw Langflow payload alongside the AG-UI translation for the\\n    playground's chat-view. A follow-up retires this once chat-view\\n    consumes the AG-UI ``TEXT_MESSAGE_*`` lifecycle directly.\\n\\n    ``execution_timeout`` bounds the run. It defaults to the settings ceiling,\\n    which is the right budget for a caller with a waiting HTTP client (stream,\\n    public). Background runs pass ``None``: nothing is waiting on them, and their\\n    budget is ``background_job_timeout``, enforced by ``JobRunner`` one layer out.\\n    Resolving the ceiling here for them too nested two budgets, and the inner one\\n    always wins, which made the documented ``background_job_timeout=None``\\n    (\\\"no timeout\\\") silently cap at the sync ceiling instead.\\n    \\\"\\\"\\\"\\n    # EventManager uses put_nowait(), so a plain bounded asyncio.Queue would\\n    # silently drop frames via QueueFull. This adapter keeps memory bounded and\\n    # converts overflow into an explicit stream error + sentinel.\\n    queue = _WorkflowEventQueue(maxsize=_EVENT_QUEUE_MAX_SIZE)\\n    event_manager = create_default_event_manager(queue)\\n    input_request = _single_input_value_request(parsed)\\n    flow_data = FlowDataRequest(**parsed.data) if parsed.data else None\\n    # Ceiling for the modes whose caller is waiting on a socket (stream, public).\\n    # Sync uses its own asyncio.wait_for upstream; background passes None and is\\n    # bounded by JobRunner instead. wait_for(timeout=None) simply awaits.\\n    if isinstance(execution_timeout, _CeilingFromSettings):\\n        execution_timeout = _resolve_execution_timeout()\\n\\n    # Captured from drive()'s exception path so the consumer can yield a\\n    # guaranteed adapter.error_events(...) fallback after the queue loop ends.\\n    # Layered error handling, by design:\\n    #   1. ``event_manager.on_error(...)`` is the cooperative path: the\\n    #      translator turns it into the protocol's terminal-error event (e.g.\\n    #      RUN_ERROR for AG-UI, ``error`` for langflow) so the buffer's\\n    #      structural detector flips the job to FAILED.\\n    #   2. ``adapter.error_events(exc)`` is the dispatcher's guaranteed\\n    #      fallback: emitted from the consumer side when ``generate_flow_events``\\n    #      raises before any cooperative terminal error reaches the queue.\\n    #      Without this yield, an early failure would leave the stream with no\\n    #      terminal error event and the buffer would mark the job COMPLETED.\\n    #   3. The buffer task's ``terminal_error_type`` check fires on either\\n    #      RUN_ERROR source, so a single drive() failure cannot result in a\\n    #      job marked COMPLETED.\\n    drive_error: Exception | None = None\\n\\n    async def drive() -> None:\\n        nonlocal drive_error\\n        try:\\n            # Bound here rather than in the enclosing generator: drive() runs as its own task, so\\n            # the set/reset pair cannot straddle a generator suspension point and leak into the\\n            # consumer task that resumes it.\\n            #\\n            # The queued-run link rides alongside for the same reason and in the same place. It\\n            # is None for a run with a live request above it, and the context manager is a no-op\\n            # then, so this costs a synchronous path nothing.\\n            with (\\n                scoped_model_provider_policy_for_flow(\\n                    provider_policy_flow,\\n                    user_id=current_user.id,\\n                    is_superuser=bool(getattr(current_user, \\\"is_superuser\\\", False)),\\n                ),\\n                execution_protocol(protocol),\\n                queued_trace_link(await _queued_trace_link_for(job_id)),\\n            ):\\n                await asyncio.wait_for(\\n                    generate_flow_events(\\n                        flow_id=flow_id,\\n                        provider_policy_flow=provider_policy_flow,\\n                        background_tasks=background_tasks,\\n                        event_manager=event_manager,\\n                        inputs=input_request,\\n                        data=flow_data,\\n                        files=parsed.files,\\n                        stop_component_id=parsed.stop_component_id,\\n                        start_component_id=parsed.start_component_id,\\n                        # Persist vertex builds only for durable/background jobs. Live streams\\n                   ";
